VRT_L("1re-a-maths-r29",{"duree":20,"titre":"Intégration : une enquête de quartier","accroche":"Des chiffres pour convaincre la mairie.","intro":"Cette séance mobilise les notions du chapitre pour résoudre une situation de la vie courante, comme à la partie B de l'épreuve.","objectifs":["identifier le problème","choisir l'outil mathématique","conclure par une phrase"],"parties":[{"t":"L'outil","html":"<div class='def'><b>Définition</b>Une <strong>enquête statistique</strong> organise des données pour appuyer une décision.</div>"},{"t":"La démarche","verrou":true},{"t":"Un exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"maths","rang":29,"apc":{"module":"Mathématiques de Première A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations de la vie courante pour prendre des décisions","situation":"Un comité de quartier de Garoua relève le temps d'attente de 50 ménages à la borne-fontaine.","tache":"Comment présenter les résultats à la mairie ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-maths-r23",{"duree":20,"titre":"Approche intuitive des limites","accroche":"Ce que devient une fonction très loin.","intro":"La limite décrit le comportement d'une fonction quand x devient très grand ou s'approche d'une valeur interdite.","objectifs":["lire une limite sur un graphique","calculer des limites simples","reconnaître une asymptote"],"parties":[{"t":"Idée","html":"<div class='def'><b>Définition</b>Dire que f(x) tend vers L quand x tend vers +∞, c'est dire que f(x) est aussi proche de L que l'on veut pour x assez grand.</div>"},{"t":"Exemples","html":"<ul><li>1/x tend vers 0 quand x tend vers +∞.</li><li>(2x + 1)/(x − 1) tend vers 2 quand x tend vers +∞.</li><li>1/(x − 1) tend vers +∞ quand x tend vers 1 par la droite.</li></ul>","labo":{"type":"courbe","fn":"inv","xmin":-4,"xmax":4,"ymin":-4,"ymax":4,"x0":1}},{"t":"Asymptotes","html":"<p>Une limite finie en +∞ donne une asymptote horizontale ; une limite infinie en a donne une asymptote verticale.</p>","retenir":"Les termes dominants donnent la limite."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Question de cours.</strong> La limite de 1/x quand x devient très grand est :</p><ol type='a'><li>0</li><li>+∞</li><li>1</li><li>−∞</li></ol><details><summary>Voir la réponse</summary><p><strong>0</strong>. Le quotient devient de plus en plus petit.</p></details><p><strong>Exercice.</strong></p><p>Limite de 3 + 1/x en +∞ ?</p><details><summary>Voir la réponse</summary><p>(Réponse : 3.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Situation.</strong> Le coût moyen de fabrication d'un sac à Bamenda est C(x) = (3x + 600)/x, en milliers de F, pour x sacs.</p><p><strong>Tâche 1.</strong> Que devient C(x) quand x devient très grand ? Interprète.</p><p><strong>Tâche 2.</strong> Que devient C(x) quand x s'approche de 0 ?</p><details><summary>Voir une réponse attendue</summary><p>C(x) = 3 + 600/x tend vers 3 : le coût moyen se rapproche de 3 000 F, asymptote y = 3. Quand x tend vers 0, C(x) tend vers +∞ : les frais fixes pèsent sur peu de sacs.</p></details></div>","retenir":"Savoir-être mobilisé : Esprit critique face aux résultats."}],"revision":["Limite en +∞.","Valeur interdite.","Asymptotes."],"exo":"<p>Limite de 3 + 1/x en +∞ ? <em>(Réponse : 3.)</em></p>","quiz":[{"q":"La limite de 1/x quand x devient très grand est :","r":["0","+∞","1","−∞"],"b":0,"e":"Le quotient devient de plus en plus petit."},{"q":"La limite de x² quand x tend vers +∞ est :","r":["0","+∞","1","−∞"],"b":1,"e":"x² devient aussi grand que l'on veut."},{"q":"La limite de 3 + 1/x en +∞ est :","r":["0","+∞","3","4"],"b":2,"e":"1/x tend vers 0."},{"q":"Le coût moyen 500 + 10 000/x tend, pour un grand tirage, vers :","r":["10 000 F","0 F","10 500 F","500 F"],"b":3,"e":"Les frais fixes se partagent entre de nombreux exemplaires."},{"q":"La limite de −2x en +∞ est :","r":["−∞","+∞","0","−2"],"b":0,"e":"Un nombre négatif multiplié par un grand nombre."},{"q":"Dire que f tend vers 2 en +∞ signifie :","r":["f(2) = 0 et f est croissante sur [2 ; +∞[","f(x) est aussi proche de 2 que l'on veut pour x assez grand","f vaut toujours 2, quel que soit le réel x choisi dans son domaine","f est croissante"],"b":1,"e":"Approche intuitive d'une limite."},{"q":"La limite de (2x + 1)/x en +∞ est :","r":["1","0","2","+∞"],"b":2,"e":"(2x + 1)/x = 2 + 1/x."},{"q":"Une asymptote horizontale y = 2 signifie que la courbe :","r":["coupe la droite y = 2 une seule fois, puis s'en éloigne","est au-dessus de y = 2","est verticale","se rapproche de la droite y = 2"],"b":3,"e":"La distance à la droite tend vers 0."},{"q":"La limite de 1/x quand x tend vers 0 par valeurs positives est :","r":["+∞","0","−∞","1"],"b":0,"e":"On divise 1 par des nombres positifs très petits."},{"q":"Le nombre de clients d'une boutique qui se stabilise autour de 200 illustre :","r":["une limite infinie","une limite finie","une fonction décroissante","une discontinuité"],"b":1,"e":"La valeur se rapproche de 200."}],"c":"1re A","m":"maths","rang":23,"apc":{"module":"Mathématiques de Première A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations de la vie courante pour prendre des décisions","situation":"Le coût moyen de fabrication d'un sac à Bamenda est C(x) = 2 + 500/x, en milliers de F, pour x sacs.","tache":"Que devient ce coût pour une grande production ?"},"gratuit":true});
VRT_L("1re-a-maths-r24",{"duree":20,"titre":"Continuité","accroche":"Une courbe sans saut.","intro":"Une fonction continue se trace sans lever le crayon.","objectifs":["reconnaître une fonction continue","repérer un saut","donner des exemples"],"parties":[{"t":"Idée","html":"<div class='def'><b>Définition</b>Une fonction est <strong>continue</strong> sur un intervalle si sa courbe se trace sans lever le crayon sur cet intervalle.</div>"},{"t":"Exemples","verrou":true},{"t":"Fonction en escalier","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"maths","rang":24,"apc":{"module":"Mathématiques de Première A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations de la vie courante pour prendre des décisions","situation":"La taxe d'un transporteur de colis à Bertoua est de 1 000 F jusqu'à 10 kg, puis 2 000 F jusqu'à 20 kg.","tache":"La fonction taxe est-elle continue ? Justifie."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-maths-r30",{"duree":20,"titre":"Moyenne et médiane","accroche":"Deux façons de résumer une série.","intro":"La moyenne tient compte de toutes les valeurs ; la médiane partage la série en deux moitiés.","objectifs":["calculer une moyenne pondérée","trouver la médiane","comparer moyenne et médiane"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définition</b>La <strong>moyenne</strong> est x̄ = Σnᵢxᵢ / N. La <strong>médiane</strong> est la valeur qui partage la série ordonnée en deux groupes de même effectif.</div>"},{"t":"Exemple discret","verrou":true},{"t":"En classes","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"maths","rang":30,"apc":{"module":"Mathématiques de Première A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations de la vie courante pour prendre des décisions","situation":"Dans une entreprise de Douala, 9 employés gagnent 80 000 F et le directeur 1 000 000 F.","tache":"Quel indicateur décrit le mieux le salaire typique ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-maths-r32",{"duree":20,"titre":"Moyenne et médiane : entraînement","accroche":"Une série de notes en classes.","intro":"Cette séance d'entraînement reprend la notion avec un exercice type d'examen.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>Pour une série en classes, on calcule avec les centres et on interpole pour la médiane.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"maths","rang":32,"apc":{"module":"Mathématiques de Première A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations de la vie courante pour prendre des décisions","situation":"Un conseil de classe à Kumba compare la moyenne et la médiane des notes de mathématiques.","tache":"Que signifie une médiane de 10,42 ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-maths-r31",{"duree":20,"titre":"Variance et écart type","accroche":"Mesurer la dispersion.","intro":"Deux classes peuvent avoir la même moyenne mais des notes plus ou moins dispersées.","objectifs":["calculer la variance","calculer l'écart type","interpréter"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définition</b>La <strong>variance</strong> est V = Σnᵢxᵢ²/N − x̄². L'<strong>écart type</strong> est σ = √V.</div>"},{"t":"Exemple","verrou":true},{"t":"Interprétation","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"maths","rang":31,"apc":{"module":"Mathématiques de Première A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations de la vie courante pour prendre des décisions","situation":"Deux classes de Bafia ont 10 de moyenne ; l'écart type est 2 dans l'une et 5 dans l'autre.","tache":"Compare les deux classes."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-maths-r33",{"duree":20,"titre":"Variance : entraînement","accroche":"Le calcul pas à pas.","intro":"Cette séance d'entraînement reprend la notion avec un exercice type d'examen.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>On organise le calcul dans un tableau : x, n, nx, nx².</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"maths","rang":33,"apc":{"module":"Mathématiques de Première A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations de la vie courante pour prendre des décisions","situation":"Un élève de Mbouda calcule l'écart type de sa classe et trouve un nombre négatif.","tache":"Que dois-tu lui dire ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-maths-r34",{"duree":20,"titre":"Effectifs cumulés croissants et décroissants","accroche":"Combien ont moins de... ? Combien ont au moins... ?","intro":"Les effectifs cumulés répondent aux questions « au plus » et « au moins ».","objectifs":["calculer les ECC","calculer les ECD","répondre à une question"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définition</b>L'<strong>effectif cumulé croissant</strong> d'une classe est la somme des effectifs des classes jusqu'à celle-ci. L'<strong>effectif cumulé décroissant</strong> est la somme des effectifs depuis cette classe jusqu'à la dernière.</div>"},{"t":"Exemple","verrou":true},{"t":"Lecture","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"maths","rang":34,"apc":{"module":"Mathématiques de Première A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations de la vie courante pour prendre des décisions","situation":"Une association de parents de Dschang veut savoir combien d'élèves ont moins de 10 de moyenne.","tache":"Quel tableau utiliser ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-maths-r36",{"duree":20,"titre":"Effectifs cumulés : entraînement","accroche":"Bien lire une borne.","intro":"Cette séance d'entraînement reprend la notion avec un exercice type d'examen.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>L'ECC d'une classe compte les valeurs inférieures à sa borne droite.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"maths","rang":36,"apc":{"module":"Mathématiques de Première A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations de la vie courante pour prendre des décisions","situation":"Un club de football de Garoua classe ses joueurs par âge en classes de 2 ans.","tache":"Comment trouver le nombre de joueurs entre 14 et 18 ans ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-maths-r35",{"duree":20,"titre":"Fréquences cumulées croissantes et décroissantes","accroche":"En pourcentage, c'est plus parlant.","intro":"Les fréquences cumulées expriment en pourcentage les réponses aux questions « au plus » et « au moins ».","objectifs":["calculer les FCC","calculer les FCD","interpréter"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>fréquence cumulée croissante</strong> est l'ECC divisé par l'effectif total ; la <strong>fréquence cumulée décroissante</strong> est l'ECD divisé par l'effectif total.</div>"},{"t":"Exemple","verrou":true},{"t":"Lecture","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"maths","rang":35,"apc":{"module":"Mathématiques de Première A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations de la vie courante pour prendre des décisions","situation":"Un journal de Yaoundé annonce que « moins de la moitié des élèves ont la moyenne ».","tache":"Vérifie avec les fréquences cumulées."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-maths-r37",{"duree":20,"titre":"Fréquences cumulées : entraînement","accroche":"Trouver la médiane avec 50 %.","intro":"Cette séance d'entraînement reprend la notion avec un exercice type d'examen.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>La médiane correspond à une fréquence cumulée de 50 %.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"maths","rang":37,"apc":{"module":"Mathématiques de Première A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations de la vie courante pour prendre des décisions","situation":"Une ONG de Bertoua analyse les revenus mensuels de 200 ménages avec les fréquences cumulées.","tache":"Comment trouver le revenu médian ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-maths-r38",{"duree":20,"titre":"Intégration : résultats d'un examen blanc","accroche":"Des chiffres pour le conseil de classe.","intro":"Cette séance mobilise les notions du chapitre pour résoudre une situation de la vie courante, comme à la partie B de l'épreuve.","objectifs":["identifier le problème","choisir l'outil mathématique","conclure par une phrase"],"parties":[{"t":"L'outil","html":"<div class='def'><b>Définition</b>Les <strong>effectifs et fréquences cumulés</strong> permettent de répondre aux questions sur les seuils.</div>"},{"t":"La démarche","verrou":true},{"t":"Un exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"maths","rang":38,"apc":{"module":"Mathématiques de Première A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations de la vie courante pour prendre des décisions","situation":"Au lycée de Bafoussam, sur 160 élèves de 1re A, 56 ont moins de 8 à l'examen blanc, 40 entre 8 et 10, et le reste au moins 10. Le censeur veut annoncer le taux de réussite aux parents.","tache":"Calcule le pourcentage d'élèves ayant au moins 10 et celui des élèves sous 8."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-maths-r39",{"duree":20,"titre":"Représentations graphiques des séries","accroche":"Un bon graphique vaut mieux qu'un long tableau.","intro":"Chaque type de caractère a sa représentation adaptée.","objectifs":["choisir le bon graphique","construire un diagramme circulaire","construire un polygone des effectifs cumulés"],"parties":[{"t":"Choisir","html":"<div class='def'><b>Définition</b>Diagramme en <strong>bâtons</strong> pour un caractère discret, <strong>histogramme</strong> pour des classes, <strong>diagramme circulaire</strong> pour des parts d'un tout.</div>"},{"t":"Diagramme circulaire","verrou":true},{"t":"Polygone cumulé","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"maths","rang":39,"apc":{"module":"Mathématiques de Première A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations de la vie courante pour prendre des décisions","situation":"La mairie de Kribi présente la répartition des activités de la population : pêche, commerce, fonction publique.","tache":"Quel graphique choisir ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-maths-r40",{"duree":20,"titre":"Intégration : présenter une enquête","accroche":"Un graphique pour la radio communautaire.","intro":"Cette séance mobilise les notions du chapitre pour résoudre une situation de la vie courante, comme à la partie B de l'épreuve.","objectifs":["identifier le problème","choisir l'outil mathématique","conclure par une phrase"],"parties":[{"t":"L'outil","html":"<div class='def'><b>Définition</b>Le <strong>graphique adapté</strong> rend une enquête lisible par tous.</div>"},{"t":"La démarche","verrou":true},{"t":"Un exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"maths","rang":40,"apc":{"module":"Mathématiques de Première A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations de la vie courante pour prendre des décisions","situation":"Une radio communautaire de Mbalmayo a interrogé 200 auditeurs sur leur moment d'écoute préféré.","tache":"Propose un graphique et calcule l'angle du secteur « matin » (90 personnes)."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-maths-r41",{"duree":20,"titre":"Nombre dérivé et tangente","accroche":"La pente d'une courbe en un point.","intro":"Le nombre dérivé mesure la vitesse de variation d'une fonction en un point.","objectifs":["calculer un nombre dérivé","écrire l'équation d'une tangente","interpréter"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>nombre dérivé</strong> f'(a) est la limite du taux (f(a + h) − f(a))/h quand h tend vers 0. C'est la pente de la tangente au point d'abscisse a.</div>"},{"t":"Tangente","html":"<p class='formule'>y = f'(a)(x − a) + f(a)</p><p>Pour f(x) = x² en 3 : f'(3) = 6, tangente y = 6x − 9.</p>","labo":{"type":"courbe","fn":"x2","xmin":-3,"xmax":3,"ymin":-2,"ymax":9,"x0":1}},{"t":"Interprétation","html":"<p>f'(a) > 0 : la fonction monte en a ; f'(a) &lt; 0 : elle descend.</p>","retenir":"Pente de la tangente = f'(a)."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Question de cours.</strong> Le nombre dérivé f'(a) est :</p><ol type='a'><li>le coefficient directeur de la tangente au point d'abscisse a</li><li>la valeur f(a) de la fonction au point d'abscisse a</li><li>l'ordonnée à l'origine de la courbe représentative de f</li><li>l'aire sous la courbe entre l'origine et le point d'abscisse a</li></ol><details><summary>Voir la réponse</summary><p><strong>le coefficient directeur de la tangente au point d'abscisse a</strong>. Il mesure la pente de la courbe en a.</p></details><p><strong>Exercice.</strong></p><p>Pour f(x) = x², calcule f'(2).</p><details><summary>Voir la réponse</summary><p>(Réponse : 4.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Situation.</strong> Soit f(x) = x² − 3x, qui modélise la position d'un objet.</p><p><strong>Tâche 1.</strong> Calcule f'(2).</p><p><strong>Tâche 2.</strong> Écris l'équation de la tangente à la courbe au point d'abscisse 2.</p><details><summary>Voir une réponse attendue</summary><p>f'(x) = 2x − 3, f'(2) = 1 ; f(2) = −2. Tangente : y = 1(x − 2) − 2 = x − 4.</p></details></div>","retenir":"Savoir-être mobilisé : Rigueur dans la rédaction."}],"revision":["Taux de variation.","Tangente.","Signe de f'(a)."],"exo":"<p>Pour f(x) = x², calcule f'(2). <em>(Réponse : 4.)</em></p>","quiz":[{"q":"Le nombre dérivé f'(a) est :","r":["le coefficient directeur de la tangente au point d'abscisse a","la valeur f(a) de la fonction au point d'abscisse a","l'ordonnée à l'origine de la courbe représentative de f","l'aire sous la courbe entre l'origine et le point d'abscisse a"],"b":0,"e":"Il mesure la pente de la courbe en a."},{"q":"Le nombre dérivé se calcule comme la limite :","r":["de f(a + h) − f(a) quand h tend vers l'infini","de (f(a + h) − f(a))/h quand h tend vers 0","de f(h)","de h/f(a)"],"b":1,"e":"Taux d'accroissement."},{"q":"Pour f(x) = x², f'(3) vaut :","r":["9","3","6","2"],"b":2,"e":"f'(x) = 2x, donc f'(3) = 6."},{"q":"L'équation de la tangente en a est :","r":["y = f(a)(x − a) + f'(a)","y = f'(a)","y = ax","y = f'(a)(x − a) + f(a)"],"b":3,"e":"Droite de pente f'(a) passant par le point de la courbe."},{"q":"La tangente à y = x² en x = 1 a pour équation :","r":["y = 2x − 1","y = 2x + 1","y = x","y = x − 1"],"b":0,"e":"f(1) = 1, f'(1) = 2 : y = 2(x − 1) + 1."},{"q":"Une tangente horizontale correspond à :","r":["un nombre dérivé égal à 1","un nombre dérivé nul","une asymptote","un point d'intersection avec l'axe"],"b":1,"e":"Une droite horizontale a une pente nulle, donc f'(a) = 0."},{"q":"Si f'(a) > 0, la courbe au voisinage de a est :","r":["descendante","horizontale","montante","verticale"],"b":2,"e":"La pente est positive."},{"q":"Pour f(x) = 3x + 2, f'(a) vaut pour tout a :","r":["2","0","5","3"],"b":3,"e":"La pente d'une droite est constante."},{"q":"Le taux d'accroissement de f(x) = x² entre 2 et 2 + h vaut :","r":["4 + h","4","h","2 + h"],"b":0,"e":"((2 + h)² − 4)/h = (4h + h²)/h."},{"q":"La vitesse instantanée d'un objet est :","r":["la position du mobile à cet instant, en mètres","le nombre dérivé de la position par rapport au temps","la distance totale parcourue depuis le départ du mobile","le temps"],"b":1,"e":"Interprétation physique."}],"c":"1re A","m":"maths","rang":41,"apc":{"module":"Mathématiques de Première A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations de la vie courante pour prendre des décisions","situation":"Le nombre de clients d'une boutique de Douala suit f(t) = t², t en heures après l'ouverture.","tache":"Quelle est la vitesse d'arrivée des clients à t = 3 h ?"},"gratuit":true});
VRT_L("1re-a-maths-r43",{"duree":20,"titre":"Nombre dérivé : entraînement","accroche":"Une tangente pas à pas.","intro":"Cette séance d'entraînement reprend la notion avec un exercice type d'examen.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>On calcule f(a), puis f'(a), puis on remplace dans la formule.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"maths","rang":43,"apc":{"module":"Mathématiques de Première A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations de la vie courante pour prendre des décisions","situation":"Un graphique des ventes d'une boutique de Kumba suit f(x) = 3x² − 2x + 1.","tache":"Donne la tendance au point x = 1."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-maths-r42",{"duree":20,"titre":"Dérivées des fonctions élémentaires","accroche":"Un formulaire à connaître.","intro":"Quelques dérivées usuelles suffisent pour étudier la plupart des fonctions du programme.","objectifs":["connaître les dérivées usuelles","dériver un polynôme","dériver 1/x et √x"],"parties":[{"t":"Le formulaire","html":"<div class='def'><b>Définition</b>(k)' = 0 ; (x)' = 1 ; (x²)' = 2x ; (x³)' = 3x² ; (xⁿ)' = nxⁿ⁻¹ ; (1/x)' = −1/x² ; (√x)' = 1/(2√x).</div>"},{"t":"Polynômes","verrou":true},{"t":"Attention","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"maths","rang":42,"apc":{"module":"Mathématiques de Première A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations de la vie courante pour prendre des décisions","situation":"Un comptable de Bafang modélise un coût par C(x) = 2x³ − 5x + 1.","tache":"Calcule le coût marginal C'(x)."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-maths-r44",{"duree":20,"titre":"Dérivées : entraînement","accroche":"Racine carrée et inverse.","intro":"Cette séance d'entraînement reprend la notion avec un exercice type d'examen.","objectifs":["reconnaître le type d'exercice","rédiger la méthode","éviter le piège classique"],"parties":[{"t":"Le rappel","html":"<div class='def'><b>À retenir</b>(√x)' = 1/(2√x) pour x > 0 ; (1/x)' = −1/x² pour x ≠ 0.</div>"},{"t":"Exercice résolu","verrou":true},{"t":"Le piège à éviter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"maths","rang":44,"apc":{"module":"Mathématiques de Première A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations de la vie courante pour prendre des décisions","situation":"Le rendement d'une parcelle de maïs à Foumbot suit f(x) = 4√x, x étant la quantité d'engrais.","tache":"Donne la vitesse de variation du rendement."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-maths-r45",{"duree":20,"titre":"Dérivées et opérations","accroche":"Somme, produit, quotient.","intro":"Les règles opératoires permettent de dériver des fonctions construites à partir des fonctions usuelles.","objectifs":["dériver une somme et un produit par un réel","dériver un produit","dériver un quotient"],"parties":[{"t":"Les règles","html":"<div class='def'><b>Définition</b>(u + v)' = u' + v' ; (ku)' = ku' ; (uv)' = u'v + uv' ; (u/v)' = (u'v − uv')/v².</div>"},{"t":"Produit","verrou":true},{"t":"Quotient","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"maths","rang":45,"apc":{"module":"Mathématiques de Première A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations de la vie courante pour prendre des décisions","situation":"Le prix de vente moyen d'un tissu à Mokolo suit p(x) = (2x + 1)/(x + 1).","tache":"Ce prix augmente-t-il avec x ? Justifie."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-maths-r46",{"duree":20,"titre":"Intégration : maximiser une recette","accroche":"Le bon prix pour la meilleure recette.","intro":"Cette séance mobilise les notions du chapitre pour résoudre une situation de la vie courante, comme à la partie B de l'épreuve.","objectifs":["identifier le problème","choisir l'outil mathématique","conclure par une phrase"],"parties":[{"t":"L'outil","html":"<div class='def'><b>Définition</b>Le <strong>maximum</strong> d'une fonction se trouve là où sa dérivée s'annule en changeant de signe.</div>"},{"t":"La démarche","verrou":true},{"t":"Un exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"maths","rang":46,"apc":{"module":"Mathématiques de Première A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations de la vie courante pour prendre des décisions","situation":"Une coopérative de Dschang modélise sa recette par R(x) = −2x² + 80x, en milliers de F, x étant le prix en centaines de F.","tache":"Quel prix choisir pour une recette maximale ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-maths-r47",{"duree":20,"titre":"Étude de fonctions sur un intervalle","accroche":"Du calcul de dérivée au tableau de variation.","intro":"Étudier une fonction sur un intervalle borné, c'est dresser son tableau de variation et tracer sa courbe.","objectifs":["calculer la dérivée","dresser le tableau de variation","tracer la courbe"],"parties":[{"t":"Le plan","html":"<div class='def'><b>Définition</b><strong>Étudier</strong> f sur [a ; b] : calculer f', étudier son signe, dresser le tableau de variation avec les valeurs aux bornes, tracer la courbe.</div>"},{"t":"Polynôme","verrou":true},{"t":"Homographique","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"maths","rang":47,"apc":{"module":"Mathématiques de Première A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations de la vie courante pour prendre des décisions","situation":"Le niveau de l'eau d'un réservoir de Bamessing, mesuré par rapport à un repère, suit f(t) = t² − 4t + 3 (en mètres) entre 0 et 5 heures.","tache":"Quand le niveau est-il le plus bas ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-maths-r48",{"duree":20,"titre":"Fonctions et transformations usuelles","accroche":"Déplacer une courbe connue.","intro":"À partir de la courbe de f, on obtient celles de f(x) + b, f(x − a), −f(x) et |f(x)| par des transformations simples.","objectifs":["reconnaître une translation","reconnaître une symétrie","tracer |f|"],"parties":[{"t":"Les transformations","html":"<div class='def'><b>Définition</b>La courbe de <strong>f(x) + b</strong> est translatée de b verticalement ; celle de <strong>f(x − a)</strong> est translatée de a horizontalement ; celle de <strong>−f(x)</strong> est symétrique par rapport à l'axe des abscisses.</div>"},{"t":"Exemples","verrou":true},{"t":"Valeur absolue","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"maths","rang":48,"apc":{"module":"Mathématiques de Première A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations de la vie courante pour prendre des décisions","situation":"Un graphiste de Yaoundé décale un logo en forme de parabole y = x² de 2 unités vers la droite et 3 vers le haut.","tache":"Donne l'équation de la nouvelle courbe."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-maths-r49",{"duree":20,"titre":"Intégration : lire et transformer une courbe","accroche":"Un graphique de ventes déplacé.","intro":"Cette séance mobilise les notions du chapitre pour résoudre une situation de la vie courante, comme à la partie B de l'épreuve.","objectifs":["identifier le problème","choisir l'outil mathématique","conclure par une phrase"],"parties":[{"t":"L'outil","html":"<div class='def'><b>Définition</b>Les <strong>transformations</strong> d'une courbe traduisent des changements simples de la situation.</div>"},{"t":"La démarche","verrou":true},{"t":"Un exemple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"maths","rang":49,"apc":{"module":"Mathématiques de Première A","famille":"Organisation des données et prise de décision dans la vie économique et sociale","agir":"Modéliser des situations de la vie courante pour prendre des décisions","situation":"Une boulangerie de Garoua décale l'ouverture de 2 heures ; sa courbe d'affluence f(t) devient f(t − 2).","tache":"Décris la transformation de la courbe."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-ecm-r01",{"duree":20,"titre":"Les droits de l'homme","accroche":"Des droits pour chaque être humain, partout.","intro":"Les droits de l'homme sont les droits que toute personne possède du seul fait qu'elle est un être humain. Ils sont proclamés par des textes internationaux et par la Constitution camerounaise.","objectifs":["définir les droits de l'homme","en connaître les caractères","citer les textes qui les proclament"],"parties":[{"t":"Définition et caractères","html":"<div class='def'><b>Définition</b>Les <strong>droits de l'homme</strong> sont l'ensemble des droits et libertés fondamentaux reconnus à toute personne humaine, sans distinction de sexe, d'origine, de religion ou d'opinion.</div><p>Ils sont <strong>universels</strong> (valables pour tous), <strong>inaliénables</strong> (on ne peut pas les céder), <strong>indivisibles</strong> et <strong>interdépendants</strong> (tous se tiennent).</p>"},{"t":"Les catégories de droits","html":"<ul><li><strong>Droits civils et politiques</strong> : droit à la vie, liberté d'expression, droit de vote, procès équitable.</li><li><strong>Droits économiques, sociaux et culturels</strong> : droit à l'éducation, à la santé, au travail, au logement.</li><li><strong>Droits de solidarité</strong> : droit à la paix, au développement, à un environnement sain.</li></ul>","retenir":"Trois générations de droits : civils et politiques, économiques et sociaux, de solidarité.","labo":{"type":"trier","invite":"Choisis une catégorie de droits.","items":[["Civils et politiques","vie, expression, vote, procès équitable."],["Économiques, sociaux et culturels","éducation, santé, travail, logement."],["De solidarité","paix, développement, environnement sain."]]}},{"t":"Les textes fondamentaux","html":"<ul><li>la <strong>Déclaration universelle des droits de l'homme</strong>, adoptée par l'ONU le 10 décembre 1948 ;</li><li>la <strong>Charte africaine des droits de l'homme et des peuples</strong>, adoptée en 1981 ;</li><li>la <strong>Convention relative aux droits de l'enfant</strong> de 1989 ;</li><li>le <strong>préambule de la Constitution</strong> camerounaise du 18 janvier 1996.</li></ul><div class='attention'><b>Attention</b>à chaque droit correspond un devoir : respecter les droits des autres.</div>"},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Première partie : l'évaluation des ressources</h3><p><strong>Vérification des savoirs.</strong> Les droits de l'homme sont reconnus à toute personne :</p><ol type='a'><li>du seul fait qu'elle est un être humain</li><li>seulement si elle paie ses impôts</li><li>à partir de l'âge de la majorité électorale</li><li>seulement si elle est de nationalité camerounaise</li></ol><details><summary>Voir la réponse</summary><p><strong>du seul fait qu'elle est un être humain</strong>. Ils sont universels.</p></details><p><strong>Vérification des savoir-faire.</strong></p><p>Le droit à l'éducation appartient à quelle catégorie ?</p><details><summary>Voir la réponse</summary><p>(Réponse : aux droits économiques, sociaux et culturels.)</p></details><h3>Deuxième partie : l'évaluation de l'agir compétent</h3><p><strong>Situation-problème.</strong> Document : rapport d'une ONG signalant des enfants travaillant dans une carrière de pierres à la périphérie de Yaoundé, sans scolarisation.</p><p><strong>Tâche 1.</strong> Identifie deux droits de l'enfant violés.</p><p><strong>Tâche 2.</strong> Propose deux actions et les acteurs à mobiliser.</p><p><em>Présentation : 2 points.</em></p><details><summary>Voir une réponse attendue</summary><p>Droit à l'éducation et droit d'être protégé contre l'exploitation économique. Actions : signalement aux services des Affaires sociales et à la CDHC ; campagne de sensibilisation des parents avec les chefs de quartier et une aide à la scolarisation.</p></details></div>","retenir":"Savoir-être mobilisé : Tolérance et respect de l'autre."}],"revision":["Droits universels, inaliénables, indivisibles.","Civils et politiques ; économiques, sociaux et culturels ; de solidarité.","DUDH 1948, Charte africaine 1981, CDE 1989, Constitution 1996."],"exo":"<p>Le droit à l'éducation appartient à quelle catégorie ? <em>(Réponse : aux droits économiques, sociaux et culturels.)</em></p>","quiz":[{"q":"Les droits de l'homme sont reconnus à toute personne :","r":["du seul fait qu'elle est un être humain","seulement si elle paie ses impôts","à partir de l'âge de la majorité électorale","seulement si elle est de nationalité camerounaise"],"b":0,"e":"Ils sont universels."},{"q":"La Déclaration universelle des droits de l'homme a été adoptée le :","r":["24 octobre 1945","10 décembre 1948","25 mai 1963","18 janvier 1996"],"b":1,"e":"Adoptée par l'Assemblée générale de l'ONU à Paris."},{"q":"Dire que les droits de l'homme sont inaliénables signifie :","r":["qu'ils ne concernent que les étrangers","qu'ils changent selon les pays","qu'on ne peut pas les céder ni les perdre","qu'on peut les vendre à un tiers"],"b":2,"e":"Personne ne peut y renoncer ni en être privé arbitrairement."},{"q":"Le droit à l'éducation fait partie des droits :","r":["civils et politiques uniquement","de solidarité entre les peuples","réservés aux adultes","économiques, sociaux et culturels"],"b":3,"e":"Comme la santé, le travail, le logement."},{"q":"Le droit de vote fait partie des droits :","r":["civils et politiques","économiques et sociaux","de solidarité","culturels seulement"],"b":0,"e":"Il permet de participer à la vie politique."},{"q":"Le droit à un environnement sain est un droit :","r":["civil et politique","de solidarité","économique et individuel","réservé aux États"],"b":1,"e":"Les droits de solidarité concernent toute la collectivité."},{"q":"La Charte africaine des droits de l'homme et des peuples a été adoptée en :","r":["1948","1963","1981","2002"],"b":2,"e":"Elle a été adoptée à Nairobi et est entrée en vigueur en 1986."},{"q":"La Convention relative aux droits de l'enfant date de :","r":["1948","1996","2000","1989"],"b":3,"e":"Adoptée par l'ONU le 20 novembre 1989."},{"q":"Au Cameroun, les droits fondamentaux sont proclamés dans :","r":["le préambule de la Constitution","le règlement intérieur des écoles","le Code de la route","les statuts des partis politiques"],"b":0,"e":"Le préambule de la Constitution de 1996 les énumère."},{"q":"À chaque droit correspond :","r":["un impôt particulier à payer chaque année à l'État","le devoir de respecter les droits des autres","une autorisation du chef de l'État","un privilège réservé à certains"],"b":1,"e":"Droits et devoirs vont ensemble."}],"c":"1re A","m":"ecm","rang":1,"apc":{"module":"Les droits humains","famille":"Vie citoyenne et droits humains","agir":"Promouvoir et défendre les droits humains dans son milieu","situation":"Dans un village du Mayo-Tsanaga, une fille de 13 ans est retirée de l'école par son père qui veut la marier ; sa camarade de classe s'indigne mais ne sait pas comment réagir.","tache":"Identifie deux droits de l'enfant violés et indique deux personnes ou structures auxquelles la camarade peut s'adresser."},"gratuit":true});
VRT_L("1re-a-ecm-r02",{"duree":20,"titre":"Les institutions de protection des droits de l'homme","accroche":"Qui défend nos droits quand ils sont violés ?","intro":"Des institutions nationales et internationales veillent au respect des droits de l'homme : elles reçoivent les plaintes, enquêtent, sensibilisent et sanctionnent.","objectifs":["citer des institutions nationales de protection","citer des institutions internationales et africaines","savoir comment les saisir"],"parties":[{"t":"Au Cameroun","html":"<div class='def'><b>Définition</b>Une <strong>institution de protection des droits de l'homme</strong> est un organisme chargé de promouvoir les droits, de recevoir les plaintes et de faire cesser les violations.</div><ul><li>la <strong>Commission des droits de l'homme du Cameroun</strong> (CDHC), créée en 2019 pour remplacer la Commission nationale des droits de l'homme et des libertés ;</li><li>les <strong>tribunaux</strong>, gardiens des libertés individuelles ;</li><li>le <strong>Parlement</strong>, qui vote les lois protectrices ;</li><li>les <strong>ministères</strong> chargés des Affaires sociales et de la Promotion de la femme et de la famille ;</li><li>les <strong>associations et ONG</strong> de défense des droits.</li></ul>"},{"t":"Au niveau africain et mondial","verrou":true},{"t":"Saisir une institution","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"ecm","rang":2,"apc":{"module":"Les droits humains","famille":"Vie citoyenne et droits humains","agir":"Promouvoir et défendre les droits humains dans son milieu","situation":"Moussa, 17 ans, a été gardé à vue quatre jours dans un commissariat de Maroua sans voir de magistrat ni pouvoir prévenir sa famille ; son oncle veut « régler l'affaire avec de l'argent ».","tache":"Indique les droits de Moussa qui ont été méconnus et propose à son oncle une démarche légale."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-ecm-r03",{"duree":20,"titre":"TD : étude d'une structure locale de promotion des droits de l'homme","accroche":"Enquêter près de chez soi.","intro":"Ce travail dirigé conduit à identifier et étudier une structure de sa localité qui promeut les droits de l'homme : centre social, association, clinique juridique, antenne de la CDHC.","objectifs":["préparer une enquête","présenter une structure","évaluer son action"],"parties":[{"t":"Préparer l'enquête","html":"<div class='def'><b>Définition</b>Une <strong>enquête</strong> est une recherche d'informations auprès de personnes et de documents, menée avec un questionnaire préparé et une méthode.</div><ol><li>Choisir la structure et prendre rendez-vous.</li><li>Rédiger un questionnaire : missions, public, activités, moyens, difficultés.</li><li>Répartir les rôles : questions, prise de notes, photographies autorisées.</li></ol>"},{"t":"Présenter la structure","verrou":true},{"t":"Évaluer et restituer","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"ecm","rang":3,"apc":{"module":"Les droits humains","famille":"Vie citoyenne et droits humains","agir":"Promouvoir et défendre les droits humains dans son milieu","situation":"Ton groupe doit enquêter sur le centre social de ton arrondissement. Le responsable n'accorde que 30 minutes d'entretien et refuse que l'on photographie les personnes accueillies.","tache":"Rédige cinq questions prioritaires pour l'entretien et explique comment respecter la règle sur les photographies."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-ecm-r04",{"duree":20,"titre":"Le concept d'intégrité morale","accroche":"Être droit même quand personne ne regarde.","intro":"L'intégrité morale est une qualité essentielle du citoyen et de l'agent public. Son absence ouvre la porte à la corruption, à la fraude et au détournement.","objectifs":["définir l'intégrité morale","identifier ses manifestations et ses contraires","en mesurer l'importance pour la société"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>L'<strong>intégrité morale</strong> est la qualité d'une personne honnête, droite et incorruptible, qui agit conformément aux règles et à sa conscience, même lorsqu'elle pourrait tirer profit d'un manquement.</div><p>Elle se manifeste par l'<strong>honnêteté</strong>, la <strong>probité</strong>, le <strong>respect de la parole donnée</strong>, la <strong>loyauté</strong> et le <strong>sens du bien commun</strong>.</p>"},{"t":"Les atteintes à l'intégrité","verrou":true},{"t":"Pourquoi l'intégrité est-elle essentielle ?","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"ecm","rang":4,"apc":{"module":"L'intégrité morale","famille":"Vie citoyenne et morale","agir":"Adopter et promouvoir un comportement intègre","situation":"À l'approche du Probatoire, un message circule dans ta classe : « sujets disponibles contre 5 000 F ». Sept camarades veulent payer ; ta meilleure amie hésite.","tache":"Rédige un message de huit lignes pour la convaincre de refuser, en utilisant deux arguments liés à l'intégrité morale."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-ecm-r05",{"duree":20,"titre":"Les institutions de promotion et de préservation de l'intégrité morale au Cameroun","accroche":"Les gardiens de la probité publique.","intro":"Pour lutter contre la corruption et les détournements, le Cameroun a mis en place des institutions de prévention, de contrôle et de répression.","objectifs":["citer les institutions de lutte contre la corruption","préciser le rôle de chacune","savoir dénoncer un acte de corruption"],"parties":[{"t":"Les institutions de prévention","html":"<div class='def'><b>Définition</b>Une <strong>institution de préservation de l'intégrité morale</strong> est un organisme public chargé de prévenir, contrôler ou sanctionner les atteintes à la probité.</div><ul><li>la <strong>Commission nationale anti-corruption</strong> (CONAC), créée en 2006 : prévention, enquêtes, sensibilisation, réception des dénonciations ;</li><li>les <strong>cellules de lutte contre la corruption</strong> dans les ministères ;</li><li>l'<strong>Agence nationale d'investigation financière</strong> (ANIF) contre le blanchiment.</li></ul>"},{"t":"Les institutions de contrôle et de répression","verrou":true},{"t":"Dénoncer un acte de corruption","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"ecm","rang":5,"apc":{"module":"L'intégrité morale","famille":"Vie citoyenne et morale","agir":"Adopter et promouvoir un comportement intègre","situation":"Pour obtenir l'acte de naissance de son fils, une mère de Sangmélima s'entend dire par un agent : « reviens demain avec 3 000 F, sinon ton dossier dort ». L'acte est en principe délivré gratuitement.","tache":"Identifie l'infraction commise et indique à la mère deux institutions qu'elle peut saisir, avec la démarche à suivre."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-ecm-r06",{"duree":20,"titre":"TD : l'intégrité morale en milieu scolaire","accroche":"L'école, première école de l'intégrité.","intro":"Le lycée est un lieu où l'on apprend aussi à être honnête. Ce travail dirigé repère les atteintes à l'intégrité en milieu scolaire et construit des réponses.","objectifs":["identifier les atteintes à l'intégrité à l'école","en analyser les causes et les conséquences","élaborer une charte d'intégrité"],"parties":[{"t":"Les atteintes en milieu scolaire","html":"<div class='def'><b>Définition</b>Une <strong>atteinte à l'intégrité en milieu scolaire</strong> est tout comportement malhonnête qui fausse l'évaluation, l'accès aux services ou la vie commune à l'école.</div><ul><li>la tricherie aux devoirs et aux examens ;</li><li>l'achat de notes ou de places ;</li><li>la falsification de bulletins ou de signatures ;</li><li>le vol de matériel ;</li><li>le harcèlement en échange de notes.</li></ul>"},{"t":"Causes et conséquences","verrou":true},{"t":"Une charte d'intégrité","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"ecm","rang":6,"apc":{"module":"L'intégrité morale","famille":"Vie citoyenne et morale","agir":"Adopter et promouvoir un comportement intègre","situation":"Lors d'une composition, l'enseignant de ton lycée de Bertoua découvre que 18 copies sur 52 sont identiques. Le club d'éducation à la citoyenneté veut agir avant les examens officiels.","tache":"Propose une charte de cinq engagements et deux actions du club pour la faire vivre."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-ecm-r07",{"duree":20,"titre":"Les médias et leur impact sur l'opinion publique","accroche":"Ce que nous pensons dépend de ce que nous lisons.","intro":"Les médias informent, éduquent et divertissent ; ils façonnent aussi l'opinion publique, pour le meilleur et parfois pour le pire.","objectifs":["définir les médias et l'opinion publique","citer les types de médias","analyser leur influence"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définition</b>Les <strong>médias</strong> sont les moyens de diffusion de l'information auprès d'un large public : presse écrite, radio, télévision, internet et réseaux sociaux. L'<strong>opinion publique</strong> est l'ensemble des idées et jugements partagés par une grande partie de la population sur une question.</div>"},{"t":"Les rôles des médias","verrou":true},{"t":"Impacts positifs et négatifs","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"ecm","rang":7,"apc":{"module":"Les médias et l'opinion publique","famille":"Vie citoyenne et communication","agir":"Exploiter les médias avec esprit critique","situation":"Un message audio partagé 2 000 fois sur WhatsApp affirme qu'un vaccin distribué gratuitement à Douala « rend stérile ». Dans ton quartier, des parents refusent de faire vacciner leurs enfants.","tache":"Explique l'impact de ce message sur l'opinion publique et propose trois gestes pour lutter contre cette fausse nouvelle."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-ecm-r08",{"duree":20,"titre":"La protection de l'opinion publique au Cameroun","accroche":"Liberté de la presse et responsabilité.","intro":"La liberté de communication est garantie, mais elle s'exerce dans le respect de la loi. Des textes et des institutions protègent le public contre la manipulation et les dérives.","objectifs":["connaître le cadre juridique de la communication","citer les institutions de régulation","identifier les limites de la liberté d'expression"],"parties":[{"t":"Le cadre juridique","html":"<div class='def'><b>Définition</b>La <strong>protection de l'opinion publique</strong> désigne l'ensemble des règles et institutions qui garantissent une information libre, pluraliste et responsable, et protègent le public contre les abus.</div><p>La <strong>loi du 19 décembre 1990</strong> sur la liberté de communication sociale organise la presse et l'audiovisuel ; le Code pénal sanctionne la diffamation, la propagation de fausses nouvelles et l'incitation à la haine. La loi de 2010 sur la cybersécurité et la cybercriminalité encadre internet.</p>"},{"t":"Les institutions de régulation","verrou":true},{"t":"Les limites de la liberté d'expression","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"ecm","rang":8,"apc":{"module":"Les médias et l'opinion publique","famille":"Vie citoyenne et communication","agir":"Exploiter les médias avec esprit critique","situation":"Un blogueur de Bafoussam publie la photo d'un enseignant de ton lycée avec la légende « voleur de notes », sans aucune preuve ; la publication est partagée 600 fois.","tache":"Explique pourquoi cette publication dépasse les limites de la liberté d'expression et indique les recours possibles pour l'enseignant."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-ecm-r09",{"duree":20,"titre":"TD : la publicité dans les médias","accroche":"Décoder un message qui veut nous faire acheter.","intro":"La publicité finance de nombreux médias. Ce travail dirigé apprend à analyser une publicité et à repérer ses procédés de persuasion.","objectifs":["définir la publicité","analyser une affiche ou un spot","adopter un comportement de consommateur averti"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>publicité</strong> est un message diffusé dans les médias pour faire connaître un produit, un service ou une idée et inciter le public à l'acheter ou à l'adopter.</div><p>On distingue la publicité <strong>commerciale</strong> et la publicité <strong>institutionnelle</strong> ou d'intérêt général (campagne contre le paludisme, pour la sécurité routière).</p>"},{"t":"Analyser une publicité","verrou":true},{"t":"Le consommateur averti","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"ecm","rang":9,"apc":{"module":"Les médias et l'opinion publique","famille":"Vie citoyenne et communication","agir":"Exploiter les médias avec esprit critique","situation":"Une affiche de Douala vante une crème qui « éclaircit la peau en 7 jours, 100 % sans danger », avec la photo d'une jeune femme souriante et le slogan « Brille comme une star ».","tache":"Analyse cette publicité (cible, procédés) et explique pourquoi elle peut être dangereuse et trompeuse."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-ecm-r10",{"duree":20,"titre":"Les atteintes à l'intégrité physique, morale et au patrimoine","accroche":"Protéger la personne et ses biens.","intro":"La loi protège la personne humaine dans son corps, dans son honneur et dans ses biens. Le Code pénal du 12 juillet 2016 punit les atteintes à ces droits.","objectifs":["distinguer les trois types d'atteintes","en donner des exemples","connaître les conduites à tenir"],"parties":[{"t":"Les atteintes à l'intégrité physique","html":"<div class='def'><b>Définition</b>Une <strong>atteinte à l'intégrité physique</strong> est un acte qui blesse le corps d'une personne ou met sa vie en danger.</div><p>Exemples : coups et blessures, meurtre, viol, mutilations génitales, châtiments corporels excessifs, bagarres.</p>"},{"t":"Les atteintes à l'intégrité morale","html":"<p>Elles blessent la dignité, l'honneur ou l'équilibre psychologique : injures, diffamation, menaces, harcèlement (y compris sur internet), humiliations, discriminations.</p><p>Les <strong>femmes</strong> en sont souvent victimes : violences conjugales, mariages forcés ou précoces, mutilations, et dans le monde du travail discrimination à l'embauche, inégalités de salaire, harcèlement sexuel, licenciement pour grossesse, interdits par le Code pénal et le Code du travail. Des associations comme l'ALVF (Association de lutte contre les violences faites aux femmes) accompagnent les victimes.</p>","retenir":"Les mots et les écrans peuvent aussi blesser.","labo":{"type":"trier","invite":"Choisis une atteinte.","items":[["Intégrité physique","coups, blessures, viol, mutilations."],["Intégrité morale","injures, diffamation, harcèlement."],["Patrimoine","vol, escroquerie, destruction de biens."]]}},{"t":"Les atteintes au patrimoine","html":"<p>Elles visent les biens d'une personne ou de la collectivité : vol, escroquerie, abus de confiance, destruction de biens, détournement de biens publics, incendie volontaire.</p><p><strong>Conduite à tenir</strong> : protéger la victime, alerter (police 117, gendarmerie, sapeurs-pompiers 118), conserver les preuves, porter plainte.</p><div class='attention'><b>Attention</b>la vengeance personnelle et la « justice populaire » sont elles-mêmes des infractions.</div>"},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Première partie : l'évaluation des ressources</h3><p><strong>Vérification des savoirs.</strong> Les coups et blessures sont une atteinte à l'intégrité :</p><ol type='a'><li>morale</li><li>patrimoniale</li><li>physique</li><li>électorale</li></ol><details><summary>Voir la réponse</summary><p><strong>physique</strong>. Ils blessent le corps.</p></details><p><strong>Vérification des savoir-faire.</strong></p><p>Un élève publie des moqueries répétées sur un camarade dans un groupe de classe. Quelle atteinte commet-il ?</p><details><summary>Voir la réponse</summary><p>(Réponse : une atteinte à l'intégrité morale, par cyberharcèlement.)</p></details><h3>Deuxième partie : l'évaluation de l'agir compétent</h3><p><strong>Situation-problème.</strong> Dans un quartier de Douala, un élève est frappé et filmé par des camarades ; la vidéo est partagée avec des moqueries ; son téléphone lui est volé.</p><p><strong>Tâche 1.</strong> Identifie les trois types d'atteintes.</p><p><strong>Tâche 2.</strong> Indique la conduite à tenir pour un témoin.</p><p><em>Présentation : 2 points.</em></p><details><summary>Voir une réponse attendue</summary><p>Physique (coups), morale (vidéo humiliante, moqueries), patrimoine (vol du téléphone). Le témoin protège la victime, alerte un adulte ou la police, ne partage pas la vidéo et témoigne.</p></details></div>","retenir":"Savoir-être mobilisé : Sens de la responsabilité."}],"revision":["Physique : coups, blessures, viol, mutilations.","Morale : injures, diffamation, harcèlement, discrimination.","Patrimoine : vol, escroquerie, destruction, détournement ; alerter, preuves, plainte."],"exo":"<p>Un élève publie des moqueries répétées sur un camarade dans un groupe de classe. Quelle atteinte commet-il ? <em>(Réponse : une atteinte à l'intégrité morale, par cyberharcèlement.)</em></p>","quiz":[{"q":"Les coups et blessures sont une atteinte à l'intégrité :","r":["morale","patrimoniale","physique","électorale"],"b":2,"e":"Ils blessent le corps."},{"q":"L'injure est une atteinte à l'intégrité :","r":["physique","au patrimoine","territoriale","morale"],"b":3,"e":"Elle blesse la dignité."},{"q":"Le vol est une atteinte :","r":["au patrimoine","à l'intégrité physique","à l'intégrité morale seulement","au droit de vote"],"b":0,"e":"Il vise les biens."},{"q":"Le Code pénal camerounais en vigueur date du :","r":["19 décembre 1990","12 juillet 2016","14 août 1992","18 janvier 1996"],"b":1,"e":"Loi n° 2016/007 du 12 juillet 2016."},{"q":"Le cyberharcèlement est une atteinte à l'intégrité :","r":["patrimoniale","physique","morale","territoriale"],"b":2,"e":"Les mots en ligne peuvent blesser."},{"q":"L'escroquerie consiste à :","r":["frapper une personne pour lui faire peur","insulter un voisin","voter deux fois","obtenir un bien par la tromperie"],"b":3,"e":"C'est une atteinte au patrimoine."},{"q":"Le numéro de la police au Cameroun est :","r":["117","118","119","112"],"b":0,"e":"Le 118 est celui des sapeurs-pompiers."},{"q":"La « justice populaire » est :","r":["une forme légale de justice","elle-même une infraction","recommandée par la loi","un droit des victimes"],"b":1,"e":"Seule la justice officielle peut juger."},{"q":"Les mutilations génitales féminines sont une atteinte :","r":["au patrimoine","à la liberté de la presse","à l'intégrité physique","au droit de vote"],"b":2,"e":"Elles blessent gravement le corps."},{"q":"Face à une agression, il faut d'abord :","r":["filmer la scène pour les réseaux","se venger de l'agresseur","fuir sans rien dire","protéger la victime et alerter"],"b":3,"e":"Protéger, alerter, témoigner."}],"c":"1re A","m":"ecm","rang":10,"apc":{"module":"Les formes de violences","famille":"Paix et sécurité","agir":"Prévenir et combattre les violences et l'extrémisme violent","situation":"Au marché de Mbouda, un voleur présumé est rattrapé par la foule qui commence à le frapper ; un commerçant crie de le brûler. Tu es présent avec ton grand frère.","tache":"Identifie les atteintes commises dans cette scène et décris la conduite responsable à tenir."},"gratuit":true});
VRT_L("1re-a-ecm-r11",{"duree":20,"titre":"L'extrémisme violent","accroche":"Quand les idées deviennent des armes.","intro":"L'extrémisme violent menace la paix au Cameroun, notamment avec les attaques de Boko Haram dans l'Extrême-Nord et les violences armées dans les régions du Nord-Ouest et du Sud-Ouest.","objectifs":["définir l'extrémisme violent","identifier ses causes et ses manifestations","connaître les signes de radicalisation"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>L'<strong>extrémisme violent</strong> est l'attitude de personnes ou de groupes qui adoptent des idées extrêmes (religieuses, politiques, ethniques) et utilisent la violence pour les imposer.</div><p>Le <strong>terrorisme</strong> en est une forme : il vise à semer la terreur dans la population par des attentats, des enlèvements ou des massacres.</p>"},{"t":"Causes et manifestations","verrou":true},{"t":"Les signes de radicalisation","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"ecm","rang":11,"apc":{"module":"Les formes de violences","famille":"Paix et sécurité","agir":"Prévenir et combattre les violences et l'extrémisme violent","situation":"Ton cousin de 17 ans, à Kousséri, a quitté l'école, ne parle plus à sa famille, passe ses nuits à regarder des vidéos de combattants et répète qu'« un vrai homme doit prendre les armes ».","tache":"Identifie trois signes de radicalisation et propose une démarche pour l'aider."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-ecm-r12",{"duree":20,"titre":"La notion de paix","accroche":"Plus que l'absence de guerre.","intro":"La paix est un bien précieux que le Cameroun a appris à mesurer face aux crises. Elle ne se réduit pas à l'absence de combats : elle suppose la justice, le respect et la sécurité de tous.","objectifs":["définir la paix","distinguer paix négative et paix positive","identifier les facteurs de paix"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>paix</strong> est l'état d'une société ou de relations entre États où règnent la sécurité, la concorde et le respect mutuel, sans violence ni conflit armé.</div><p>On distingue la <strong>paix négative</strong> (absence de guerre) et la <strong>paix positive</strong> (présence de justice, de droits respectés et de bonnes relations).</p>"},{"t":"Les niveaux de la paix","verrou":true},{"t":"Les facteurs de paix","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"ecm","rang":12,"apc":{"module":"La notion de paix","famille":"Paix et sécurité","agir":"Promouvoir la paix et le vivre ensemble","situation":"Dans ton quartier de Yaoundé, aucune bagarre n'a eu lieu depuis un an, mais les familles de deux communautés ne se parlent plus et refusent les mariages mixtes.","tache":"Explique pourquoi cette situation n'est pas une paix véritable et propose deux actions pour construire une paix positive."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-ecm-r13",{"duree":20,"titre":"TD : les symboles de la paix au Cameroun","accroche":"Enquête sur les signes qui unissent.","intro":"Chaque culture camerounaise possède des signes, objets et rites qui expriment la paix et la réconciliation. Ce travail dirigé les fait découvrir par l'enquête.","objectifs":["recenser des symboles de paix","en expliquer la signification","présenter les résultats d'une enquête"],"parties":[{"t":"Les symboles universels","html":"<div class='def'><b>Définition</b>Un <strong>symbole de paix</strong> est un objet, une image, un geste ou un rite qui représente la paix et la réconciliation dans une culture.</div><ul><li>la <strong>colombe</strong> portant un rameau d'olivier ;</li><li>le <strong>drapeau blanc</strong> ;</li><li>la <strong>poignée de main</strong> et l'accolade ;</li><li>le <strong>flambeau</strong> de la paix.</li></ul>"},{"t":"Des symboles camerounais","verrou":true},{"t":"Mener l'enquête","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"ecm","rang":13,"apc":{"module":"La notion de paix","famille":"Paix et sécurité","agir":"Promouvoir la paix et le vivre ensemble","situation":"Ta classe de 1re prépare une exposition sur les symboles de la paix pour la Journée internationale de la paix. Les élèves viennent de cinq régions différentes.","tache":"Propose un plan d'enquête en quatre étapes et un tableau à trois colonnes pour présenter les résultats."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-ecm-r14",{"duree":20,"titre":"Les stratégies de promotion de la paix","accroche":"Construire la paix au quotidien.","intro":"La paix se prépare et s'entretient. Les États, les communautés et chaque citoyen disposent de stratégies pour prévenir les conflits et renforcer la cohésion.","objectifs":["citer des stratégies de promotion de la paix","identifier les acteurs","proposer des actions à son niveau"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Une <strong>stratégie de promotion de la paix</strong> est un ensemble d'actions organisées pour prévenir les conflits, réduire les tensions et renforcer la cohésion sociale.</div>"},{"t":"Les stratégies","verrou":true},{"t":"Les acteurs et le rôle du jeune","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"ecm","rang":14,"apc":{"module":"La notion de paix","famille":"Paix et sécurité","agir":"Promouvoir la paix et le vivre ensemble","situation":"Dans ton lycée, des bagarres opposent régulièrement les élèves de deux quartiers rivaux ; trois blessés ont été recensés depuis la rentrée et des insultes circulent sur un groupe en ligne.","tache":"Propose une stratégie de paix en trois actions, en précisant pour chacune les acteurs mobilisés."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-ecm-r15",{"duree":20,"titre":"Le règlement pacifique des différends","accroche":"Résoudre les conflits sans violence.","intro":"Un différend peut opposer deux personnes, deux communautés ou deux États. Il existe des moyens pacifiques de le régler, du dialogue jusqu'au juge international. L'affaire de Bakassi en est un exemple célèbre.","objectifs":["définir un différend","citer les modes de règlement pacifique","analyser l'exemple de Bakassi"],"parties":[{"t":"Différend et modes de règlement","html":"<div class='def'><b>Définition</b>Un <strong>différend</strong> est un désaccord sur un droit, un intérêt ou un fait entre deux ou plusieurs parties. Son <strong>règlement pacifique</strong> consiste à y mettre fin sans recourir à la force.</div><ul><li><strong>la négociation</strong> : discussion directe entre les parties ;</li><li><strong>les bons offices et la médiation</strong> : un tiers rapproche les parties et propose une solution ;</li><li><strong>la conciliation</strong> : une commission examine et propose ;</li><li><strong>l'arbitrage</strong> : des arbitres choisis rendent une décision obligatoire ;</li><li><strong>le règlement judiciaire</strong> : un tribunal, comme la Cour internationale de justice, tranche.</li></ul>"},{"t":"L'exemple de Bakassi","verrou":true},{"t":"À l'échelle de chacun","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"ecm","rang":15,"apc":{"module":"La notion de paix","famille":"Paix et sécurité","agir":"Promouvoir la paix et le vivre ensemble","situation":"Deux familles de Foumban se disputent une parcelle de 2 hectares héritée d'un ancêtre commun ; les jeunes des deux familles ont déjà échangé des menaces et des coups de machette ont été évités de justesse.","tache":"Propose, dans l'ordre, trois modes de règlement pacifique adaptés à ce différend et justifie leur choix."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-ecm-r16",{"duree":20,"titre":"Dossier : la lutte contre l'extrémisme violent au Cameroun","accroche":"Défendre, prévenir, réintégrer.","intro":"Face à Boko Haram et aux groupes armés, le Cameroun combine une réponse sécuritaire, judiciaire, sociale et éducative. Ce dossier analyse cette lutte et la place des citoyens.","objectifs":["présenter les moyens de lutte contre l'extrémisme violent","analyser leurs résultats et leurs limites","proposer des actions citoyennes"],"parties":[{"t":"Les réponses sécuritaire et judiciaire","html":"<div class='def'><b>Définition</b>La <strong>lutte contre l'extrémisme violent</strong> est l'ensemble des actions qui visent à prévenir la radicalisation, à protéger les populations et à neutraliser les groupes violents.</div><ul><li>engagement des forces de défense et de sécurité, dont la Force multinationale mixte du bassin du lac Tchad avec les pays voisins ;</li><li>comités de vigilance des populations dans l'Extrême-Nord ;</li><li>loi du 23 décembre 2014 contre le terrorisme.</li></ul>"},{"t":"Les réponses sociales et éducatives","verrou":true},{"t":"Résultats, limites et rôle du citoyen","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"ecm","rang":16,"apc":{"module":"Les formes de violences","famille":"Paix et sécurité","agir":"Prévenir et combattre les violences et l'extrémisme violent","situation":"Dans un village du Mayo-Sava, l'école a rouvert après trois ans de fermeture due aux attaques ; 40 % des élèves sont des enfants déplacés et plusieurs jeunes du village ont rejoint autrefois un groupe armé avant de se rendre.","tache":"Analyse deux défis de ce village et propose trois actions complémentaires pour éviter le retour de l'extrémisme violent."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-ecm-r17",{"duree":20,"titre":"L'importance du vivre ensemble au Cameroun","accroche":"Plus de deux cents ethnies, une seule nation.","intro":"Le Cameroun est souvent présenté comme « l'Afrique en miniature » pour la diversité de ses peuples, de ses langues, de ses religions et de ses paysages. Vivre ensemble est la condition de sa stabilité et de son développement.","objectifs":["définir le vivre ensemble","identifier les éléments de la diversité camerounaise","expliquer l'importance du vivre ensemble"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>vivre ensemble</strong> est la capacité de personnes et de communautés différentes à partager pacifiquement un même espace, dans le respect mutuel, l'égalité des droits et la solidarité.</div>"},{"t":"La diversité camerounaise","verrou":true},{"t":"Pourquoi vivre ensemble ?","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"ecm","rang":17,"apc":{"module":"La notion de paix","famille":"Paix et sécurité","agir":"Promouvoir la paix et le vivre ensemble","situation":"Lors de l'élection du délégué de ta classe à Buea, un candidat déclare : « ne votez pas pour lui, il n'est pas de chez nous ». La classe compte des élèves de six régions et deux sous-systèmes.","tache":"Montre en quoi ce discours menace le vivre ensemble et rédige un appel de six lignes pour une campagne fondée sur les idées."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-ecm-r18",{"duree":20,"titre":"Dossier : la Commission nationale pour la promotion du bilinguisme et du multiculturalisme","accroche":"Une institution au service de l'unité.","intro":"Créée par décret du 23 janvier 2017, la Commission nationale pour la promotion du bilinguisme et du multiculturalisme (CNPBM) veille à l'égalité du français et de l'anglais et à la promotion de la diversité culturelle.","objectifs":["présenter la CNPBM","expliquer ses missions","évaluer son action et le rôle du citoyen"],"parties":[{"t":"Présentation","html":"<div class='def'><b>Définition</b>La <strong>CNPBM</strong> est un organe consultatif, placé auprès du président de la République, chargé de promouvoir le bilinguisme officiel (français et anglais) et le multiculturalisme au Cameroun.</div><p>Elle a été créée dans un contexte de tensions dans les régions du Nord-Ouest et du Sud-Ouest, où une partie de la population dénonçait une marginalisation de l'anglais et du sous-système anglophone.</p>"},{"t":"Les missions","verrou":true},{"t":"Évaluation et rôle du citoyen","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"ecm","rang":18,"apc":{"module":"La notion de paix","famille":"Paix et sécurité","agir":"Promouvoir la paix et le vivre ensemble","situation":"Un élève anglophone muté de Limbé à Ngaoundéré reçoit tous ses documents administratifs en français seulement et se fait moquer pour son accent ; il envisage d'abandonner l'école.","tache":"Explique en quoi ses droits et le vivre ensemble sont atteints, et indique deux actions possibles, dont une auprès de la CNPBM."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-francais-commentaire-consigne",{"c":"1re A","m":"francais","rang":4,"titre":"Commentaire composé : analyser la consigne","duree":25,"accroche":"La consigne est une boussole : elle indique où regarder dans le texte.","intro":"Au probatoire et au baccalauréat A, le commentaire composé est un exercice majeur. Avant de lire le texte en détail, il faut comprendre ce que la consigne demande : sans cela, on paraphrase ou on fait une explication linéaire, deux fautes sévèrement notées.","objectifs":["identifier les éléments d'une consigne de commentaire composé","distinguer consigne avec pistes et consigne sans pistes","transformer la consigne en projet de lecture"],"parties":[{"t":"Qu'est-ce qu'un commentaire composé ?","html":"<div class='def'><b>Définition</b>Le commentaire composé est l'étude organisée d'un texte littéraire (poème, extrait de roman ou de théâtre) autour de <strong>centres d'intérêt</strong>. On montre <strong>ce que dit</strong> le texte et <strong>comment il le dit</strong> (procédés d'écriture).</div><div class='attention'><b>Deux fautes à éviter</b>La <strong>paraphrase</strong> (répéter le texte avec d'autres mots) et l'<strong>explication linéaire</strong> (suivre le texte ligne à ligne). Le commentaire est <strong>composé</strong> : regroupé par idées.</div>","retenir":"Commentaire composé = fond + forme, organisés en centres d'intérêt."},{"t":"Les éléments de la consigne","verrou":true},{"t":"Transformer la consigne en projet de lecture","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Français de Première et Terminale A","famille":"Vie sociale et culturelle","agir":"Analyser une consigne pour construire une lecture organisée d'un texte littéraire","situation":"En devoir surveillé dans ton lycée de Nkongsamba, la consigne est : « Vous ferez de ce texte un commentaire composé. » Il n'y a aucune piste. Ta voisine panique et commence à expliquer le texte vers après vers.","tache":"Lui expliquer la démarche pour trouver des centres d'intérêt."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-philo-ethnocentrisme",{"c":"1re A","m":"philo","rang":1,"titre":"Les thèses ethnocentristes occidentales sur l'Afrique","duree":25,"accroche":"« L'Afrique n'est pas une partie historique du monde » : une thèse à examiner, pas à subir.","intro":"Pour comprendre pourquoi la philosophie africaine s'est d'abord construite comme une réponse, il faut connaître les thèses qu'elle conteste. Du XVIIIᵉ au XXᵉ siècle, des penseurs européens ont jugé l'Afrique à partir de leur propre culture, prise comme mesure de toute humanité : c'est l'ethnocentrisme.","objectifs":["définir l'ethnocentrisme","présenter les thèses de Hegel, Gobineau et Lévy-Bruhl","montrer les limites de ces thèses et leurs conséquences"],"parties":[{"t":"L'ethnocentrisme","html":"<div class='def'><b>Définition</b>L'<strong>ethnocentrisme</strong> est l'attitude qui consiste à juger les autres cultures à partir des valeurs de la sienne, considérée comme supérieure ou comme la norme. Claude Lévi-Strauss : « Le barbare, c'est d'abord l'homme qui croit à la barbarie » (<em>Race et histoire</em>, 1952).</div><div class='ex'><b>Exemple</b>Dire qu'un peuple « n'a pas d'écriture, donc pas de pensée », c'est prendre l'écriture alphabétique européenne comme seul critère de rationalité et ignorer l'oralité, les hiéroglyphes, l'écriture bamoun du roi Njoya.</div>","retenir":"Ethnocentrisme : sa propre culture comme mesure des autres."},{"t":"Les principales thèses","html":"<ul><li><strong>Hegel</strong> (<em>Leçons sur la philosophie de l'histoire</em>, 1822-1830) : l'Afrique « proprement dite » ne serait « pas une partie historique du monde » ; l'Africain vivrait dans l'immédiateté, sans conscience de l'universel.</li><li><strong>Arthur de Gobineau</strong> (<em>Essai sur l'inégalité des races humaines</em>, 1853-1855) : hiérarchie des « races » ; la « race noire » serait la plus basse. Thèse raciste aujourd'hui scientifiquement réfutée.</li><li><strong>Lucien Lévy-Bruhl</strong> (<em>La Mentalité primitive</em>, 1922) : les « primitifs » auraient une mentalité <strong>prélogique</strong> et <strong>mystique</strong>, indifférente à la contradiction.</li></ul><div class='attention'><b>Les conséquences</b>Ces thèses ont servi à <strong>justifier</strong> la traite négrière et la colonisation, présentée comme une « mission civilisatrice ».</div>","retenir":"Hegel : Afrique hors de l'histoire ; Gobineau : inégalité des races ; Lévy-Bruhl : mentalité prélogique.","labo":{"type":"trier","invite":"Choisis une notion de la leçon.","items":[["Ethnocentrisme","Ethnocentrisme : juger les autres à partir de sa culture."],["Hegel","Hegel : l'Afrique, « pas une partie historique du monde »."],["Gobineau","Gobineau (1853-1855) : inégalité des races."],["Lévy-Bruhl","Lévy-Bruhl (1922) : mentalité prélogique ; revenu sur sa thèse (1949)."],["Réponses","Réponses : C. A. Diop, Towa, Hountondji ; écriture de Njoya."]]}},{"t":"Les réponses et les limites","html":"<ul><li><strong>Lévy-Bruhl lui-même</strong>, dans ses <em>Carnets</em> publiés en 1949, revient sur l'idée d'une mentalité prélogique propre à certains peuples.</li><li><strong>Cheikh Anta Diop</strong> montre l'apport de l'Égypte nègre à la civilisation et la profondeur historique de l'Afrique.</li><li>La génétique a établi qu'il n'existe pas de « races » humaines biologiquement hiérarchisées.</li><li><strong>Marcien Towa</strong> et <strong>Paulin Hountondji</strong> répondent en philosophes : la rationalité est universelle ; il faut l'exercer, non prouver qu'on la possède.</li></ul><div class='savais'><b>Le savais-tu ?</b>Le roi Ibrahim Njoya (vers 1870-1933) a inventé à Foumban une écriture, le <strong>shü-mom</strong>, et fait rédiger l'histoire et les coutumes de son royaume : un démenti direct à l'idée d'une Afrique sans écriture.</div>","retenir":"Ces thèses sont réfutées par l'histoire, la science et la philosophie ; la raison est universelle."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Première partie : l'évaluation des ressources</h3><p><strong>Question de cours.</strong> L'ethnocentrisme consiste à :</p><ol type='a'><li>juger les autres cultures à partir de la sienne</li><li>étudier toutes les cultures</li><li>aimer les voyages</li><li>parler plusieurs langues</li></ol><details><summary>Voir la réponse</summary><p><strong>juger les autres cultures à partir de la sienne</strong>. Sa culture devient la mesure de toutes les autres.</p></details><p><strong>Exercice.</strong></p><p>Définis les concepts « ethnocentrisme » et « mentalité prélogique » et donne pour chacun une citation avec son auteur.</p><details><summary>Voir la réponse</summary><p>(Réponse : Ethnocentrisme : juger les autres cultures à partir de la sienne, prise pour norme ; « Le barbare, c'est d'abord l'homme qui croit à la barbarie » (Lévi-Strauss). Mentalité prélogique : selon Lévy-Bruhl, pensée « primitive » mystique, indifférente à la contradiction ; « L'Afrique […] n'est pas une partie historique du monde » (Hegel) relève du même préjugé.)</p></details><h3>Deuxième partie : l'évaluation de l'agir compétent</h3><p><strong>Sujet.</strong> Sur un réseau social, une vidéo virale affirme : « Les Africains n'ont rien inventé, tout vient de l'Occident. » Plusieurs élèves de ta classe à Yaoundé la partagent en riant.</p><p><strong>Consigne.</strong> Rédige un commentaire argumenté (12 lignes) qui identifie la thèse ethnocentriste, la rattache à un auteur étudié et la réfute avec deux arguments.</p><p><em>Présentation : 2 points.</em></p><details><summary>Voir une réponse attendue</summary><p>Cette affirmation reprend l'idée de Hegel d'une Afrique hors de l'histoire. Elle est fausse : l'Égypte pharaonique a développé l'écriture, la géométrie et la médecine (Cheikh Anta Diop) ; au Cameroun, le roi Njoya a inventé une écriture au XIXᵉ siècle ; la métallurgie du fer est attestée très tôt en Afrique. Juger les autres à partir de critères qu'on suppose universels, c'est de l'ethnocentrisme. Partager une telle vidéo sans vérifier, c'est accepter une opinion sans examen, le contraire de l'attitude philosophique.</p></details></div>","retenir":"Savoir-être mobilisé : esprit critique et fierté éclairée de son héritage."}],"revision":["<strong>Ethnocentrisme</strong> : juger les autres à partir de sa culture.","<strong>Hegel</strong> : l'Afrique, « pas une partie historique du monde ».","<strong>Gobineau</strong> (1853-1855) : inégalité des races.","<strong>Lévy-Bruhl</strong> (1922) : mentalité prélogique ; revenu sur sa thèse (1949).","Réponses : C. A. Diop, Towa, Hountondji ; écriture de Njoya."],"exo":"<p>Définis les concepts « ethnocentrisme » et « mentalité prélogique » et donne pour chacun une citation avec son auteur. <em>(Réponse : Ethnocentrisme : juger les autres cultures à partir de la sienne, prise pour norme ; « Le barbare, c'est d'abord l'homme qui croit à la barbarie » (Lévi-Strauss). Mentalité prélogique : selon Lévy-Bruhl, pensée « primitive » mystique, indifférente à la contradiction ; « L'Afrique […] n'est pas une partie historique du monde » (Hegel) relève du même préjugé.)</em></p>","quiz":[{"q":"L'ethnocentrisme consiste à :","r":["juger les autres cultures à partir de la sienne","étudier toutes les cultures","aimer les voyages","parler plusieurs langues"],"b":0,"e":"Sa culture devient la mesure de toutes les autres."},{"q":"Pour Hegel, l'Afrique « proprement dite » :","r":["est le berceau de la philosophie","n'est pas une partie historique du monde","est l'avenir du monde","est une démocratie"],"b":1,"e":"Thèse des Leçons sur la philosophie de l'histoire."},{"q":"<em>Essai sur l'inégalité des races humaines</em> est de :","r":["Lévy-Bruhl","Hegel","Gobineau","Towa"],"b":2,"e":"Arthur de Gobineau, 1853-1855."},{"q":"<em>La Mentalité primitive</em> date de :","r":["1853","1945","1971","1922"],"b":3,"e":"Lucien Lévy-Bruhl."},{"q":"La « mentalité prélogique » serait indifférente :","r":["à la contradiction","à la musique","à la religion","à la nature"],"b":0,"e":"Selon Lévy-Bruhl, avant ses Carnets."},{"q":"Ces thèses ont servi à justifier :","r":["les indépendances","la colonisation","la négritude","l'ONU"],"b":1,"e":"Sous le nom de « mission civilisatrice »."},{"q":"L'écriture shü-mom a été inventée par :","r":["Cheikh Anta Diop","Senghor","le roi Njoya","Hountondji"],"b":2,"e":"À Foumban, royaume bamoun."},{"q":"« Le barbare, c'est d'abord l'homme qui croit à la barbarie » est de :","r":["Hegel","Gobineau","Towa","Lévi-Strauss"],"b":3,"e":"Race et histoire, 1952."},{"q":"Cheikh Anta Diop a surtout montré :","r":["l'apport de l'Égypte nègre à la civilisation","l'infériorité de l'Afrique","la supériorité de l'Europe","l'absence d'histoire africaine"],"b":0,"e":"Nations nègres et culture, 1954."},{"q":"Pour Towa et Hountondji, face à ces thèses il faut :","r":["se taire","exercer la raison critique","rejeter toute philosophie","imiter l'Europe en tout"],"b":1,"e":"La rationalité est universelle : il faut l'exercer."}],"apc":{"module":"Philosophie de Première A","famille":"Vie sociale et culturelle","agir":"Identifier et réfuter les préjugés ethnocentristes","situation":"Sur un réseau social, une vidéo virale affirme : « Les Africains n'ont rien inventé, tout vient de l'Occident. » Plusieurs élèves de ta classe à Yaoundé la partagent en riant.","tache":"Rédiger un commentaire qui identifie la thèse, la rattache à un auteur et la réfute."},"gratuit":true});
VRT_L("1re-a-histoire-renaissance",{"c":"1re A","m":"histoire","rang":1,"titre":"L'Europe de la Renaissance (XVᵉ-XVIᵉ siècles)","duree":25,"accroche":"Une imprimerie, des caravelles et une nouvelle idée de l'homme : l'Europe change de visage.","intro":"Entre le milieu du XVᵉ et la fin du XVIᵉ siècle, l'Europe connaît un renouveau des arts, des sciences et des idées, et part à la découverte du monde. C'est aussi le moment où des navigateurs portugais atteignent les côtes du Cameroun, auquel ils donnent son nom.","objectifs":["définir la Renaissance et l'humanisme","présenter les transformations artistiques, scientifiques et religieuses","expliquer les grandes découvertes et leurs conséquences pour l'Afrique"],"parties":[{"t":"La Renaissance et l'humanisme","html":"<div class='def'><b>Définitions</b>La <strong>Renaissance</strong> est le renouveau culturel européen des XVᵉ et XVIᵉ siècles, né en <strong>Italie</strong> (Florence, Rome, Venise), qui s'inspire de l'Antiquité grecque et romaine. L'<strong>humanisme</strong> est le mouvement intellectuel qui place l'<strong>homme</strong>, sa dignité et sa raison au centre de la réflexion.</div><ul><li><strong>L'imprimerie</strong> : Gutenberg met au point les caractères mobiles à Mayence (Bible vers 1455) ; les livres se diffusent rapidement.</li><li><strong>Les humanistes</strong> : Érasme (<em>Éloge de la folie</em>, 1511), Thomas More (<em>Utopie</em>, 1516), Rabelais, Montaigne.</li><li><strong>Les mécènes</strong> : les Médicis à Florence, les papes à Rome financent artistes et savants.</li></ul>","retenir":"Renaissance : renouveau inspiré de l'Antiquité, né en Italie ; humanisme : l'homme au centre ; diffusion par l'imprimerie."},{"t":"Arts, sciences et religion","html":"<ul><li><strong>Arts</strong> : perspective, étude du corps humain. Léonard de Vinci (<em>La Joconde</em>), Michel-Ange (plafond de la chapelle Sixtine), Raphaël.</li><li><strong>Sciences</strong> : <strong>Copernic</strong> (1543) affirme que la Terre tourne autour du Soleil (héliocentrisme) ; Vésale décrit l'anatomie humaine.</li><li><strong>Religion</strong> : en <strong>1517</strong>, <strong>Martin Luther</strong> critique la vente des indulgences : c'est la <strong>Réforme protestante</strong> ; Calvin la prolonge. L'Église catholique répond par la <strong>Contre-Réforme</strong> (concile de Trente, 1545-1563).</li></ul><div class='attention'><b>Attention</b>La Renaissance n'est pas une rupture totale avec le Moyen Âge, et elle reste réservée à une élite urbaine et instruite.</div>","retenir":"Vinci, Michel-Ange ; Copernic (1543) ; Luther (1517) : Réforme et Contre-Réforme.","labo":{"type":"etapes","invite":"Avance étape par étape.","items":[["Renaissance","Renaissance (XVᵉ-XVIᵉ s.) : renouveau né en Italie, inspiré de l'Antiquité."],["Humanisme","Humanisme : l'homme au centre ; imprimerie de Gutenberg (vers 1455)."],["Copernic","Vinci, Michel-Ange ; Copernic 1543 ; Luther 1517."],["1492","Découvertes : 1488 Dias, 1492 Colomb, 1498 Vasco de Gama."],["Rio dos Camarões","Vers 1472 : Fernando Póo, Rio dos Camarões."]]}},{"t":"Les grandes découvertes et l'Afrique","html":"<ul><li>Causes : recherche de l'or et des épices, contournement de l'Empire ottoman (prise de Constantinople en <strong>1453</strong>), progrès techniques (caravelle, boussole, astrolabe).</li><li>Étapes : Bartolomeu Dias passe le cap de Bonne-Espérance (1488) ; <strong>Christophe Colomb</strong> atteint l'Amérique (1492) ; Vasco de Gama arrive en Inde (1498) ; Magellan et Elcano font le tour du monde (1519-1522).</li></ul><div class='ex'><b>Le Cameroun</b>Vers <strong>1472</strong>, le Portugais <strong>Fernando Póo</strong> entre dans l'estuaire du Wouri ; les marins, frappés par l'abondance des crevettes, le nomment <strong>Rio dos Camarões</strong>, la « rivière des crevettes » : c'est l'origine du nom <strong>Cameroun</strong>.</div><div class='attention'><b>Conséquences</b>Premiers contacts commerciaux avec l'Afrique, puis développement de la <strong>traite atlantique</strong> pour fournir des esclaves aux plantations d'Amérique ; destruction des sociétés amérindiennes.</div>","retenir":"1453, 1488, 1492, 1498 ; vers 1472, Rio dos Camarões ; le revers des découvertes : traite et conquêtes."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Première partie : l'évaluation des ressources (9 points)</h3><p><strong>1.</strong> Présente et analyse deux facteurs qui expliquent la Renaissance en Europe aux XVe et XVIe siècles. Le candidat répondra par un texte de 10 à 15 lignes, en un seul paragraphe. (5 pts)</p><p><strong>2. Texte à corriger (4 pts).</strong> Le texte ci-dessous contient quatre informations erronées.</p><blockquote>« La Renaissance commence en Allemagne au XVe siècle. Gutenberg y invente la boussole vers 1450. Les humanistes, comme Érasme, veulent revenir aux textes de l'Antiquité. En 1543, Galilée publie un ouvrage qui place la Terre au centre de l'univers. Les princes deviennent mécènes des artistes. »</blockquote><p>a) Relève les quatre informations erronées. (2 pts) b) Réécris le texte en corrigeant ces erreurs. (2 pts)</p><details><summary>Voir le corrigé de la première partie</summary><p><strong>1.</strong> Préambule : aux XVe-XVIe siècles, l'Europe connaît un renouveau des arts, des lettres et des sciences appelé Renaissance. Éléments : l'invention de l'imprimerie par Gutenberg vers 1450, qui diffuse rapidement les livres et les idées ; la redécouverte des auteurs grecs et latins par les humanistes, favorisée par l'arrivée de savants byzantins en Italie après 1453 ; on peut aussi citer le mécénat des princes et des riches marchands. Explications : ces facteurs permettent la circulation du savoir et financent les artistes. Bilan : la Renaissance naît de la conjonction d'innovations techniques, intellectuelles et économiques.</p><p><em>Barème : préambule 1 pt (existence 0,5, pertinence 0,5) ; deux éléments 2 pts ; explications 1 pt ; bilan 1 pt.</em></p><p><strong>2.</strong> Erreurs : 1) en Allemagne → en Italie ; 2) la boussole → l'imprimerie à caractères mobiles ; 3) Galilée → Copernic ; 4) la Terre au centre → le Soleil au centre (héliocentrisme). Texte corrigé : « La Renaissance commence en Italie au XVe siècle. Gutenberg invente l'imprimerie à caractères mobiles vers 1450. Les humanistes, comme Érasme, veulent revenir aux textes de l'Antiquité. En 1543, Copernic publie un ouvrage qui place le Soleil au centre de l'univers. Les princes deviennent mécènes des artistes. »</p></details><h3>Deuxième partie : l'évaluation des compétences (9 points)</h3><p><strong>Thème : Promotion de la culture et de l'esprit critique</strong></p><p><strong>Document 1 : Un idéal humaniste</strong></p><blockquote>« Science sans conscience n'est que ruine de l'âme. »</blockquote><p><em>Source : François Rabelais, <i>Pantagruel</i>, 1532, chapitre VIII (lettre de Gargantua à son fils).</em></p><p><strong>Document 2 : Quelques repères de la Renaissance</strong></p><table><tr><th>Date</th><th>Événement</th></tr><tr><td>vers 1450</td><td>Imprimerie à caractères mobiles de Gutenberg (Mayence)</td></tr><tr><td>1492</td><td>Christophe Colomb atteint l'Amérique</td></tr><tr><td>1503-1506</td><td>Léonard de Vinci peint <i>La Joconde</i></td></tr><tr><td>1543</td><td>Copernic publie sa théorie héliocentrique</td></tr></table><p><em>Source : Réalisation VÉRITAS, d'après le programme d'histoire de Première.</em></p><p><strong>Consigne.</strong> À partir des documents et de tes connaissances, rédige une production cohérente dont les grandes lignes reposent sur les tâches suivantes :</p><ol><li>Explique le sens de la phrase de Rabelais et montre qu'elle résume l'idéal humaniste. (3 pts)</li><li>Montre, à partir du document 2 et de tes connaissances, que la Renaissance est un renouveau à la fois artistique, scientifique et géographique. (3 pts)</li><li>Propose deux actions pour que les jeunes Camerounais développent aujourd'hui leur esprit critique face aux informations qu'ils reçoivent. (3 pts)</li></ol><p><em>Ta production comportera trois paragraphes, sans numéros ni tirets. Présentation : 2 points.</em></p><details><summary>Voir le corrigé de la deuxième partie</summary><p>Tâche 1 : pour Rabelais, le savoir doit s'accompagner de morale et de jugement ; l'humanisme place l'homme au centre, valorise l'éducation complète, le retour aux textes anciens et l'esprit critique. Tâche 2 : renouveau artistique (Léonard de Vinci), scientifique (Copernic, héliocentrisme), technique (imprimerie) et géographique (voyage de Colomb, 1492). Tâche 3 : créer des clubs de lecture et de débat dans les établissements ; apprendre à vérifier les sources des informations reçues sur les réseaux sociaux.</p><p><em>Barème de chaque tâche : pertinence 1 pt, correction de la langue 1 pt, cohérence 1 pt. Présentation : 2 pts.</em></p></details></div>","retenir":"Savoir-être mobilisé : esprit critique et devoir de mémoire."}],"revision":["<strong>Renaissance</strong> (XVᵉ-XVIᵉ s.) : renouveau né en Italie, inspiré de l'Antiquité.","<strong>Humanisme</strong> : l'homme au centre ; imprimerie de Gutenberg (vers 1455).","Vinci, Michel-Ange ; <strong>Copernic</strong> 1543 ; <strong>Luther</strong> 1517.","Découvertes : 1488 Dias, <strong>1492</strong> Colomb, 1498 Vasco de Gama.","Vers 1472 : Fernando Póo, <strong>Rio dos Camarões</strong>."],"exo":"<p>Associe chaque date à son événement : 1455, 1492, 1517, 1543. <em>(Réponse : 1455 : Bible de Gutenberg ; 1492 : Colomb en Amérique ; 1517 : thèses de Luther ; 1543 : Copernic, héliocentrisme.)</em></p>","quiz":[{"q":"La Renaissance est née en :","r":["Italie","Angleterre","Espagne","Allemagne"],"b":0,"e":"Florence, Rome et Venise en sont les grands foyers."},{"q":"L'imprimerie à caractères mobiles est mise au point par :","r":["Copernic","Gutenberg","Érasme","Luther"],"b":1,"e":"À Mayence, Bible vers 1455."},{"q":"<em>Éloge de la folie</em> est d'un humaniste :","r":["Rabelais","Montaigne","Érasme","Thomas More"],"b":2,"e":"Érasme, 1511."},{"q":"Copernic affirme que :","r":["la Terre est plate","le Soleil tourne autour de la Terre","la Lune est une planète","la Terre tourne autour du Soleil"],"b":3,"e":"L'héliocentrisme, 1543."},{"q":"La Réforme protestante commence en :","r":["1517","1492","1453","1545"],"b":0,"e":"Martin Luther et les 95 thèses."},{"q":"Christophe Colomb atteint l'Amérique en :","r":["1488","1492","1498","1522"],"b":1,"e":"Au service des rois d'Espagne."},{"q":"Le nom « Cameroun » vient de :","r":["un roi douala","un fleuve du Nord","Rio dos Camarões, la rivière des crevettes","un mot allemand"],"b":2,"e":"Nom donné par les Portugais à l'estuaire du Wouri."},{"q":"La prise de Constantinople par les Ottomans date de :","r":["1517","1492","1498","1453"],"b":3,"e":"Elle pousse les Européens à chercher d'autres routes vers l'Asie."},{"q":"Une conséquence dramatique des grandes découvertes pour l'Afrique est :","r":["la traite atlantique","l'imprimerie","l'humanisme","la Contre-Réforme"],"b":0,"e":"Déportation de millions d'Africains vers l'Amérique."},{"q":"La caravelle, la boussole et l'astrolabe sont :","r":["des œuvres d'art","des progrès techniques de navigation","des livres humanistes","des religions"],"b":1,"e":"Ils rendent possibles les voyages au long cours."}],"apc":{"module":"Histoire de Première","famille":"Citoyenneté","agir":"Expliquer les transformations de l'Europe et leurs effets sur l'Afrique","situation":"Un guide du musée maritime de Douala prépare une visite pour des collégiens. Il veut leur expliquer d'où vient le nom « Cameroun » et pourquoi l'arrivée des Portugais au XVᵉ siècle a eu des effets à la fois positifs et dramatiques.","tache":"Rédiger un texte qui explique le nom et les deux faces des contacts avec les Portugais."},"gratuit":true});
VRT_L("1re-a-geo-croissance-demographique",{"c":"1re A","m":"geo","rang":1,"titre":"La croissance démographique dans le monde","duree":25,"accroche":"Huit milliards d'humains, mais des rythmes de croissance très différents.","intro":"La population mondiale a dépassé 8 milliards en novembre 2022. Elle était d'un milliard vers 1800. Cette croissance n'a pas été régulière et elle n'est pas la même partout : l'Afrique subsaharienne, dont le Cameroun, connaît aujourd'hui la croissance la plus rapide du monde.","objectifs":["calculer et interpréter les indicateurs démographiques","expliquer la transition démographique","comparer la croissance des pays développés et des pays en développement"],"parties":[{"t":"Les indicateurs démographiques","html":"<div class='def'><b>Définitions</b><strong>Taux de natalité</strong> (TN) = naissances ÷ population × 1 000 (en ‰). <strong>Taux de mortalité</strong> (TM) = décès ÷ population × 1 000. <strong>Taux d'accroissement naturel</strong> (TAN) = TN − TM, exprimé en ‰ ou en %. <strong>Indice synthétique de fécondité</strong> (ISF) : nombre moyen d'enfants par femme.</div><div class='ex'><b>Exemple</b>Une ville de 200 000 habitants enregistre 7 000 naissances et 1 600 décès en un an. TN = 7 000 ÷ 200 000 × 1 000 = 35 ‰ ; TM = 8 ‰ ; TAN = 27 ‰ = 2,7 % par an.</div><div class='astuce'><b>Astuce</b>Temps de doublement approximatif : 70 ÷ taux en %. À 2,7 % par an, la population double en 26 ans environ.</div>","retenir":"TAN = TN − TM ; doublement ≈ 70 ÷ taux en %."},{"t":"La transition démographique","html":"<div class='def'><b>Définition</b>La <strong>transition démographique</strong> est le passage d'un régime à natalité et mortalité <strong>élevées</strong> à un régime où les deux sont <strong>faibles</strong>.</div><ol><li><strong>Régime traditionnel</strong> : TN et TM élevés, croissance faible.</li><li><strong>Phase 1</strong> : la mortalité baisse (vaccins, hygiène, alimentation), la natalité reste forte : <strong>croissance très rapide</strong>.</li><li><strong>Phase 2</strong> : la natalité baisse à son tour (scolarisation des filles, urbanisation, contraception) : la croissance ralentit.</li><li><strong>Régime moderne</strong> : TN et TM faibles, croissance faible, vieillissement.</li></ol><div class='ex'><b>Où en est-on ?</b>L'Europe a achevé sa transition. Le Cameroun est entre la phase 1 et la phase 2 : mortalité en baisse, fécondité encore élevée (près de 5 enfants par femme selon l'enquête démographique et de santé de 2018), croissance d'environ 2,6 % par an.</div>","retenir":"Mortalité qui baisse d'abord, natalité ensuite : entre les deux, une explosion démographique.","labo":{"type":"trier","invite":"Choisis une notion de la leçon.","items":[["TAN = TN − TM","TN, TM en ‰ ; TAN = TN − TM ; ISF : enfants par femme."],["70 ÷ taux en %","Doublement ≈ 70 ÷ taux en %."],["Transition démographique","Transition démographique : mortalité puis natalité baissent."],["Cameroun","Cameroun : croissance ≈ 2,6 % par an, ISF proche de 5."],["Enjeux","Enjeux : écoles, emplois, santé ; dividende démographique."]]}},{"t":"Une croissance inégale et ses enjeux","html":"<ul><li><strong>Pays développés</strong> : croissance faible ou nulle, vieillissement (Japon, Europe), parfois déclin.</li><li><strong>Pays en développement</strong> : population jeune ; en Afrique subsaharienne, plus de 40 % des habitants ont moins de 15 ans.</li></ul><div class='attention'><b>Enjeux pour le Cameroun</b>Besoins massifs en écoles, en emplois, en soins et en logements ; pression sur les terres et les forêts ; mais aussi un atout, le <strong>dividende démographique</strong>, si les jeunes sont formés et employés.</div><div class='savais'><b>Le savais-tu ?</b>Selon les projections de l'ONU, plus d'un humain sur quatre sera africain en 2050.</div>","retenir":"Vieillissement au Nord, jeunesse au Sud ; la croissance rapide est un défi et une chance."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Première partie : l'évaluation des ressources</h3><p><strong>Vérification des savoirs.</strong> La population mondiale a dépassé 8 milliards en :</p><ol type='a'><li>2022</li><li>2000</li><li>1990</li><li>2030</li></ol><details><summary>Voir la réponse</summary><p><strong>2022</strong>. En novembre 2022 selon l'ONU.</p></details><p><strong>Vérification des savoir-faire.</strong></p><p>Un pays a un TN de 12 ‰ et un TM de 10 ‰. Calcule le TAN et commente.</p><details><summary>Voir la réponse</summary><p>(Réponse : TAN = 2 ‰ = 0,2 % : croissance très faible, typique d'un pays ayant achevé sa transition.)</p></details><h3>Deuxième partie : l'évaluation de l'agir compétent</h3><p><strong>Situation-problème.</strong> La commune de Mbouda compte 100 000 habitants. En 2025, on y a enregistré 3 800 naissances et 900 décès. Le maire veut savoir combien de places d'école primaire prévoir et si la population aura doublé en 2050.</p><p><strong>Tâche 1.</strong> Calcule TN, TM et TAN.</p><p><strong>Tâche 2.</strong> Estime le temps de doublement et propose deux mesures au maire.</p><p><em>Présentation : 2 points.</em></p><details><summary>Voir une réponse attendue</summary><p>TN = 38 ‰ ; TM = 9 ‰ ; TAN = 29 ‰ = 2,9 % par an. Doublement ≈ 70 ÷ 2,9 ≈ 24 ans : la population atteindrait environ 200 000 habitants vers 2049, si le rythme se maintient. Mesures : construire des salles de classe et recruter des enseignants chaque année (environ 3 800 enfants de plus par génération) ; développer la formation professionnelle et les centres de santé maternelle, pour transformer cette jeunesse en atout.</p></details></div>","retenir":"Savoir-être mobilisé : sens de l'anticipation et de l'intérêt général."}],"revision":["TN, TM en ‰ ; <strong>TAN = TN − TM</strong> ; ISF : enfants par femme.","Doublement ≈ <strong>70 ÷ taux en %</strong>.","<strong>Transition démographique</strong> : mortalité puis natalité baissent.","Cameroun : croissance ≈ 2,6 % par an, ISF proche de 5.","Enjeux : écoles, emplois, santé ; dividende démographique."],"exo":"<p>Un pays a un TN de 12 ‰ et un TM de 10 ‰. Calcule le TAN et commente. <em>(Réponse : TAN = 2 ‰ = 0,2 % : croissance très faible, typique d'un pays ayant achevé sa transition.)</em></p>","quiz":[{"q":"La population mondiale a dépassé 8 milliards en :","r":["2022","2000","1990","2030"],"b":0,"e":"En novembre 2022 selon l'ONU."},{"q":"Le taux d'accroissement naturel se calcule par :","r":["TN + TM","TN − TM","TM − TN","TN × TM"],"b":1,"e":"Naissances moins décès, rapportés à la population."},{"q":"Un taux de natalité s'exprime en :","r":["%","km²","‰","habitants"],"b":2,"e":"Pour mille habitants."},{"q":"L'ISF désigne :","r":["le taux de mortalité infantile","l'espérance de vie","la densité","le nombre moyen d'enfants par femme"],"b":3,"e":"Indice synthétique de fécondité."},{"q":"À 3,5 % par an, une population double en environ :","r":["20 ans","35 ans","70 ans","10 ans"],"b":0,"e":"70 ÷ 3,5 = 20."},{"q":"Dans le régime démographique moderne :","r":["TN et TM sont élevés","TN et TM sont faibles","seule la mortalité est forte","la population explose"],"b":1,"e":"Fin de la transition : croissance faible."},{"q":"Une cause de la baisse de la natalité est :","r":["la baisse de la scolarisation","la ruralisation","la scolarisation des filles","les épidémies"],"b":2,"e":"Mariage plus tardif, accès à l'information et à la contraception."},{"q":"La phase de croissance la plus rapide correspond à :","r":["le régime moderne","le vieillissement","le régime traditionnel","la baisse de la mortalité avec une natalité forte"],"b":3,"e":"Phase 1 de la transition."},{"q":"Le « dividende démographique » désigne :","r":["l'avantage d'une population active nombreuse et formée","une prime de naissance","un impôt","le vieillissement"],"b":0,"e":"Il suppose formation et emplois."},{"q":"Le continent à la croissance la plus rapide aujourd'hui est :","r":["l'Europe","l'Afrique","l'Amérique du Nord","l'Océanie"],"b":1,"e":"Surtout l'Afrique subsaharienne."}],"apc":{"module":"Géographie de Première A","famille":"Environnement, santé et bien-être","agir":"Utiliser les indicateurs démographiques pour anticiper les besoins d'une population","situation":"La commune de Mbouda compte 100 000 habitants. En 2025, on y a enregistré 3 800 naissances et 900 décès. Le maire veut savoir combien de places d'école primaire prévoir et si la population aura doublé en 2050.","tache":"Calculer les taux, estimer le doublement et proposer des mesures."},"gratuit":true});
VRT_L("1re-a-francais-metrique",{"c":"1re A","m":"francais","rang":3,"titre":"Le texte poétique : éléments de métrique","duree":25,"accroche":"Compter les syllabes d'un vers, c'est entendre la musique du poème.","intro":"Le poème se distingue de la prose par un travail particulier sur le rythme et les sons. La métrique étudie le vers : le nombre de syllabes, les pauses, les rimes, les strophes. Au commentaire composé, ces outils permettent de montrer comment la forme sert le sens.","objectifs":["compter les syllabes d'un vers (e muet, diérèse, synérèse)","identifier les types de vers, de rimes et de strophes","relier les choix métriques au sens du poème"],"parties":[{"t":"Compter les syllabes","html":"<p>En poésie, on compte les <strong>syllabes prononcées</strong>, appelées <strong>pieds</strong> par l'usage scolaire.</p><div class='def'><b>Le e muet</b>Il <strong>se prononce</strong> devant une consonne (« la ter-re-de mes pè-res ») ; il <strong>s'élide</strong> devant une voyelle ou un h muet ; il <strong>ne compte jamais</strong> en fin de vers.</div><div class='def'><b>Diérèse et synérèse</b>La <strong>diérèse</strong> sépare deux voyelles qui se suivent en deux syllabes (« pas-si-on » au lieu de « pas-sion ») pour insister sur un mot. La <strong>synérèse</strong> les réunit en une seule.</div><div class='ex'><b>Exemple</b>« Demain, dès l'aube, à l'heure où blanchit la campagne » (Victor Hugo) : De / main / dès / l'au / b(e) à / l'heu / r(e) où / blan / chit / la / cam / pagn(e) = <strong>12 syllabes</strong>.</div>","retenir":"E muet : compte devant consonne, s'élide devant voyelle, jamais en fin de vers."},{"t":"Vers, rythme et rimes","verrou":true},{"t":"Strophes et formes fixes ; la forme au service du sens","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Français de Première et Terminale A","famille":"Vie sociale et culturelle","agir":"Utiliser les règles de la métrique pour analyser et composer un poème","situation":"Pour la journée de la poésie de ton lycée à Bafang, ton groupe doit présenter un poème de quatre vers sur le fleuve Nkam. Un camarade propose de « faire comme dans les livres », avec des alexandrins et des rimes croisées, mais personne ne sait vérifier.","tache":"Expliquer la méthode de vérification et composer le quatrain."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-histoire-industrialisation",{"c":"1re A","m":"histoire","rang":2,"titre":"L'industrialisation de l'Europe (XVIIIᵉ-XIXᵉ siècles)","duree":25,"accroche":"La machine à vapeur a changé l'Europe… puis le destin de l'Afrique.","intro":"À partir de la fin du XVIIIᵉ siècle, l'Europe passe d'une économie agricole et artisanale à une économie industrielle fondée sur les machines, le charbon et les usines. Cette révolution transforme les sociétés européennes et pousse les puissances industrielles à conquérir de nouveaux territoires, notamment en Afrique.","objectifs":["expliquer les causes et les étapes de la révolution industrielle","décrire ses conséquences économiques et sociales","établir le lien entre industrialisation et impérialisme en Afrique"],"parties":[{"t":"La première révolution industrielle","html":"<p>Elle commence en <strong>Grande-Bretagne</strong> vers <strong>1760-1780</strong>, puis gagne la France, la Belgique et l'Allemagne au XIXᵉ siècle.</p><div class='def'><b>Les causes</b>Une <strong>révolution agricole</strong> qui nourrit plus d'habitants et libère de la main-d'œuvre ; une <strong>croissance démographique</strong> ; des <strong>capitaux</strong> issus du commerce, y compris le commerce triangulaire ; du <strong>charbon</strong> et du <strong>fer</strong> en abondance ; des inventions.</div><ul><li><strong>Textile</strong> : navette volante (Kay, 1733), machines à filer.</li><li><strong>Machine à vapeur</strong> perfectionnée par <strong>James Watt</strong> (1769).</li><li><strong>Chemin de fer</strong> : locomotive de Stephenson ; ligne Liverpool-Manchester (1830) ; bateaux à vapeur.</li></ul>","retenir":"Grande-Bretagne, fin du XVIIIᵉ siècle : charbon, fer, textile, machine à vapeur (Watt), chemin de fer."},{"t":"La deuxième révolution industrielle","verrou":true},{"t":"Conséquences : sociétés nouvelles et expansion coloniale","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Histoire de Première","famille":"Vie économique","agir":"Expliquer l'origine historique de la place de l'Afrique dans les échanges mondiaux","situation":"Lors d'une sortie au port de Douala, tu observes des grumes de bois et des fèves de cacao chargées vers l'Europe, et des voitures et des machines déchargées. Ton camarade demande : « Pourquoi exportons-nous des produits bruts et importons-nous des produits finis ? »","tache":"Expliquer l'origine de cette situation et proposer une piste de changement."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-geo-problemes-demographiques",{"c":"1re A","m":"geo","rang":3,"titre":"Les problèmes démographiques dans le monde","duree":25,"accroche":"Trop de jeunes ici, trop de vieux là-bas : deux problèmes opposés.","intro":"La croissance démographique ne pose pas les mêmes problèmes partout. Les pays en développement, à la population jeune et nombreuse, peinent à loger, nourrir, éduquer et employer. Les pays développés, eux, vieillissent et manquent de jeunes actifs. Comprendre ces deux situations aide à juger les politiques démographiques.","objectifs":["identifier les problèmes liés à la croissance rapide","identifier les problèmes liés au vieillissement","lire une pyramide des âges et en tirer des conclusions"],"parties":[{"t":"Les pays à croissance rapide","html":"<div class='def'><b>Définition</b>Un <strong>problème démographique</strong> est une difficulté économique ou sociale née du nombre, de la croissance ou de la structure par âge d'une population.</div><ul><li><strong>Scolarisation</strong> : salles de classe surchargées, manque d'enseignants.</li><li><strong>Emploi</strong> : chômage et sous-emploi des jeunes, secteur informel (moto-taxis, petit commerce).</li><li><strong>Alimentation</strong> : insécurité alimentaire si la production agricole progresse moins vite que la population.</li><li><strong>Urbanisation rapide</strong> : exode rural, quartiers spontanés, manque d'eau potable, d'électricité et d'assainissement.</li><li><strong>Santé</strong> : hôpitaux saturés, mortalité maternelle et infantile encore élevée.</li><li><strong>Environnement</strong> : déforestation, épuisement des sols, pression sur l'eau.</li></ul><div class='ex'><b>Au Cameroun</b>Douala et Yaoundé comptent chacune environ 4 millions d'habitants ; les quartiers construits en zones inondables (Mabanda à Douala, les bords du Mfoundi à Yaoundé) sont régulièrement touchés.</div>","retenir":"Croissance rapide : écoles, emplois, nourriture, logement, santé, environnement sous pression."},{"t":"Les pays vieillissants","verrou":true},{"t":"Lire une pyramide des âges","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Géographie de Première A","famille":"Environnement, santé et bien-être","agir":"Identifier les problèmes démographiques pour proposer des solutions locales","situation":"Dans la commune de Bonabéri, à Douala, la population a doublé en quinze ans. Les habitants se plaignent : écoles surchargées (plus de 100 élèves par classe), coupures d'eau, inondations dans les quartiers bas, jeunes sans emploi.","tache":"Rattacher ces problèmes à la croissance et proposer un plan d'action municipal."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-philo-tendances-africaine",{"c":"1re A","m":"philo","rang":2,"titre":"Les tendances de la philosophie africaine","duree":25,"accroche":"Y a-t-il une philosophie africaine ? Le débat lui-même en est une.","intro":"Pendant longtemps, des auteurs européens ont affirmé que l'Afrique n'avait ni histoire ni pensée rationnelle. Les philosophes africains ont répondu, mais pas tous de la même façon : certains ont cherché la philosophie dans les traditions, d'autres ont exigé une pensée critique et écrite. Ce débat est au cœur du programme de Terminale.","objectifs":["situer les grandes étapes de la philosophie africaine","distinguer les tendances (ethnophilosophie, courant critique, courant idéologique, sagesse)","associer chaque tendance à ses auteurs et à leurs œuvres"],"parties":[{"t":"Aux origines : l'Égypte ancienne et la réponse aux préjugés","html":"<p>Les historiens africains, à la suite de <strong>Cheikh Anta Diop</strong> (<em>Nations nègres et culture</em>, 1954) et de <strong>Théophile Obenga</strong>, rattachent la pensée africaine à l'<strong>Égypte pharaonique</strong> : sagesse de Ptahhotep, notion de <strong>Maât</strong> (ordre, vérité, justice).</p><div class='def'><b>Le contexte</b>Au XIXᵉ et au début du XXᵉ siècle, Hegel exclut l'Afrique de l'histoire universelle et Lévy-Bruhl parle d'une « mentalité prélogique ». La philosophie africaine moderne naît en grande partie comme <strong>réponse</strong> à ces thèses ethnocentristes.</div><div class='savais'><b>Le savais-tu ?</b>Le mot « Maât » désignait à la fois la justice du pharaon, la vérité de la parole et l'équilibre du monde : une seule notion pour l'éthique, la politique et la cosmologie.</div>","retenir":"La philosophie africaine moderne se construit en réponse aux préjugés et revendique un héritage ancien (Égypte, Maât)."},{"t":"L'ethnophilosophie et sa critique","verrou":true},{"t":"Les autres tendances","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Philosophie de Première A","famille":"Vie sociale et culturelle","agir":"Situer les débats de la philosophie africaine pour dialoguer entre tradition et raison critique","situation":"Lors d'une veillée à Bafoussam, ton oncle affirme : « Nos proverbes, c'est notre philosophie ; pas besoin de lire les livres des Blancs. » Ta cousine, en Terminale D, répond que « la philosophie est universelle ».","tache":"Exposer les deux positions avec des auteurs, puis dépasser l'opposition."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-philo-conscience",{"c":"1re A","m":"philo","rang":8,"titre":"La conscience : nature, valeur et limites","duree":30,"accroche":"« Je pense, donc je suis » : mais suis-je vraiment ce que je crois être ?","intro":"Je sais que je lis cette phrase, je sais que j'ai faim, je sais que j'ai mal agi hier : c'est la conscience. Elle semble faire la grandeur de l'homme et fonder sa liberté. Pourtant, des penseurs ont montré qu'elle ne nous dit pas tout de nous-mêmes. Cette notion revient souvent au baccalauréat.","objectifs":["définir la conscience et en distinguer les formes","présenter la valeur de la conscience (Descartes, Pascal, Husserl)","en montrer les limites (Spinoza, Marx, Freud)"],"parties":[{"t":"Définitions et formes","html":"<div class='def'><b>Étymologie et définition</b>Du latin <strong>cum scientia</strong>, « avec savoir ». La <strong>conscience</strong> est la connaissance plus ou moins claire que l'homme a de lui-même, de ses états et du monde qui l'entoure.</div><ul><li><strong>Conscience spontanée</strong> (ou immédiate) : je vois, j'entends, je ressens, sans y réfléchir.</li><li><strong>Conscience réfléchie</strong> : je fais retour sur moi-même (« je sais que je pense »).</li><li><strong>Conscience psychologique</strong> : savoir ce que l'on vit. <strong>Conscience morale</strong> : juger le bien et le mal de ses actes (remords, fierté). Rousseau : « Conscience ! conscience ! instinct divin, immortelle et céleste voix ».</li></ul><div class='astuce'><b>Husserl</b>« Toute conscience est conscience de quelque chose » : la conscience est toujours tournée vers un objet (c'est l'<strong>intentionnalité</strong>).</div>","retenir":"Conscience = « avec savoir » ; spontanée / réfléchie ; psychologique / morale ; intentionnalité (Husserl)."},{"t":"La valeur de la conscience","verrou":true},{"t":"Les limites de la conscience","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Philosophie de Première A","famille":"Vie sociale et culturelle","agir":"Réfléchir sur la conscience pour assumer ses actes","situation":"Ton cousin de Mbalmayo a insulté sa sœur sous le coup de la colère. Il se défend : « Ce n'est pas moi, je n'étais pas conscient de ce que je disais. »","tache":"Répondre de manière argumentée à la question de la responsabilité sans conscience."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-francais-lecture-methodique",{"c":"1re A","m":"francais","rang":5,"titre":"Commentaire composé : la lecture méthodique du texte","duree":25,"accroche":"Observer, supposer, vérifier : lire un texte comme un enquêteur.","intro":"Après l'analyse de la consigne vient le travail sur le texte lui-même. La lecture méthodique est une démarche organisée qui part de l'observation des faits d'écriture pour construire des hypothèses de lecture, puis les vérifier. C'est elle qui fournit la matière du commentaire composé.","objectifs":["conduire une première lecture d'observation","formuler des hypothèses de lecture","relever et interpréter les procédés dans un tableau"],"parties":[{"t":"Observer le texte","html":"<div class='def'><b>Définition</b>La <strong>lecture méthodique</strong> est une démarche d'analyse qui part de l'observation des faits d'écriture pour formuler des hypothèses de lecture, puis les vérifier dans le texte.</div><ul><li><strong>Le paratexte</strong> : auteur, œuvre, date, genre, mouvement.</li><li><strong>La forme</strong> : vers ou prose, strophes, longueur, ponctuation, structure visible.</li><li><strong>L'énonciation</strong> : qui parle (je, nous, il), à qui (tu, vous, apostrophes), quand et où (indices de temps et de lieu).</li><li><strong>Les champs lexicaux</strong> dominants, les répétitions, les mots marquants.</li><li><strong>La tonalité</strong> : lyrique, épique, élégiaque, polémique, satirique, tragique.</li></ul><div class='astuce'><b>Astuce</b>Lis le texte au moins trois fois : une fois pour comprendre, une fois crayon en main, une fois à voix basse pour entendre le rythme.</div>","retenir":"Paratexte, forme, énonciation, champs lexicaux, tonalité : la grille d'observation."},{"t":"Formuler des hypothèses de lecture","verrou":true},{"t":"Vérifier : le tableau d'analyse","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Français de Première et Terminale A","famille":"Vie sociale et culturelle","agir":"Conduire la lecture méthodique d'un texte pour préparer un commentaire composé","situation":"En préparation du commentaire composé, ton groupe d'étude à Foumban reçoit un poème qui parle d'un village abandonné après l'exode des jeunes vers la ville. Personne ne sait par où commencer.","tache":"Décrire la démarche, proposer des hypothèses de lecture et les procédés à chercher."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-histoire-imperialisme",{"c":"1re A","m":"histoire","rang":3,"titre":"Les fondements de l'impérialisme européen","duree":25,"accroche":"Pourquoi l'Europe a-t-elle voulu se partager l'Afrique à la fin du XIXᵉ siècle ?","intro":"Entre 1880 et 1914, les puissances européennes se lancent dans une course aux colonies : en une trentaine d'années, presque toute l'Afrique est conquise et partagée. Cette expansion, appelée impérialisme, a des causes économiques, politiques, démographiques, idéologiques et scientifiques, que les Européens de l'époque exposaient sans détour.","objectifs":["définir l'impérialisme","expliquer ses fondements économiques, politiques, démographiques et idéologiques","porter un regard critique sur les justifications de la colonisation"],"parties":[{"t":"Définition et fondements économiques","html":"<div class='def'><b>Définition</b>L'<strong>impérialisme</strong> est la volonté d'un État d'étendre sa domination politique, économique et culturelle sur d'autres territoires et peuples. La <strong>colonisation</strong> en est la forme la plus directe.</div><ul><li>Les industries européennes ont besoin de <strong>matières premières</strong> (caoutchouc, huile de palme, coton, cacao, minerais).</li><li>Elles cherchent des <strong>débouchés</strong> pour leurs produits manufacturés, protégés par le <strong>protectionnisme</strong> des pays rivaux.</li><li>Les banques veulent placer des <strong>capitaux</strong> dans des investissements rentables (chemins de fer, mines, plantations).</li></ul><div class='ex'><b>Jules Ferry (1885)</b>« La politique coloniale est fille de la politique industrielle. »</div>","retenir":"Impérialisme : domination ; fondements économiques : matières premières, débouchés, capitaux."},{"t":"Fondements politiques et démographiques","verrou":true},{"t":"Fondements idéologiques, religieux et scientifiques","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Histoire de Première","famille":"Citoyenneté","agir":"Analyser les fondements de l'impérialisme avec un regard critique","situation":"Lors d'une exposition au musée national de Yaoundé, un visiteur affirme devant une carte de l'Afrique en 1914 : « Les Européens sont venus pour nous civiliser, c'était une bonne chose. »","tache":"Lui répondre en exposant les vrais fondements de l'impérialisme et les limites de cet argument."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-geo-migrations",{"c":"1re A","m":"geo","rang":5,"titre":"Les migrations dans le monde","duree":25,"accroche":"Environ 280 millions de personnes vivent hors de leur pays de naissance.","intro":"Partir chercher du travail en ville, fuir une guerre, rejoindre sa famille à l'étranger : les migrations sont aussi anciennes que l'humanité. Elles concernent aujourd'hui des centaines de millions de personnes et transforment les sociétés de départ comme d'arrivée. Le Cameroun est à la fois pays de départ, de passage et d'accueil.","objectifs":["définir les différents types de migrations","expliquer les causes des migrations","décrire les grands flux migratoires, dont ceux qui concernent le Cameroun"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Vocabulaire</b>Une <strong>migration</strong> est un déplacement de population d'un lieu à un autre avec changement de résidence durable. <strong>Émigration</strong> : départ d'un pays ; <strong>immigration</strong> : arrivée dans un pays. <strong>Solde migratoire</strong> = immigrants − émigrants.</div><ul><li><strong>Migrations internes</strong> (dans un même pays) : exode rural, migrations entre régions.</li><li><strong>Migrations internationales</strong> : vers un autre pays, régulières ou irrégulières.</li><li><strong>Migrations forcées</strong> : <strong>réfugiés</strong> (qui fuient une persécution ou une guerre et franchissent une frontière) et <strong>déplacés internes</strong> (qui fuient sans quitter leur pays).</li><li>Migrations <strong>temporaires</strong> ou <strong>saisonnières</strong> (transhumance, travaux agricoles) ou <strong>définitives</strong>.</li></ul>","retenir":"Émigration / immigration ; solde migratoire ; internes / internationales ; volontaires / forcées."},{"t":"Les causes des migrations","verrou":true},{"t":"Les grands flux et le Cameroun","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Géographie de Première A","famille":"Citoyenneté","agir":"Analyser les causes et les risques des migrations pour faire des choix éclairés","situation":"Ton camarade de Bamenda, déplacé avec sa famille à Douala, veut tenter de rejoindre l'Europe « par le désert », comme un cousin parti il y a deux ans dont on n'a plus de nouvelles.","tache":"Expliquer sa situation, les risques de la migration irrégulière et proposer des alternatives."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-philo-reorientation",{"c":"1re A","m":"philo","rang":3,"titre":"La réorientation actuelle du débat philosophique africain","duree":25,"accroche":"Plus de 250 peuples, deux langues officielles, un seul pays : vivre ensemble se pense.","intro":"Les philosophes africains d'aujourd'hui ne se demandent plus seulement s'il existe une philosophie africaine : ils réfléchissent aux problèmes concrets du continent. Comment des peuples différents peuvent-ils former une nation ? Comment gouverner de façon juste et efficace ? Ce sont les thèmes du vivre-ensemble et de la gouvernance.","objectifs":["définir le vivre-ensemble et la bonne gouvernance","présenter des réflexions africaines sur ces thèmes","appliquer ces notions à des situations camerounaises"],"parties":[{"t":"Le vivre-ensemble","html":"<div class='def'><b>Définition</b>Le <strong>vivre-ensemble</strong> désigne la capacité de personnes et de groupes différents (ethnies, langues, religions, régions) à partager un même espace dans la paix, le respect mutuel et la solidarité, en reconnaissant leurs différences sans en faire des motifs d'exclusion.</div><ul><li>La pensée <strong>ubuntu</strong> d'Afrique australe, popularisée par Desmond Tutu : « Je suis parce que nous sommes » ; l'homme n'existe pleinement qu'en relation.</li><li><strong>Achille Mbembe</strong>, philosophe camerounais, analyse dans <em>Politique de l'inimitié</em> (2016) la tentation de définir son identité contre un ennemi.</li><li>Kant parlait déjà de l'« insociable sociabilité » des hommes : nous avons besoin des autres, mais nous leur résistons.</li></ul><div class='savais'><b>Le savais-tu ?</b>Le Cameroun a créé en 2017 une Commission nationale pour la promotion du bilinguisme et du multiculturalisme, chargée de veiller au vivre-ensemble.</div>","retenir":"Vivre-ensemble : reconnaître les différences sans exclure ; ubuntu : « Je suis parce que nous sommes »."},{"t":"La gouvernance","verrou":true},{"t":"Le rôle du philosophe","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Philosophie de Première A","famille":"Citoyenneté","agir":"Mobiliser les notions de vivre-ensemble et de gouvernance pour apaiser un conflit","situation":"Dans ton quartier à Douala, un forage financé par la mairie est en panne depuis six mois. Des habitants accusent « ceux de l'autre communauté » d'avoir détourné l'argent ; la tension monte.","tache":"Analyser la situation et proposer une démarche pacifique."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-philo-dissertation",{"c":"1re A","m":"philo","rang":4,"titre":"La dissertation philosophique : principes et méthode","duree":30,"accroche":"Une dissertation n'est pas un exposé : c'est un problème que l'on résout.","intro":"Au baccalauréat, la dissertation philosophique compte autant que ta réflexion personnelle que tes connaissances. Le correcteur attend un problème clairement posé, un raisonnement qui avance et une réponse argumentée. Cette leçon reprend les exigences et donne une méthode pas à pas.","objectifs":["analyser un sujet et dégager une problématique","construire un plan dialectique (thèse, antithèse, synthèse)","rédiger une introduction et une conclusion conformes"],"parties":[{"t":"Comprendre le sujet et poser le problème","html":"<div class='def'><b>Définition</b>La <strong>dissertation philosophique</strong> est une réflexion argumentée et organisée qui répond à une question en examinant des positions opposées, pour aboutir à une réponse personnelle et justifiée.</div><ol><li><strong>Lire le sujet mot à mot</strong> : définir chaque notion (« liberté », « bonheur », « travail »), repérer les mots de liaison (« seulement », « toujours », « peut-on », « doit-on »).</li><li><strong>Reformuler</strong> le sujet avec tes propres mots.</li><li><strong>Repérer la tension</strong> : la réponse spontanée et ce qui la contredit.</li><li><strong>Formuler la problématique</strong> sous forme d'une ou deux questions qui montrent pourquoi la réponse n'est pas évidente.</li></ol><div class='ex'><b>Exemple</b>Sujet : « Le travail est-il seulement une contrainte ? » Réponse spontanée : oui, on travaille pour vivre. Mais le travail permet aussi de se réaliser (Hegel, Marx). Problématique : le travail n'est-il qu'une nécessité subie, ou peut-il être le lieu où l'homme se forme et se libère ?</div><div class='attention'><b>Attention</b>Le hors-sujet est la faute la plus lourde : un exposé sur « le travail en général » ne répond pas au mot « seulement ».</div>","retenir":"Définir, reformuler, repérer la tension, poser la problématique."},{"t":"Construire le plan dialectique","verrou":true},{"t":"Introduction et conclusion","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Philosophie de Première A","famille":"Vie sociale et culturelle","agir":"Construire une réflexion argumentée sur une question philosophique","situation":"Au bac blanc de ton lycée à Ebolowa, le sujet est : « Le bonheur dépend-il de l'argent ? » Ton camarade a écrit trois pages sur la pauvreté au Cameroun, sans définir le bonheur ni poser de question. Il a obtenu 6/20.","tache":"Identifier ses erreurs et proposer une introduction et un plan dialectique."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-philo-inconscient",{"c":"1re A","m":"philo","rang":9,"titre":"L'inconscient : valeur et limites de la psychanalyse","duree":30,"accroche":"Et si l'essentiel de ce que nous sommes nous échappait ?","intro":"On croit savoir pourquoi on agit. Pourtant, un mot qui nous échappe, un oubli étrange, un rêve récurrent semblent dire autre chose. Au début du XXᵉ siècle, Sigmund Freud fait de l'inconscient une hypothèse scientifique et invente une méthode pour l'explorer, la psychanalyse. Cette découverte bouleverse l'idée que l'homme se fait de sa liberté.","objectifs":["définir l'inconscient et en distinguer les formes","expliquer les principaux concepts de la psychanalyse","évaluer la valeur et les limites de la théorie freudienne"],"parties":[{"t":"Définitions et formes de l'inconscient","html":"<div class='def'><b>Définition</b>Au sens large, l'<strong>inconscient</strong> désigne ce qui, en nous, échappe à la conscience. Au sens freudien, c'est une <strong>partie du psychisme</strong> formée de désirs et de souvenirs <strong>refoulés</strong>, qui agissent sur nos pensées et nos actes à notre insu.</div><ul><li><strong>Inconscient physiologique</strong> : battements du cœur, digestion, réflexes.</li><li><strong>Automatismes et habitudes</strong> : marcher, écrire sans y penser ; Leibniz parle des « petites perceptions » trop faibles pour être remarquées.</li><li><strong>Inconscient psychique</strong> (Freud) : des désirs interdits, refoulés, cherchent à s'exprimer.</li><li><strong>Inconscient collectif</strong> (Jung) : images et symboles communs à l'humanité.</li></ul>","retenir":"Inconscient : ce qui échappe à la conscience ; chez Freud, des désirs refoulés actifs."},{"t":"La découverte freudienne","verrou":true},{"t":"Valeur et limites de la psychanalyse","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Philosophie de Première A","famille":"Vie sociale et culturelle","agir":"Réfléchir sur l'inconscient pour assumer ses actes","situation":"Dans un taxi à Yaoundé, un passager accusé d'avoir menti répond : « C'est mon inconscient, je n'y peux rien. » Le chauffeur lui rétorque qu'on ne se cache pas derrière Freud.","tache":"Traiter la question de la responsabilité face à l'inconscient."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-philo-commentaire",{"c":"1re A","m":"philo","rang":6,"titre":"Le commentaire philosophique : méthode","duree":30,"accroche":"Commenter, ce n'est ni résumer ni réciter : c'est dialoguer avec un auteur.","intro":"Au Probatoire, la seconde partie de l'épreuve est un commentaire de texte ou une dissertation, noté sur 9 points (introduction 3, développement 3, conclusion 3). Le commentaire demande de comprendre un texte, de l'expliquer, puis de le discuter. Cette leçon donne une méthode en étapes claires.","objectifs":["dégager le thème, le problème, la thèse et la structure d'un texte","rédiger l'étude analytique sans paraphrase","discuter le texte (réfutation, réinterprétation) et conclure sur son intérêt"],"parties":[{"t":"Lire et comprendre le texte","html":"<div class='def'><b>Définition</b>Le <strong>commentaire philosophique</strong> est l'explication et la discussion d'un texte : on montre ce que l'auteur affirme, comment il le justifie, puis ce que vaut sa position.</div><ol><li><strong>Thème</strong> : de quoi parle le texte ?</li><li><strong>Problème</strong> : quelle question se pose l'auteur ?</li><li><strong>Thèse</strong> : quelle réponse défend-il ?</li><li><strong>Structure</strong> : les moments du texte, repérés grâce aux connecteurs (mais, donc, car, en effet).</li></ol>","retenir":"Thème, problème, thèse, structure : la carte d'identité du texte."},{"t":"Rédiger le commentaire","verrou":true},{"t":"Un exemple guidé","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Philosophie de Première A","famille":"Vie sociale et culturelle","agir":"Commenter un texte philosophique pour éclairer une situation vécue","situation":"Après avoir raté son examen blanc à Maroua, ta camarade est abattue : « Tout est perdu. » Ton professeur vous donne à commenter le texte d'Épictète ci-dessus.","tache":"Rédiger l'introduction et la conclusion du commentaire et en tirer une leçon."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-histoire-conquetes-francaises",{"c":"1re A","m":"histoire","rang":5,"titre":"Les conquêtes françaises en Afrique","duree":25,"accroche":"De Dakar au lac Tchad : la France taille un empire à coups de colonnes militaires.","intro":"Entre 1830 et 1912, la France conquiert un immense domaine en Afrique du Nord, de l'Ouest, du Centre et à Madagascar. Elle se heurte partout à des résistances. Une de ses batailles décisives se déroule sur le sol actuel du Cameroun, à Kousséri.","objectifs":["situer les étapes et les zones des conquêtes françaises","décrire les méthodes de conquête","présenter les grandes résistances et l'organisation des colonies (AOF, AEF)"],"parties":[{"t":"Les étapes de la conquête","html":"<div class='def'><b>Définition</b>La <strong>conquête coloniale</strong> est la prise de contrôle militaire, politique et économique d'un territoire et de ses habitants par une puissance étrangère.</div><ul><li><strong>Afrique du Nord</strong> : Algérie (à partir de 1830), protectorats sur la Tunisie (1881) et le Maroc (1912).</li><li><strong>Afrique de l'Ouest</strong> : à partir du Sénégal (gouverneur Faidherbe, 1854-1865), pénétration vers le Niger ; Dahomey (1892-1894).</li><li><strong>Afrique centrale</strong> : Savorgnan de Brazza signe le traité avec le roi Makoko (1880) ; vers le Tchad.</li><li><strong>Madagascar</strong> : conquise en 1895-1896.</li></ul>","retenir":"Algérie 1830, Tunisie 1881, Maroc 1912 ; Sénégal-Niger ; Congo-Tchad ; Madagascar 1896."},{"t":"Les méthodes et les résistances","verrou":true},{"t":"L'organisation de l'empire","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Histoire de Première","famille":"Citoyenneté","agir":"Expliquer les conquêtes coloniales et en garder une mémoire juste","situation":"En visite à Kousséri, un groupe d'élèves de Maroua découvre une stèle commémorant la bataille de 1900, qui ne cite que les officiers français.","tache":"Rédiger un panneau complémentaire sur la bataille, Rabah et les populations."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-histoire-conquetes-anglaises",{"c":"1re A","m":"histoire","rang":6,"titre":"Les conquêtes anglaises en Afrique","duree":25,"accroche":"« Du Cap au Caire » : le rêve d'un empire britannique d'un bout à l'autre de l'Afrique.","intro":"Première puissance industrielle et maritime du XIXᵉ siècle, la Grande-Bretagne veut contrôler les routes vers l'Inde et les richesses de l'Afrique. Elle conquiert l'Égypte, le Soudan, l'Afrique australe, une partie de l'Afrique de l'Ouest et de l'Est, en se heurtant à de fortes résistances, et gouverne souvent par l'intermédiaire des chefs locaux.","objectifs":["situer les principales conquêtes britanniques","présenter les résistances africaines","expliquer l'indirect rule"],"parties":[{"t":"Les grandes zones de conquête","html":"<div class='def'><b>Définition</b>L'<strong>Empire britannique</strong> est l'ensemble des territoires dominés par la Grande-Bretagne ; en Afrique, il vise la maîtrise des routes vers l'Inde (canal de Suez, Le Cap) et des ressources (or, diamants, huile de palme).</div><ul><li><strong>Égypte</strong> : occupée en 1882 (bataille de Tell el-Kébir) pour contrôler le canal de Suez.</li><li><strong>Soudan</strong> : Kitchener écrase les mahdistes à <strong>Omdurman</strong> (1898).</li><li><strong>Afrique australe</strong> : colonie du Cap ; Cecil Rhodes et sa compagnie conquièrent les Rhodésies ; guerre contre les Boers (1899-1902).</li><li><strong>Afrique de l'Ouest</strong> : Nigeria (Lagos 1861, Royal Niger Company), Gold Coast (Ghana), Sierra Leone, Gambie.</li><li><strong>Afrique de l'Est</strong> : Kenya, Ouganda.</li></ul>","retenir":"Égypte (1882), Soudan (1898), Afrique australe (Rhodes, Boers), Nigeria, Gold Coast, Kenya."},{"t":"Les résistances","verrou":true},{"t":"L'administration : l'indirect rule","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Histoire de Première","famille":"Citoyenneté","agir":"Expliquer les héritages coloniaux pour renforcer l'unité nationale","situation":"Lors d'un débat au lycée bilingue de Buea, un élève demande pourquoi les régions du Nord-Ouest et du Sud-Ouest ont un système scolaire et juridique différent.","tache":"Expliquer l'origine historique de cette différence."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-geo-incidences-migrations",{"c":"1re A","m":"geo","rang":6,"titre":"Problèmes et incidences socioéconomiques des migrations","duree":25,"accroche":"Celui qui part laisse un vide ; celui qui arrive change sa ville : la migration transforme les deux bouts du chemin.","intro":"Les migrations n'ont pas seulement des causes : elles ont des effets, positifs et négatifs, dans les régions de départ comme dans celles d'arrivée. Au Cameroun, l'exode rural vide certains villages tandis que Douala et Yaoundé débordent ; la diaspora envoie des fonds, et les régions de l'Est et de l'Extrême-Nord accueillent des réfugiés.","objectifs":["identifier les incidences des migrations dans les régions de départ","identifier les incidences dans les régions d'arrivée","évaluer le bilan des migrations au Cameroun"],"parties":[{"t":"Dans les régions de départ","html":"<div class='def'><b>Définition</b>Les <strong>incidences socioéconomiques</strong> des migrations sont leurs effets sur la population, l'emploi, les revenus, les services et la vie sociale des régions de départ et d'arrivée.</div><div class='attention'><b>Effets négatifs</b>Départ des jeunes actifs ; <strong>vieillissement</strong> des villages et baisse de la production agricole ; <strong>fuite des cerveaux</strong> (médecins, ingénieurs formés au pays qui partent à l'étranger) ; familles séparées.</div><div class='ex'><b>Effets positifs</b>Les <strong>transferts de fonds</strong> des migrants financent la scolarité, les soins, les maisons, parfois de petites entreprises ; retour de compétences et d'idées ; baisse de la pression sur la terre.</div>","retenir":"Au départ : vieillissement, fuite des cerveaux, mais transferts de fonds et compétences."},{"t":"Dans les régions d'arrivée","verrou":true},{"t":"Le bilan au Cameroun","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Géographie de Première A","famille":"Vie économique","agir":"Évaluer les incidences des migrations pour orienter le développement local","situation":"Le village de Bangangté a perdu la moitié de ses jeunes partis à Douala ou en Europe. Les champs sont abandonnés, mais de belles maisons sont construites avec l'argent des émigrés. Le chef réunit les élites pour un plan de développement.","tache":"Faire le bilan et proposer des mesures pour un développement collectif."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-anglais-modals",{"c":"1re A","m":"anglais","rang":2,"titre":"Modals: permission, possibility, obligation, advice and deduction","duree":25,"accroche":"May I go out? You must be tired! You needn't come: small words, big differences.","intro":"Modal verbs (can, may, must, should…) add an attitude to the main verb: permission, ability, possibility, obligation, advice or deduction. They are tested in almost every Probatoire and Baccalauréat paper.","objectifs":["form sentences with modal verbs","choose the right modal for permission, possibility, obligation, absence of obligation and advice","use must and can't for deduction"],"parties":[{"t":"What is a modal verb?","html":"<div class='def'><b>Definition</b>A <strong>modal verb</strong> is an auxiliary placed before a <strong>bare infinitive</strong> (without « to ») to express the speaker's attitude. It never takes « -s » and makes its question and negative without « do »: <em>She can swim. Can she swim? She cannot (can't) swim.</em></div><ul><li><strong>Permission</strong>: <em>can</em>, <em>may</em> (more polite): <em>May I come in, sir?</em></li><li><strong>Possibility</strong>: <em>can</em> (general), <em>could</em>, <em>may</em>, <em>might</em> (less sure): <em>It might rain this afternoon.</em></li></ul><div class='attention'><b>French speakers, watch out!</b>Never « He cans » or « She must to go ». Modal + bare infinitive: <em>She must go.</em></div>","retenir":"Modal + bare infinitive; no -s, no do."},{"t":"Obligation, no obligation, advice","verrou":true},{"t":"Deduction","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Anglais de Première A","famille":"Citoyenneté","agir":"Use modal verbs to give rules, advice and permission in real-life situations","situation":"Your school in Kribi is organising a clean-up campaign on the beach on Saturday. As class prefect, you write the rules for your classmates.","tache":"Write a notice using different modals."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-anglais-purpose-result",{"c":"1re A","m":"anglais","rang":5,"titre":"Expressing purpose, result and preference; let's / let's not","duree":25,"accroche":"I study hard so that I can pass. It rained so much that the road was closed. I'd rather walk.","intro":"To argue, explain or plan, you must say why you do something (purpose), what happens as a consequence (result) and what you prefer. These structures are essential in essays, letters and dialogues.","objectifs":["express purpose with to, in order to, so as to, so that","express result with so … that, such … that, so, therefore","express preference with prefer, would rather, had better, and make suggestions with let's"],"parties":[{"t":"Purpose","html":"<div class='def'><b>Definition</b><strong>Purpose</strong> is the aim of an action: it answers the question « Why? / What for? ».</div><ul><li><strong>to / in order to / so as to + infinitive</strong> (same subject): <em>She saves money (in order) to buy a laptop.</em> Negative: <em>in order not to / so as not to</em>: <em>He left early so as not to miss the bus.</em></li><li><strong>so that + subject + can / could / will / would</strong> (different subjects possible): <em>The teacher speaks slowly so that everybody can understand.</em></li></ul><div class='attention'><b>French speakers, watch out!</b>« Pour + infinitif » is <em>to</em>, never « for to »: <em>I came to see you</em>, not « for to see you ».</div>","retenir":"to / in order to / so as to + infinitive; so that + subject + can / could."},{"t":"Result","verrou":true},{"t":"Preference, advice and suggestion","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Anglais de Première A","famille":"Vie sociale et culturelle","agir":"Express purpose, result and preference to take decisions in a group","situation":"Your class in Bafoussam wants to raise money for the end-of-year trip. The class meeting must choose between selling snacks at break time and organising a cultural evening.","tache":"Write a dialogue using purpose, result, preference and let's."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-anglais-prepositions",{"c":"1re A","m":"anglais","rang":8,"titre":"Prepositions of place, time, manner and direction","duree":20,"accroche":"In Douala, on Monday, at 7 a.m., by taxi, towards the port: prepositions place everything.","intro":"Prepositions are short words, but they cause many mistakes, because they rarely translate word for word from French. This lesson organises them by meaning: place, time, manner and direction.","objectifs":["use prepositions of place and time correctly","use prepositions of direction and manner","avoid the most common French-speaker mistakes"],"parties":[{"t":"Place and time: at, on, in","html":"<div class='def'><b>Definition</b>A <strong>preposition</strong> is a word placed before a noun or pronoun to show its relation to another word: place, time, direction, manner. A <strong>prepositional phrase</strong> is the preposition + its noun: <em>under the table, in the morning</em>.</div><ul><li><strong>Place</strong>: <em>at</em> a point (at the bus stop, at school), <em>on</em> a surface or a street (on the wall, on Joss Street), <em>in</em> an enclosed space, town or country (in the classroom, in Garoua, in Cameroon).</li><li><strong>Time</strong>: <em>at</em> + clock time and festivals (at 7 o'clock, at Christmas), <em>on</em> + days and dates (on Monday, on 20th May), <em>in</em> + months, years, seasons, parts of the day (in May, in 1960, in the dry season, in the morning).</li></ul>","retenir":"at (point / hour), on (surface / day), in (inside / month, year)."},{"t":"Direction and movement","verrou":true},{"t":"Manner and fixed expressions","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Anglais de Première A","famille":"Vie sociale et culturelle","agir":"Use prepositions to give precise directions and times","situation":"A pen friend from Ghana is coming to visit you in Buea. She will arrive at the Douala airport and must find your house alone.","tache":"Write an e-mail with precise directions using prepositions."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-anglais-conditionals",{"c":"1re A","m":"anglais","rang":10,"titre":"Conditionals: types 1, 2 and 3","duree":25,"accroche":"If it rains, we'll stay. If I were rich, I'd build a school. If I had revised, I would have passed.","intro":"Conditional sentences link a condition (the if-clause) and its consequence. English has three main types, each with its own tenses. They are among the most frequent grammar questions at the Probatoire and the Baccalauréat.","objectifs":["form the three types of conditional sentences","choose the type according to the meaning (real, unreal present, unreal past)","use unless, provided that and as long as"],"parties":[{"t":"Type 1: real or possible","html":"<div class='def'><b>Definition</b>A <strong>conditional sentence</strong> has two clauses: the <strong>if-clause</strong> (condition) and the <strong>main clause</strong> (result). <strong>Type 1</strong> describes a <strong>real or likely</strong> situation in the present or future.</div><p class='formule'>If + simple present → will + bare infinitive</p><ul><li><em>If you study hard, you will pass.</em></li><li><em>If it rains, the match will be cancelled.</em></li></ul><div class='attention'><b>French speakers, watch out!</b>No « will » in the if-clause: <em>If he comes</em>, not « If he will come ».</div>","retenir":"Type 1: if + present, will + infinitive (possible)."},{"t":"Type 2: unreal present","verrou":true},{"t":"Type 3 and other conjunctions","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Anglais de Première A","famille":"Citoyenneté","agir":"Use conditionals to imagine solutions and express regrets","situation":"Your school's English club in Ngaoundéré organises an essay competition on the topic: « If I were the mayor of my town ».","tache":"Write a short essay using the three types of conditionals."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-histoire-reactions-africaines",{"c":"1re A","m":"histoire","rang":8,"titre":"Les réactions africaines face aux agressions européennes : résistances et collaborations","duree":25,"accroche":"Résister ou s'allier : deux réponses africaines à une même conquête.","intro":"Face à la conquête européenne, les sociétés africaines n'ont pas réagi d'une seule façon. Beaucoup ont résisté par les armes ou autrement ; d'autres ont choisi de collaborer, par calcul, par contrainte ou pour se protéger de voisins rivaux. Comprendre ces choix évite de juger le passé avec simplisme.","objectifs":["présenter les formes de résistance","expliquer les raisons et les formes de la collaboration","illustrer ces réactions par des exemples africains et camerounais"],"parties":[{"t":"Les résistances","html":"<div class='def'><b>Définitions</b>La <strong>résistance</strong> est l'opposition à la conquête et à la domination coloniales. La <strong>collaboration</strong> est le choix de coopérer avec le colonisateur.</div><ul><li><strong>Résistance armée</strong> : Samory Touré (capturé en 1898), Béhanzin au Dahomey (1894), Menelik II à Adoua (1896), Rabah (Kousséri, 1900), les Zoulous (Isandhlwana, 1879).</li><li><strong>Résistances passives</strong> : fuite, refus de l'impôt et du travail forcé.</li><li><strong>Résistances religieuses</strong> : mouvements prophétiques.</li><li>Au Cameroun : les Bakweri de Kuva Likenye, le soulèvement des Bulu (1899-1901), Rudolf Duala Manga Bell et Martin-Paul Samba, exécutés en 1914.</li></ul>","retenir":"Résistances armées (Samory, Béhanzin, Menelik, Rabah), passives, religieuses ; au Cameroun : Bakweri, Bulu, Duala Manga Bell, Samba."},{"t":"Les collaborations","verrou":true},{"t":"Des choix complexes","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Histoire de Première","famille":"Citoyenneté","agir":"Analyser les réactions africaines à la conquête sans simplisme","situation":"Lors d'un exposé à Foumban, un élève accuse le roi Njoya d'avoir « trahi l'Afrique » en s'alliant aux Allemands ; un autre répond qu'il a sauvé son royaume.","tache":"Expliquer la complexité des réactions africaines et donner un point de vue argumenté."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-histoire-exploitation-colonies",{"c":"1re A","m":"histoire","rang":9,"titre":"L'exploitation économique des colonies","duree":25,"accroche":"Cacao, caoutchouc, coton : produire pour la métropole, à n'importe quel prix.","intro":"Une fois la conquête achevée, les puissances coloniales organisent l'exploitation économique de l'Afrique au profit de la métropole. Les colonies doivent fournir des matières premières à bas prix et acheter des produits manufacturés. Ce système repose sur la contrainte : impôt, cultures obligatoires, travail forcé.","objectifs":["décrire l'économie de traite","présenter les méthodes de l'exploitation (impôt, travail forcé, sociétés concessionnaires)","mesurer les conséquences pour les Africains et pour l'économie actuelle"],"parties":[{"t":"L'économie de traite","html":"<div class='def'><b>Définition</b>L'<strong>économie de traite</strong> est le système dans lequel la colonie produit des matières premières agricoles ou minières pour l'exportation et achète des produits manufacturés à la métropole, par l'intermédiaire de maisons de commerce.</div><ul><li><strong>Cultures d'exportation</strong> : cacao, café, arachide, coton, huile de palme, caoutchouc, banane.</li><li><strong>Produits miniers</strong> : cuivre du Katanga (Congo belge), or de Gold Coast.</li><li><strong>Infrastructures</strong> orientées vers les ports : chemins de fer et routes de l'intérieur vers la côte (au Cameroun, lignes Douala-Nkongsamba et Douala-Yaoundé).</li></ul>","retenir":"Exporter des matières premières, importer des produits manufacturés ; routes et rails vers les ports."},{"t":"Les méthodes : la contrainte","verrou":true},{"t":"Les conséquences","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Histoire de Première","famille":"Vie économique","agir":"Expliquer l'origine coloniale de problèmes économiques et fonciers actuels","situation":"Les terres de la Cameroon Development Corporation (CDC), autour de Buea et Tiko, sont d'anciennes plantations allemandes. Des descendants de familles bakweri en réclament une partie.","tache":"Expliquer l'origine du problème et proposer un règlement pacifique."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-geo-reglement-migrations",{"c":"1re A","m":"geo","rang":7,"titre":"Les tentatives de règlement des problèmes migratoires","duree":25,"accroche":"Ni murs ni portes grandes ouvertes : comment organiser les migrations ?","intro":"Les migrations posent des problèmes aux pays de départ (fuite des jeunes et des cerveaux), de transit (trafics, drames humains) et d'accueil (intégration, tensions). États et organisations internationales cherchent des solutions : protéger les réfugiés, organiser la circulation, combattre les trafics, fixer les jeunes chez eux par le développement.","objectifs":["présenter les cadres internationaux de règlement","présenter les politiques régionales et nationales","évaluer leurs résultats et leurs limites"],"parties":[{"t":"Le cadre international","html":"<div class='def'><b>Définition</b>Une <strong>politique migratoire</strong> est l'ensemble des mesures prises pour encadrer les entrées, les sorties, l'accueil et l'intégration des migrants.</div><ul><li>La <strong>Convention de Genève</strong> (1951) définit le réfugié et le protège contre le renvoi vers un pays où il est menacé ; le <strong>HCR</strong> l'applique.</li><li>L'<strong>OIM</strong> (Organisation internationale pour les migrations) aide les États et les migrants (retours volontaires, informations).</li><li>Le <strong>Pacte mondial pour des migrations sûres, ordonnées et régulières</strong> (Marrakech, 2018).</li><li>La lutte contre la <strong>traite des personnes</strong> (protocole de Palerme, 2000).</li></ul>","retenir":"Genève (1951), HCR, OIM, Pacte de Marrakech (2018), Palerme (2000)."},{"t":"Les politiques africaines et nationales","verrou":true},{"t":"Résultats et limites","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Géographie de Première A","famille":"Citoyenneté","agir":"Proposer des solutions locales aux problèmes migratoires","situation":"Le maire d'une commune de l'Ouest constate que de nombreux jeunes partent vers Douala ou tentent la route de l'Europe. Il réunit un conseil pour proposer des solutions.","tache":"Proposer un plan de quatre mesures avec acteurs et résultats attendus."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-francais-introduction-commentaire",{"c":"1re A","m":"francais","rang":9,"titre":"Commentaire composé : rédiger l'introduction","duree":25,"accroche":"Dix lignes qui décident souvent de la note.","intro":"L'introduction est la première impression du correcteur. Elle doit situer le texte, le présenter, poser un projet de lecture et annoncer les centres d'intérêt. Au Probatoire comme au Baccalauréat, le jury attend une introduction problématisée, sans paraphrase ni généralités.","objectifs":["connaître les quatre temps de l'introduction","formuler un projet de lecture","rédiger une introduction complète et concise"],"parties":[{"t":"Les quatre temps de l'introduction","html":"<div class='def'><b>Définition</b>L'<strong>introduction</strong> du commentaire composé est un paragraphe d'environ dix lignes qui situe le texte, le présente, pose un <strong>projet de lecture</strong> (problématique) et <strong>annonce le plan</strong>.</div><ol><li><strong>L'amorce</strong> : l'auteur, l'œuvre, l'époque, le mouvement littéraire.</li><li><strong>La présentation</strong> du texte : nature (poème, extrait de roman, scène), thème, situation dans l'œuvre.</li><li><strong>Le projet de lecture</strong> : « En quoi ce poème… ? », « Comment l'auteur… ? »</li><li><strong>L'annonce du plan</strong> : les centres d'intérêt.</li></ol>","retenir":"Amorce, présentation, projet de lecture, annonce du plan."},{"t":"Formuler le projet de lecture","verrou":true},{"t":"Un modèle d'introduction","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Français de Première et Terminale A","famille":"Vie sociale et culturelle","agir":"Rédiger une introduction de commentaire composé conforme aux attentes du jury","situation":"En devoir à Maroua, la consigne est : « Vous ferez de ce poème de la négritude un commentaire composé. Vous montrerez par exemple comment le poète célèbre la femme africaine et, à travers elle, l'Afrique. »","tache":"Rédiger une introduction complète en quatre temps."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-anglais-reading-disputes",{"c":"1re A","m":"anglais","rang":7,"titre":"Reading comprehension: settling community disputes","duree":25,"accroche":"Read, understand, explain in your own words: the keys to Section C.","intro":"In the Probatoire and the Baccalauréat, the reading comprehension section tests your ability to understand a text, find information, explain words and statements in your own words, and give your opinion. This lesson trains these skills on a text about settling disputes in a Cameroonian community.","objectifs":["use reading strategies: skimming, scanning, guessing meaning from context","answer comprehension questions in your own words","use the vocabulary of conflict and mediation"],"parties":[{"t":"Reading strategies","html":"<div class='def'><b>Definitions</b><strong>Skimming</strong>: reading quickly to get the general idea. <strong>Scanning</strong>: looking for a specific piece of information (a name, a date). <strong>Inferring</strong>: guessing the meaning of a word or idea from the context.</div><ol><li>Read the questions first, then the text.</li><li>Skim the text for the main idea (title, first and last sentences).</li><li>Scan for the answers; underline the lines.</li><li>Answer in <strong>your own words</strong> unless you are asked to quote.</li></ol>","retenir":"Skim for the main idea, scan for details, infer from context, answer in your own words."},{"t":"The text","verrou":true},{"t":"Vocabulary of disputes","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Anglais de 1re A","famille":"Citoyenneté","agir":"Read and understand texts on conflict resolution and propose peaceful solutions","situation":"In your quarter in Bamenda, two neighbours have been quarrelling for weeks about a fence. The quarter head asks students to suggest a way to settle the dispute.","tache":"Write a letter proposing a mediation meeting and a fair solution."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-philo-personne",{"c":"1re A","m":"philo","rang":10,"titre":"Personnalité, personnage, personne","duree":25,"accroche":"Qui suis-je : mon caractère, mon rôle, ou un être digne de respect ?","intro":"On dit d'un camarade qu'il « a de la personnalité », d'un acteur qu'il joue un « personnage », et qu'il faut respecter « la personne humaine ». Trois mots de même racine, trois réalités différentes. Les distinguer permet de comprendre ce qui fait la valeur de chaque être humain.","objectifs":["distinguer personnalité, personnage et personne","identifier les facteurs de formation de la personnalité","présenter la valeur de la personne chez Kant et Mounier"],"parties":[{"t":"Trois notions à distinguer","html":"<div class='def'><b>Définitions</b>La <strong>personnalité</strong> est l'ensemble des traits psychologiques qui caractérisent un individu. Le <strong>personnage</strong> est le rôle social que l'on joue (du latin <em>persona</em>, masque de théâtre). La <strong>personne</strong> est l'être humain en tant qu'il est doté de <strong>conscience</strong>, de <strong>raison</strong> et de <strong>liberté</strong>, sujet de droits et de devoirs.</div><div class='ex'><b>Exemple</b>Un professeur a une personnalité (calme, exigeant), joue un personnage en classe (l'autorité), et reste une personne qu'aucun rôle ne résume.</div>","retenir":"Personnalité : traits ; personnage : rôle, masque ; personne : être conscient, libre, digne."},{"t":"Les facteurs de la personnalité","verrou":true},{"t":"La valeur de la personne","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Philosophie de Première A","famille":"Citoyenneté","agir":"Défendre la dignité de la personne","situation":"Dans un quartier de Douala, un employeur fait travailler des jeunes « aides ménagères » venues du village, sans salaire ni repos, en disant : « Je les nourris, elles m'appartiennent. »","tache":"Rédiger une dissertation courte sur la valeur de la personne humaine."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-histoire-chine-traites",{"c":"1re A","m":"histoire","rang":10,"titre":"La Chine, des traités inégaux à l'éveil du nationalisme","duree":25,"accroche":"L'opium, des canonnières et des traités : un empire millénaire humilié.","intro":"Au XIXᵉ siècle, la Chine des Qing, longtemps puissante, est contrainte par les puissances européennes puis par le Japon à signer des « traités inégaux ». Ces humiliations provoquent des révoltes, puis l'éveil d'un nationalisme chinois qui renverse l'empire en 1911.","objectifs":["expliquer les guerres de l'opium et les traités inégaux","présenter les réactions chinoises (Taiping, Boxers)","décrire la naissance du nationalisme et de la République"],"parties":[{"t":"Les guerres de l'opium et les traités inégaux","html":"<div class='def'><b>Définition</b>Un <strong>traité inégal</strong> est un accord imposé par la force, qui accorde des avantages à une seule partie : ouverture de ports, cession de territoires, privilèges pour les étrangers.</div><ul><li>Les Britanniques vendent illégalement de l'<strong>opium</strong> venu d'Inde ; la Chine l'interdit et détruit des stocks (1839).</li><li><strong>Première guerre de l'opium</strong> (1839-1842) : <strong>traité de Nankin</strong> (1842) : Hong Kong cédée au Royaume-Uni, ports ouverts.</li><li><strong>Seconde guerre de l'opium</strong> (1856-1860) : sac du palais d'Été à Pékin (1860) ; nouveaux ports et privilèges.</li><li>Défaite face au <strong>Japon</strong> (1894-1895) : perte de Taïwan.</li></ul>","retenir":"Opium ; Nankin (1842), Hong Kong ; palais d'Été (1860) ; défaite face au Japon (1895)."},{"t":"Les réactions chinoises","html":"<ul><li><strong>Révolte des Taiping</strong> (1850-1864) : immense soulèvement contre la dynastie Qing ; des millions de morts.</li><li>Tentatives de modernisation, limitées par la cour impériale.</li><li><strong>Révolte des Boxers</strong> (1900) : société secrète qui attaque les étrangers et les missions ; écrasée par une coalition de huit puissances.</li></ul><div class='attention'><b>Le « dépeçage »</b>À la fin du siècle, les puissances se partagent la Chine en zones d'influence, sans la coloniser entièrement.</div>","retenir":"Taiping (1850-1864), Boxers (1900) ; zones d'influence étrangères.","labo":{"type":"etapes","invite":"Avance étape par étape.","items":[["opium","Guerres de l'opium (1839-1842 ; 1856-1860)."],["Traité de Nankin","Traité de Nankin (1842) : Hong Kong ; traités inégaux."],["Défaite face au Japon","Défaite face au Japon (1895) ; zones d'influence."],["Taiping","Révoltes : Taiping (1850-1864), Boxers (1900)."],["Sun Yat-sen","Sun Yat-sen ; République (1912) ; 4 mai 1919 ; PCC (1921)."]]}},{"t":"L'éveil du nationalisme","html":"<ul><li><strong>Sun Yat-sen</strong> fonde un mouvement républicain ; ses « trois principes du peuple » : nationalisme, démocratie, bien-être du peuple.</li><li><strong>Révolution de 1911</strong> : l'empire s'effondre ; la <strong>République</strong> est proclamée le <strong>1er janvier 1912</strong> ; le parti nationaliste (Kuomintang) est créé.</li><li><strong>Mouvement du 4 mai 1919</strong> : les étudiants protestent contre le traité de Versailles, qui donne au Japon des droits sur le Shandong.</li><li>Le <strong>Parti communiste chinois</strong> est fondé en <strong>1921</strong>.</li></ul><div class='ex'><b>Comparaison</b>Comme en Afrique, l'humiliation coloniale a nourri un nationalisme moderne ; il conduira, en Chine, à la victoire communiste de 1949.</div>","retenir":"Sun Yat-sen ; République (1912) ; 4 mai 1919 ; PCC (1921)."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Première partie : l'évaluation des ressources (9 points)</h3><p><strong>1.</strong> Présente et analyse deux formes de réaction des nationalistes chinois face à la domination étrangère, de la fin du XIXe siècle à 1921. Le candidat répondra par un texte de 10 à 15 lignes, en un seul paragraphe. (5 pts)</p><p><strong>2. Texte à corriger (4 pts).</strong> Le texte ci-dessous contient quatre informations erronées.</p><blockquote>« Le traité de Nankin (1842) cède Taïwan au Royaume-Uni. Le traité de Shimonoseki (1895) est signé avec la Russie. La révolte des Taiping a lieu en 1900. Sun Yat-sen proclame la République le 1er janvier 1949. »</blockquote><p>a) Relève les quatre informations erronées. (2 pts) b) Réécris le texte en corrigeant ces erreurs. (2 pts)</p><details><summary>Voir le corrigé de la première partie</summary><p><strong>1.</strong> Préambule : humiliée par les traités inégaux, la Chine voit naître au tournant du XXe siècle un nationalisme moderne. Éléments : la révolte des Boxers (1900), soulèvement contre les étrangers, écrasé par une coalition de huit puissances ; la révolution de 1911 menée par Sun Yat-sen, qui renverse l'empire et proclame la République le 1er janvier 1912 ; on peut citer le mouvement du 4 mai 1919 contre le traité de Versailles. Explications : la xénophobie populaire puis un programme politique moderne (Trois principes du peuple). Bilan : le nationalisme chinois passe de la révolte à la construction d'un État moderne.</p><p><em>Barème : préambule 1 pt (existence 0,5, pertinence 0,5) ; deux éléments 2 pts ; explications 1 pt ; bilan 1 pt.</em></p><p><strong>2.</strong> Erreurs : 1) Taïwan → Hong Kong ; 2) avec la Russie → avec le Japon ; 3) la révolte des Taiping en 1900 → la révolte des Boxers (les Taiping : 1850-1864) ; 4) 1949 → 1912. Texte corrigé : « Le traité de Nankin (1842) cède Hong Kong au Royaume-Uni. Le traité de Shimonoseki (1895) est signé avec le Japon. La révolte des Boxers a lieu en 1900. Sun Yat-sen proclame la République le 1er janvier 1912. »</p></details><h3>Deuxième partie : l'évaluation des compétences (9 points)</h3><p><strong>Thème : Défense de la souveraineté nationale</strong></p><p><strong>Document 1 : Le traité de Shimonoseki</strong></p><blockquote>« … Signé à l'issue de la guerre sino-japonaise de 1895, ce traité exigeait l'indépendance de la Corée, qui fut annexée par le Japon en 1910. Le traité reconnaissait aussi l'autorité du Japon sur l'île de Formose et les îles Pescadores. »</blockquote><p><em>Source : fr.wikipedia.org (document du sujet officiel de Probatoire, histoire, session 2023).</em></p><p><strong>Document 2 : Les Trois principes du peuple de Sun Yat-sen</strong></p><blockquote>Le programme de Sun Yat-sen repose sur le nationalisme (libérer la Chine de la domination étrangère), la démocratie (gouvernement par le peuple) et le bien-être du peuple (meilleure répartition de la terre et des richesses).</blockquote><p><em>Source : Réalisation VÉRITAS (livret HGECM 2026-2027), synthèse.</em></p><p><strong>Consigne.</strong> À partir des documents et de tes connaissances, rédige une production cohérente dont les grandes lignes reposent sur les tâches suivantes :</p><ol><li>Explique, à partir du document 1, en quoi le traité de Shimonoseki illustre la domination subie par la Chine à la fin du XIXe siècle. (3 pts)</li><li>Présente, à partir du document 2 et de tes connaissances, le projet des nationalistes chinois. (3 pts)</li><li>Montre ce que l'exemple chinois enseigne aux pays africains sur la défense de leur souveraineté. (3 pts)</li></ol><p><em>Ta production comportera trois paragraphes, sans numéros ni tirets. Présentation : 2 points.</em></p><details><summary>Voir le corrigé de la deuxième partie</summary><p>Tâche 1 : vaincue par le Japon, la Chine doit renoncer à la Corée et céder Formose (Taïwan) et les Pescadores : comme les traités de Nankin et de Tianjin, c'est un traité imposé par la force qui démembre le pays. Tâche 2 : Sun Yat-sen veut libérer la Chine des étrangers, établir la démocratie et améliorer la vie du peuple ; la révolution de 1911 renverse l'empire et la République est proclamée en 1912 ; le mouvement du 4 mai 1919 prolonge ce nationalisme. Tâche 3 : l'unité nationale, un projet politique clair et le développement économique sont les conditions de la souveraineté ; les divisions favorisent la domination étrangère.</p><p><em>Barème de chaque tâche : pertinence 1 pt, correction de la langue 1 pt, cohérence 1 pt. Présentation : 2 pts.</em></p></details></div>","retenir":"Savoir-être mobilisé : ouverture sur le monde et esprit critique."}],"revision":["Guerres de l'<strong>opium</strong> (1839-1842 ; 1856-1860).","<strong>Traité de Nankin</strong> (1842) : Hong Kong ; traités <strong>inégaux</strong>.","Défaite face au Japon (1895) ; zones d'influence.","Révoltes : <strong>Taiping</strong> (1850-1864), <strong>Boxers</strong> (1900).","<strong>Sun Yat-sen</strong> ; République (1912) ; 4 mai 1919 ; PCC (1921)."],"exo":"<p>Explique pourquoi on parle de traités « inégaux ». <em>(Réponse : Ils sont imposés par la force après des défaites militaires et n'accordent des avantages (ports, territoires, privilèges) qu'aux puissances étrangères.)</em></p>","quiz":[{"q":"La première guerre de l'opium oppose la Chine :","r":["au Royaume-Uni","au Japon","à la France seule","aux États-Unis"],"b":0,"e":"1839-1842."},{"q":"Un traité inégal est :","r":["un accord équilibré","un accord imposé par la force et favorable à une seule partie","un traité de paix africain","une constitution"],"b":1,"e":"Ports ouverts, territoires cédés."},{"q":"La révolte des Boxers a lieu en :","r":["1842","1864","1900","1919"],"b":2,"e":"Écrasée par huit puissances."},{"q":"La République de Chine est proclamée en :","r":["1842","1895","1949","1912"],"b":3,"e":"Le 1er janvier 1912."},{"q":"Les « trois principes du peuple » sont de :","r":["Sun Yat-sen","Mao Zedong","Deng Xiaoping","l'empereur"],"b":0,"e":"Nationalisme, démocratie, bien-être."},{"q":"Après la guerre de 1894-1895, la Chine perd :","r":["Hong Kong","Taïwan","Pékin","Macao"],"b":1,"e":"Au profit du Japon."},{"q":"Le mouvement du 4 mai 1919 proteste contre :","r":["l'opium","les Taiping","le traité de Versailles","la République"],"b":2,"e":"Droits donnés au Japon sur le Shandong."},{"q":"Le Parti communiste chinois est fondé en :","r":["1900","1912","1949","1921"],"b":3,"e":"Il prendra le pouvoir en 1949."},{"q":"La révolte des Taiping dure de :","r":["1850 à 1864","1900 à 1901","1911 à 1912","1839 à 1842"],"b":0,"e":"Des millions de morts."},{"q":"Le palais d'Été est saccagé en :","r":["1842","1860","1900","1911"],"b":1,"e":"Seconde guerre de l'opium."}],"apc":{"module":"Histoire de Première","famille":"Citoyenneté","agir":"Comparer les dominations étrangères et les nationalismes","situation":"Dans un débat à ton lycée de Kumba, un camarade s'étonne : « La Chine aujourd'hui puissante a-t-elle aussi été dominée comme l'Afrique ? »","tache":"Expliquer la domination subie par la Chine et la comparer à l'Afrique."},"gratuit":true});
VRT_L("1re-a-histoire-inde-indochine",{"c":"1re A","m":"histoire","rang":11,"titre":"L'impérialisme européen en Inde et en Indochine","duree":25,"accroche":"Le joyau de la couronne britannique et la perle de l'empire français.","intro":"En Asie, deux empires coloniaux se construisent au XIXᵉ siècle : l'Inde britannique, « joyau de la couronne », et l'Indochine française. Comme en Afrique, la conquête est suivie d'une exploitation économique et d'une domination politique qui provoquent révoltes et nationalismes.","objectifs":["retracer la conquête de l'Inde par les Britanniques","retracer la formation de l'Indochine française","décrire l'exploitation et les premières résistances"],"parties":[{"t":"L'Inde britannique","html":"<div class='def'><b>Définition</b>Le <strong>Raj britannique</strong> désigne la domination directe de la Couronne britannique sur l'Inde, de 1858 à 1947.</div><ul><li>La <strong>Compagnie anglaise des Indes orientales</strong> s'impose après la bataille de <strong>Plassey</strong> (1757).</li><li>La <strong>révolte des Cipayes</strong> (1857), soldats indiens de la Compagnie, est durement réprimée.</li><li>En <strong>1858</strong>, la Couronne prend le contrôle ; en <strong>1877</strong>, la reine Victoria devient impératrice des Indes.</li><li>Exploitation : coton brut exporté, textiles anglais importés qui ruinent l'artisanat indien ; thé, jute, opium ; chemins de fer vers les ports.</li><li>Le <strong>Congrès national indien</strong> est fondé en <strong>1885</strong>.</li></ul>","retenir":"Plassey (1757), Cipayes (1857), Raj (1858), Victoria impératrice (1877), Congrès (1885)."},{"t":"L'Indochine française","verrou":true},{"t":"Résistances et nationalismes","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Histoire de Première","famille":"Citoyenneté","agir":"Comparer les colonisations d'Asie et d'Afrique","situation":"Pour un exposé en classe à Bafoussam, ton groupe doit montrer que « la colonisation a suivi les mêmes logiques en Asie et en Afrique ».","tache":"Rédiger le plan détaillé de l'exposé."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-geo-ville-expansion",{"c":"1re A","m":"geo","rang":8,"titre":"La ville et l'expansion urbaine dans le monde","duree":25,"accroche":"Plus d'un humain sur deux vit en ville, et les villes africaines grandissent le plus vite.","intro":"Depuis 2007, la majorité de l'humanité vit en ville. Les villes s'étendent, se relient et forment parfois des métropoles géantes. Cette croissance est particulièrement rapide en Afrique et en Asie, où elle prend souvent la forme d'un étalement mal maîtrisé.","objectifs":["définir la ville et l'urbanisation","décrire les formes de l'expansion urbaine","comparer l'urbanisation des pays développés et des pays en développement"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définitions</b>Une <strong>ville</strong> est une agglomération de population importante, dont les habitants exercent surtout des activités non agricoles. Le <strong>taux d'urbanisation</strong> est la part de la population qui vit en ville. Une <strong>métropole</strong> est une grande ville qui concentre des fonctions de commandement (politiques, économiques, culturelles). Une <strong>mégapole</strong> dépasse 10 millions d'habitants.</div><ul><li>Le taux d'urbanisation mondial dépasse 55 % ; il dépasse 75 % dans les pays développés.</li><li>Grandes villes : Tokyo, Delhi, Shanghai, Le Caire, Lagos, Kinshasa.</li></ul>","retenir":"Ville, taux d'urbanisation (plus de 55 % dans le monde), métropole, mégapole."},{"t":"Les formes de l'expansion urbaine","verrou":true},{"t":"Deux types d'urbanisation","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Géographie de Première A","famille":"Environnement, santé et bien-être","agir":"Maîtriser l'expansion urbaine","situation":"Un rapport de la mairie de Douala indique que la ville s'étend de plusieurs kilomètres vers Bonabéri, Yassa et Logbessou, sur des terres marécageuses ou agricoles, sans routes ni réseaux.","tache":"Expliquer causes et conséquences et proposer trois mesures."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-francais-texte-injonctif",{"c":"1re A","m":"francais","rang":8,"titre":"Le texte injonctif : caractéristiques","duree":20,"accroche":"Mélangez, versez, ne touchez pas : le texte qui fait agir.","intro":"Une recette, un mode d'emploi, un règlement intérieur, une consigne d'examen, une affiche de prévention : tous ces textes cherchent à faire agir le lecteur. C'est le texte injonctif, ou prescriptif. Ses marques sont faciles à reconnaître et il obéit à une mise en page précise.","objectifs":["identifier le but et les formes du texte injonctif","repérer les marques grammaticales de l'injonction","rédiger un texte injonctif clair"],"parties":[{"t":"Définition et formes","html":"<div class='def'><b>Définition</b>Le <strong>texte injonctif</strong> (ou prescriptif) vise à <strong>faire agir</strong> le lecteur : il donne des ordres, des conseils, des consignes ou des interdictions.</div><ul><li><strong>Recettes</strong> et <strong>modes d'emploi</strong> (notices de médicaments, d'appareils).</li><li><strong>Règlements</strong> (règlement intérieur d'un lycée, code de la route).</li><li><strong>Consignes</strong> (sujets d'examen, consignes de sécurité).</li><li><strong>Affiches</strong> et messages de prévention (paludisme, sécurité routière).</li></ul>","retenir":"Faire agir : recettes, modes d'emploi, règlements, consignes, affiches."},{"t":"Les marques de l'injonction","verrou":true},{"t":"Rédiger un texte injonctif","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Français de Première A","famille":"Environnement, santé et bien-être","agir":"Rédiger un texte injonctif clair et cohérent","situation":"Le club santé de ton lycée à Ebolowa prépare une affiche contre le paludisme à placer dans les classes.","tache":"Rédiger le texte de l'affiche avec titre, consignes et mise en garde."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-anglais-community-celebrations",{"c":"1re A","m":"anglais","rang":3,"titre":"Vocabulary: interacting with others at community celebrations","duree":20,"accroche":"Could you…? Would you like…? Thank you for having us! Polite English for every celebration.","intro":"National Day, Youth Day, the Ngondo, the Nguon, a wedding or a funeral: community celebrations bring together classmates, neighbours, elders and school authorities. Each situation needs the right words to greet, invite, ask permission, thank and congratulate. This vocabulary is useful for the speaking, dialogue and letter-writing tasks of the exam.","objectifs":["use polite expressions to greet, invite, ask and thank","adapt your register to classmates, neighbours, adults and school authorities","use the vocabulary of community celebrations"],"parties":[{"t":"Celebrations and their vocabulary","html":"<div class='def'><b>Definition</b>A <strong>community celebration</strong> is an event in which members of a community gather to mark an occasion: a <strong>national holiday</strong> (National Day on 20th May, Youth Day on 11th February), a <strong>cultural festival</strong> (the Ngondo of the Sawa, the Nguon of the Bamoun, the Lela of Bali Nyonga), a <strong>wedding</strong>, a <strong>graduation</strong> or a <strong>funeral</strong>.</div><ul><li>Words: <strong>a parade</strong>, <strong>a march-past</strong>, <strong>a rehearsal</strong>, <strong>a guest</strong>, <strong>a host</strong>, <strong>a dignitary</strong>, <strong>a feast</strong>, <strong>traditional dances</strong>, <strong>attire</strong> (clothing for an occasion).</li><li>Verbs: <strong>to celebrate</strong>, <strong>to attend</strong>, <strong>to host</strong>, <strong>to rehearse</strong>, <strong>to march</strong>, <strong>to congratulate</strong>.</li></ul>","retenir":"parade, march-past, rehearsal, guest, host, feast, attire; to attend, to host, to congratulate."},{"t":"Polite expressions and register","verrou":true},{"t":"In context","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Anglais de 1re A","famille":"Vie sociale et culturelle","agir":"Interact politely with others during community celebrations","situation":"Your class in Dschang is organising a cultural evening for Youth Day (11th February). You must invite the principal, the parents and the neighbours.","tache":"Write a formal letter of invitation asking permission to use the school hall."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-philo-connaissance-autrui",{"c":"1re A","m":"philo","rang":13,"titre":"Les modes de connaissance d'autrui","duree":25,"accroche":"Puis-je savoir ce que pense vraiment mon voisin de table ?","intro":"Autrui, c'est l'autre moi, semblable à moi et pourtant différent. Je vois son corps, ses gestes, j'entends ses paroles ; mais je n'ai pas accès directement à sa conscience. Comment puis-je alors le connaître ? Les philosophes proposent plusieurs voies : le raisonnement, l'analogie, la sympathie, le regard, le visage.","objectifs":["définir autrui","présenter les principaux modes de connaissance d'autrui","évaluer les limites de cette connaissance"],"parties":[{"t":"Qui est autrui ?","html":"<div class='def'><b>Définition</b><strong>Autrui</strong> désigne l'autre homme en tant qu'il est, comme moi, un sujet doué de conscience : il est à la fois <strong>mon semblable</strong> (un autre « moi ») et <strong>différent</strong> de moi (un « moi » qui n'est pas moi).</div><ul><li>Autrui n'est pas une chose : il pense, il me juge, il a une liberté.</li><li>Le <strong>problème</strong> : je connais directement mes propres états de conscience, mais je n'ai pas accès aux siens.</li><li>Le <strong>solipsisme</strong> est la position extrême selon laquelle seul mon moi existerait avec certitude.</li></ul>","retenir":"Autrui : un autre moi, semblable et différent ; problème de l'accès à sa conscience ; solipsisme."},{"t":"Connaître par le raisonnement ou par l'analogie","verrou":true},{"t":"Connaître par la sympathie, le regard et le visage","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Philosophie de Première A","famille":"Vie sociale et culturelle","agir":"Être attentif à autrui et à ce qu'il ressent","situation":"Au lycée de Nkongsamba, Brenda, toujours souriante, est tombée malade de chagrin : ses camarades n'avaient rien remarqué. L'une d'elles dit : « On ne peut jamais savoir ce que l'autre ressent. »","tache":"Rédiger une dissertation courte : peut-on connaître autrui ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-histoire-premiere-guerre",{"c":"1re A","m":"histoire","rang":12,"titre":"La Première Guerre mondiale (1914-1918)","duree":25,"accroche":"Une guerre européenne devenue mondiale, jusqu'au Cameroun.","intro":"De 1914 à 1918, la Première Guerre mondiale oppose deux alliances et fait près de 10 millions de morts militaires. Guerre de mouvement puis guerre des tranchées, elle mobilise les économies, les sociétés et les colonies. Au Cameroun allemand, elle se termine par la défaite allemande de 1916.","objectifs":["expliquer les causes de la guerre","décrire les grandes phases du conflit","mesurer son caractère total et mondial"],"parties":[{"t":"Les causes","html":"<div class='def'><b>Définition</b>Une <strong>guerre mondiale</strong> est un conflit qui implique des États de plusieurs continents et mobilise toutes leurs ressources ; on parle de <strong>guerre totale</strong> quand toute la société est mobilisée.</div><ul><li><strong>Causes profondes</strong> : rivalités <strong>coloniales</strong> et <strong>économiques</strong> (Royaume-Uni, Allemagne) ; <strong>nationalismes</strong> (France et l'Alsace-Lorraine, Balkans) ; course aux armements ; <strong>systèmes d'alliances</strong> : Triple-Entente (France, Royaume-Uni, Russie) contre Triple-Alliance (Allemagne, Autriche-Hongrie, Italie).</li><li><strong>Cause immédiate</strong> : l'assassinat de l'archiduc <strong>François-Ferdinand</strong> à <strong>Sarajevo</strong> le <strong>28 juin 1914</strong> ; le jeu des alliances déclenche la guerre en août.</li></ul>","retenir":"Rivalités coloniales et économiques, nationalismes, alliances ; Sarajevo (28 juin 1914)."},{"t":"Les phases de la guerre","verrou":true},{"t":"Une guerre totale et mondiale","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Histoire de Première","famille":"Citoyenneté","agir":"Montrer les effets de la Première Guerre mondiale sur l'Afrique et le Cameroun","situation":"Ton grand-père, à Yaoundé, affirme : « La guerre de 14-18 était une affaire de Blancs, elle n'a rien changé chez nous. »","tache":"Lui répondre en douze lignes."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-geo-problemes-urbains",{"c":"1re A","m":"geo","rang":9,"titre":"Les problèmes urbains","duree":25,"accroche":"Embouteillages, inondations, ordures : la ville souffre de sa croissance.","intro":"Les villes concentrent les emplois, les écoles, les hôpitaux. Mais une croissance rapide et mal maîtrisée crée des problèmes : logement, transport, chômage, insalubrité, insécurité. Ils sont particulièrement graves dans les villes des pays en développement, comme Douala ou Yaoundé.","objectifs":["identifier les principaux problèmes urbains","en expliquer les causes","proposer des solutions"],"parties":[{"t":"Les problèmes","html":"<div class='def'><b>Définition</b>Les <strong>problèmes urbains</strong> sont les difficultés de la vie en ville nées d'un déséquilibre entre la croissance de la population et les capacités d'accueil (logements, équipements, emplois, services).</div><ul><li><strong>Logement</strong> : quartiers spontanés, bidonvilles, constructions en zones à risque (marécages, pentes).</li><li><strong>Transport</strong> : embouteillages, insuffisance des transports collectifs, motos-taxis accidentogènes.</li><li><strong>Services de base</strong> : coupures d'eau et d'électricité, assainissement insuffisant.</li><li><strong>Environnement</strong> : ordures, pollution de l'air, inondations.</li><li><strong>Social</strong> : chômage, secteur informel, délinquance, insécurité.</li></ul>","retenir":"Logement, transport, eau et électricité, ordures, inondations, chômage, insécurité."},{"t":"Les causes","verrou":true},{"t":"Les solutions","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Géographie de Première A","famille":"Environnement, santé et bien-être","agir":"Proposer des solutions aux problèmes de son quartier","situation":"Dans ton quartier de Yaoundé, chaque saison des pluies, la rue principale est inondée et les ordures s'accumulent près du marché ; des enfants tombent malades.","tache":"Écrire au maire pour décrire les problèmes et proposer des solutions."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-francais-paragraphe-commentaire",{"c":"1re A","m":"francais","rang":10,"titre":"Commentaire composé : rédiger un paragraphe","duree":20,"accroche":"Citer, nommer, interpréter : le geste de base du commentaire composé.","intro":"Le commentaire composé explique un texte en montrant comment la forme produit le sens. Chaque paragraphe du développement défend une idée de lecture, appuyée sur des citations précises dont on identifie les procédés et dont on interprète l'effet. Ni paraphrase, ni liste de figures : fond et forme vont ensemble.","objectifs":["construire un paragraphe de commentaire autour d'une idée","associer citation, procédé et interprétation","éviter la paraphrase et le relevé mécanique"],"parties":[{"t":"La structure du paragraphe","html":"<div class='def'><b>Définition</b>Un <strong>paragraphe de commentaire composé</strong> développe une <strong>idée directrice</strong> (un aspect du sens du texte) en l'appuyant sur des <strong>citations</strong> dont on identifie les <strong>procédés</strong> (forme) et dont on <strong>interprète</strong> l'effet (fond).</div><ol><li>Phrase d'annonce de l'idée.</li><li>Pour chaque preuve : citation entre guillemets (avec le vers ou la ligne), procédé nommé, interprétation.</li><li>Phrase de bilan.</li></ol>","retenir":"Idée directrice ; citation + procédé + interprétation ; bilan."},{"t":"Allier le fond et la forme","verrou":true},{"t":"Un modèle","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Français de Première A","famille":"Vie sociale et culturelle","agir":"Rédiger un paragraphe de commentaire alliant fond et forme","situation":"Ton professeur à Édéa donne ces vers à commenter : « Ô fleuve Sanaga, ô sang de nos collines, / Tu portes nos pirogues et nos chants vers la mer, / Mais les barrages ont dompté ta colère divine / Et tes poissons s'en vont comme un peuple en exil. » (texte inventé pour l'exercice).","tache":"Rédiger un paragraphe de commentaire autour d'une idée directrice."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-anglais-buying-selling",{"c":"1re A","m":"anglais","rang":16,"titre":"Vocabulary: buying and selling at the market","duree":20,"accroche":"How much is it? Can you reduce the price? Here is your change!","intro":"Markets and small stores are part of daily life: we buy foodstuff, clothes, phone credit; we compare prices, bargain and pay. Knowing the vocabulary of buying and selling helps in real life and in the exam, where dialogues at the market and shopping situations are frequent.","objectifs":["use the vocabulary of buying and selling","ask for prices and bargain politely","understand measures, money and payment expressions"],"parties":[{"t":"Words of the market","html":"<div class='def'><b>Definition</b><strong>Buying and selling</strong> is the exchange of goods for money. The <strong>seller</strong> (vendor, trader, shopkeeper) offers <strong>goods</strong>; the <strong>buyer</strong> (customer, client) pays the <strong>price</strong>.</div><ul><li>Places: <strong>a market</strong>, <strong>a stall</strong>, <strong>a store / shop</strong>, <strong>a supermarket</strong>, <strong>a kiosk</strong>.</li><li>Quantities: <strong>a heap</strong> (un tas), <strong>a bunch</strong> (of plantains, un régime), <strong>a bag</strong>, <strong>a kilo</strong>, <strong>a litre</strong>, <strong>a dozen</strong>, <strong>a tin</strong>, <strong>a loaf</strong> (of bread).</li><li>Money: <strong>cash</strong>, <strong>change</strong> (la monnaie rendue), <strong>a receipt</strong>, <strong>mobile money</strong>, <strong>a discount</strong>, <strong>cheap</strong> / <strong>expensive</strong>, <strong>a bargain</strong> (une bonne affaire).</li><li>Extra: <strong>a dash</strong> (Cameroonian English: a small extra gift from the seller).</li></ul>","retenir":"seller, buyer, customer, stall, heap, bunch, change, receipt, discount, cheap, expensive, bargain, dash."},{"t":"Useful expressions","verrou":true},{"t":"In context","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Anglais de 1re A","famille":"Vie économique","agir":"Buy and sell politely and safely at the market","situation":"Your English club in Buea is preparing a short play for the school's cultural week: a scene at the market between a customer, a seller and a pickpocket who is caught.","tache":"Write a dialogue at the market using the vocabulary of buying and selling."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-philo-morales-interet",{"c":"1re A","m":"philo","rang":16,"titre":"Les morales de l'intérêt : épicurisme, eudémonisme, utilitarisme","duree":25,"accroche":"Être heureux, est-ce la même chose qu'être bon ?","intro":"Pourquoi agir bien ? Une première réponse dit : parce que c'est notre intérêt. Le bien serait ce qui nous rend heureux, ce qui nous procure du plaisir ou ce qui est utile au plus grand nombre. Ces morales de l'intérêt, de l'Antiquité à l'époque moderne, s'opposent à la morale du devoir.","objectifs":["définir les morales de l'intérêt","présenter l'épicurisme, l'eudémonisme et l'utilitarisme","en dégager la valeur et les limites"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Les <strong>morales de l'intérêt</strong> (ou morales <strong>conséquentialistes</strong>) fondent le bien sur ce qui est avantageux pour l'homme : le <strong>plaisir</strong> (hédonisme), le <strong>bonheur</strong> (eudémonisme) ou l'<strong>utilité</strong> (utilitarisme). Une action y est bonne par ses <strong>conséquences</strong> heureuses.</div><ul><li>Elles partent d'un fait : tout homme recherche le bonheur et fuit la souffrance.</li><li>Elles s'opposent aux <strong>morales du devoir</strong>, pour lesquelles le bien vaut par lui-même, indépendamment de l'intérêt.</li></ul>","retenir":"Morales de l'intérêt : plaisir, bonheur, utilité ; jugent l'action par ses conséquences."},{"t":"Épicurisme et eudémonisme","verrou":true},{"t":"L'utilitarisme et les critiques","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Philosophie de Première A","famille":"Citoyenneté","agir":"Juger une décision collective en conciliant utilité et justice","situation":"La commune de Mbouda veut détruire un vieux quartier pour construire un grand marché moderne. « Des milliers d'habitants en profiteront », dit le maire ; « Et nous, les deux cents familles expulsées ? », répondent les riverains.","tache":"Rédiger une dissertation courte sur l'utilité au plus grand nombre."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-histoire-crise-1929",{"c":"1re A","m":"histoire","rang":15,"titre":"La crise économique de 1929","duree":25,"accroche":"Un jeudi d'octobre à New York, et le cacao du Cameroun ne vaut plus rien.","intro":"Le 24 octobre 1929, la Bourse de New York s'effondre. La crise boursière devient une crise bancaire, industrielle, agricole et sociale, puis s'étend au monde entier, colonies comprises. Elle provoque un chômage massif et favorise la montée des régimes totalitaires.","objectifs":["expliquer les causes de la crise de 1929","décrire son extension et ses manifestations","mesurer ses conséquences, en particulier en Afrique et au Cameroun"],"parties":[{"t":"Les causes et le krach","html":"<div class='def'><b>Définition</b>Une <strong>crise économique</strong> est une rupture brutale de la croissance, marquée par la baisse de la production et des prix, les faillites et le chômage. Le <strong>krach</strong> est l'effondrement brutal des cours de la Bourse.</div><ul><li>Dans les années 1920, les États-Unis connaissent une forte croissance (« prospérité ») mais aussi une <strong>surproduction</strong> agricole et industrielle et une <strong>spéculation</strong> boursière, souvent à crédit.</li><li>Le <strong>jeudi 24 octobre 1929</strong> (« jeudi noir »), les cours s'effondrent à <strong>Wall Street</strong> ; la panique continue les jours suivants.</li></ul>","retenir":"Surproduction, spéculation à crédit ; krach de Wall Street, jeudi noir (24 octobre 1929)."},{"t":"Une crise générale et mondiale","verrou":true},{"t":"Les conséquences","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Histoire de Première","famille":"Vie économique","agir":"Comprendre la dépendance des économies africaines aux crises mondiales","situation":"En 2020, pendant la pandémie, un commerçant de Douala se plaint : « Quand l'économie mondiale tousse, c'est nous qui tombons malades. » Ton camarade affirme que cela n'est jamais arrivé avant.","tache":"Expliquer, à partir de 1929, comment une crise extérieure touche l'Afrique."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-geo-elevage",{"c":"1re A","m":"geo","rang":12,"titre":"L'élevage dans le monde","duree":25,"accroche":"Du berger peul au feedlot américain : deux mondes de l'élevage.","intro":"L'élevage fournit viande, lait, œufs, cuir et force de travail. Il prend des formes très différentes : élevage extensif et mobile dans les savanes et les steppes, élevage intensif et industriel dans les pays riches. Il pose partout des problèmes d'environnement et, en Afrique, de cohabitation avec l'agriculture.","objectifs":["distinguer les types d'élevage","localiser les grandes régions d'élevage","analyser les problèmes de l'élevage"],"parties":[{"t":"Les types d'élevage","html":"<div class='def'><b>Définitions</b>L'<strong>élevage</strong> est l'ensemble des activités qui assurent la reproduction et l'entretien des animaux domestiques. L'<strong>élevage extensif</strong> utilise de vastes espaces avec peu de moyens et de faibles rendements ; l'<strong>élevage intensif</strong> obtient de forts rendements sur de petites surfaces grâce aux capitaux, aux aliments industriels et aux soins vétérinaires.</div><ul><li><strong>Nomadisme</strong> : déplacement permanent avec les troupeaux (Sahel, Touaregs).</li><li><strong>Transhumance</strong> : déplacement saisonnier entre pâturages de saison sèche et de saison des pluies (éleveurs peuls ou mbororo).</li><li><strong>Ranching</strong> : grands domaines clôturés (Argentine, Australie, États-Unis).</li><li><strong>Élevage hors-sol</strong> : volailles et porcs en bâtiments (Pays-Bas, Danemark, Bretagne) ; <strong>feedlots</strong> aux États-Unis.</li></ul>","retenir":"Extensif / intensif ; nomadisme, transhumance, ranching, hors-sol, feedlots."},{"t":"Les grandes régions d'élevage","verrou":true},{"t":"Les problèmes","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Géographie de Première A","famille":"Environnement, santé et bien-être","agir":"Favoriser la cohabitation entre éleveurs et agriculteurs","situation":"Près de Meiganga, chaque saison sèche, des troupeaux de transhumants traversent des champs de maïs ; les agriculteurs se plaignent, et des affrontements ont eu lieu.","tache":"Expliquer les causes du conflit et proposer trois mesures."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-francais-conditionnel",{"c":"1re A","m":"francais","rang":16,"titre":"La valeur des modes et des temps : le conditionnel","duree":20,"accroche":"« Il viendrait », « je voudrais », « il serait arrivé » : un même mode, sept valeurs.","intro":"Le conditionnel est à la fois un temps de l'indicatif (le futur vu du passé) et un mode qui exprime l'éventuel, l'irréel, la politesse ou l'incertitude. Savoir en identifier la valeur est une question classique de langue, et bien l'employer évite des fautes fréquentes, notamment après « si ».","objectifs":["conjuguer le conditionnel présent et passé","identifier les valeurs temporelles et modales du conditionnel","employer correctement le conditionnel dans les phrases hypothétiques"],"parties":[{"t":"Formes","html":"<div class='def'><b>Définition</b>Le <strong>conditionnel</strong> est une forme verbale qui, selon le contexte, exprime un <strong>temps</strong> (le futur dans le passé) ou une <strong>modalité</strong> (l'éventuel, l'irréel, la politesse, l'incertitude). Le <strong>conditionnel présent</strong> se forme sur le radical du futur + terminaisons de l'imparfait (-ais, -ais, -ait, -ions, -iez, -aient) ; le <strong>conditionnel passé</strong> avec l'auxiliaire au conditionnel présent + participe passé.</div><ul><li>chanter → je chanterais ; venir → je viendrais ; être → je serais ; avoir → j'aurais.</li><li>Passé : j'aurais chanté, je serais venu(e).</li></ul><div class='attention'><b>Ne pas confondre</b>« je chanterai » (futur) et « je chanterais » (conditionnel) : remplacer par « nous » permet de choisir (nous chanterons / nous chanterions).</div>","retenir":"Radical du futur + -ais, -ait… ; passé : aurais / serais + participe ; je chanterai ≠ je chanterais."},{"t":"Les valeurs","verrou":true},{"t":"Le système hypothétique","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Français de Première A","famille":"Citoyenneté","agir":"Employer le conditionnel pour imaginer et proposer","situation":"Pour le concours d'éloquence de ton lycée à Foumban, le sujet est : « Si j'étais maire de ma ville… »","tache":"Rédiger un texte mobilisant quatre valeurs du conditionnel."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-anglais-quantifiers",{"c":"1re A","m":"anglais","rang":18,"titre":"Grammar: determiners and quantifiers","duree":20,"accroche":"A few or a little? Much or many? Each or every?","intro":"Determiners and quantifiers tell us how much or how many of something there is. They are used every day (shopping, planning, describing) and are frequently tested in Section A of the exam. The key is to know whether the noun is countable or uncountable.","objectifs":["distinguish countable and uncountable nouns","use some, any, no, none, much, many, few, little correctly","use all, both, each, every and most"],"parties":[{"t":"Countable and uncountable nouns","html":"<div class='def'><b>Definition</b><strong>Determiners</strong> are words placed before a noun to specify it (a, the, this, my…). <strong>Quantifiers</strong> are determiners that express <strong>quantity</strong>: some, any, much, many, few, little, all, both, each, every, most, no, none. Their use depends on whether the noun is <strong>countable</strong> (books, oranges) or <strong>uncountable</strong> (water, rice, information, advice).</div><ul><li><strong>many / few / a few</strong> + plural countable: many students, a few oranges.</li><li><strong>much / little / a little</strong> + uncountable: much money, a little sugar.</li><li><strong>How many</strong> students? <strong>How much</strong> rice?</li></ul><div class='attention'><b>Watch out</b><em>information, advice, furniture, luggage, news</em> are uncountable in English: « much information », not « many informations ».</div>","retenir":"many / few + countable ; much / little + uncountable ; information, advice, news: uncountable."},{"t":"Some, any, no, none ; few and a few","verrou":true},{"t":"All, both, each, every, most","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Anglais de 1re A","famille":"Citoyenneté","agir":"Express quantities precisely to organise a community activity","situation":"Your class in Bafoussam is organising a clean-up day at the market. You must write the notice that lists what is available and what is missing.","tache":"Write a notice listing what is available and what is missing."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-philo-morale-devoir",{"c":"1re A","m":"philo","rang":17,"titre":"La morale du devoir (Kant)","duree":25,"accroche":"Faut-il faire le bien parce que c'est utile, ou parce que c'est le bien ?","intro":"Contre les morales de l'intérêt, Emmanuel Kant affirme que la valeur morale d'une action ne dépend ni de ses conséquences ni du bonheur qu'elle procure, mais de l'intention : agir par devoir, par respect pour la loi morale que la raison se donne. C'est la morale du devoir, rigoureuse et universelle.","objectifs":["définir le devoir et la bonne volonté","énoncer l'impératif catégorique et ses formules","évaluer la morale du devoir"],"parties":[{"t":"Le devoir et la bonne volonté","html":"<div class='def'><b>Définitions</b>Le <strong>devoir</strong> est l'obligation morale d'agir par respect pour la loi que la raison prescrit. Pour <strong>Kant</strong> (<em>Fondements de la métaphysique des mœurs</em>, 1785), la seule chose bonne sans restriction est la <strong>bonne volonté</strong> : la volonté d'agir par devoir.</div><ul><li>Agir <strong>conformément au devoir</strong> (le commerçant honnête par intérêt) n'est pas agir <strong>par devoir</strong> (le témoin qui dit vrai malgré la menace).</li><li>Seule l'action faite <strong>par devoir</strong> a une <strong>valeur morale</strong>.</li></ul>","retenir":"Devoir ; bonne volonté ; conformément au devoir ≠ par devoir."},{"t":"L'impératif catégorique","verrou":true},{"t":"Valeur et limites","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Philosophie de Première A","famille":"Citoyenneté","agir":"Agir avec intégrité face à la corruption","situation":"À Kousséri, un fonctionnaire refuse un pot-de-vin qui lui permettrait de payer l'hôpital de sa mère. Un collègue lui dit : « Tout le monde le fait, et c'est pour une bonne cause. »","tache":"Rédiger une dissertation courte : faut-il toujours faire son devoir ?"},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-histoire-reglement-premiere-guerre",{"c":"1re A","m":"histoire","rang":14,"titre":"Le règlement de la Première Guerre mondiale","duree":25,"accroche":"Versailles, la SDN, et le Cameroun partagé.","intro":"Après l'armistice du 11 novembre 1918, les vainqueurs réunis à Paris redessinent la carte du monde. Les traités de paix punissent l'Allemagne et démembrent les empires vaincus ; la Société des Nations est créée pour garantir la paix. Les colonies allemandes, dont le Cameroun, sont confiées aux vainqueurs sous forme de mandats.","objectifs":["présenter la conférence de la paix et les principes de Wilson","décrire les principaux traités, dont celui de Versailles","expliquer le système des mandats et le partage du Cameroun"],"parties":[{"t":"La conférence de la paix","html":"<div class='def'><b>Définition</b>Le <strong>règlement de la guerre</strong> désigne l'ensemble des traités et décisions qui fixent les conditions de la paix après 1918 ; un <strong>mandat</strong> est un territoire confié par la SDN à une puissance chargée de l'administrer au nom de la communauté internationale.</div><ul><li>La <strong>conférence de la paix</strong> s'ouvre à Paris en janvier 1919, sans les vaincus ; elle est dominée par les « Quatre » : Wilson (États-Unis), Clemenceau (France), Lloyd George (Royaume-Uni), Orlando (Italie).</li><li>Les <strong>Quatorze Points</strong> du président <strong>Wilson</strong> (8 janvier 1918) : droit des peuples à disposer d'eux-mêmes, liberté des mers, création d'une société des nations.</li></ul>","retenir":"Conférence de Paris (1919), les Quatre, Quatorze Points de Wilson ; mandat."},{"t":"Les traités","verrou":true},{"t":"Les mandats et le Cameroun","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Histoire de Première","famille":"Citoyenneté","agir":"Expliquer les origines historiques du bilinguisme camerounais","situation":"Un élève de Buea demande : « Pourquoi le Cameroun a-t-il deux langues officielles héritées de deux colonisateurs différents ? »","tache":"Expliquer le règlement de la Première Guerre mondiale et ses conséquences."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-histoire-cameroun-interets-europeens",{"c":"1re A","m":"histoire","rang":21,"titre":"Le Cameroun au centre des intérêts européens (XVe-XIXe siècle)","duree":25,"accroche":"Des crevettes de l'estuaire au traité de 1884 : quatre siècles de convoitises.","intro":"Bien avant la colonisation, la côte camerounaise attire les Européens : navigateurs portugais, négriers, commerçants, missionnaires. Au XIXᵉ siècle, Britanniques, Allemands et Français se disputent l'influence sur l'estuaire du Wouri. En 1884, l'Allemagne l'emporte par le traité germano-douala.","objectifs":["retracer les premiers contacts entre Européens et Camerounais","présenter les intérêts commerciaux, religieux et politiques au XIXᵉ siècle","expliquer comment l'Allemagne s'empare du Cameroun en 1884"],"parties":[{"t":"Des premiers contacts à la traite","html":"<div class='def'><b>Définition</b>Les <strong>intérêts européens</strong> désignent les motivations économiques, religieuses, scientifiques et politiques qui poussent les puissances européennes à s'implanter sur la côte camerounaise.</div><ul><li>Vers <strong>1472</strong>, le navigateur portugais <strong>Fernando Póo</strong> atteint l'estuaire du Wouri ; les crevettes abondantes lui font nommer le fleuve <strong>Rio dos Camarões</strong> (rivière des crevettes), d'où le nom « Cameroun ».</li><li>Du XVIᵉ au XIXᵉ siècle, la côte participe à la <strong>traite atlantique</strong> : les chefs côtiers (Douala, Bimbia) servent d'intermédiaires.</li><li>Après l'abolition de la traite par le Royaume-Uni (1807), le <strong>commerce dit « légitime »</strong> se développe : huile de palme, ivoire, caoutchouc contre tissus, alcool, armes.</li></ul>","retenir":"Fernando Póo (vers 1472), Rio dos Camarões ; traite atlantique ; commerce « légitime » après 1807."},{"t":"Britanniques, Allemands, Français au XIXᵉ siècle","verrou":true},{"t":"Le traité germano-douala de 1884","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Histoire de Première","famille":"Citoyenneté","agir":"Comprendre comment le Cameroun est devenu une colonie","situation":"Au musée maritime de Douala, ton petit frère voit une copie du traité de 1884 et demande : « Pourquoi les rois douala ont-ils signé avec les Allemands ? »","tache":"Expliquer le contexte et le contenu du traité, puis porter un jugement."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-geo-peche",{"c":"1re A","m":"geo","rang":13,"titre":"La pêche dans le monde","duree":25,"accroche":"Des pirogues de Kribi aux chalutiers-usines : la mer nourrit le monde, jusqu'à quand ?","intro":"La pêche fournit une part essentielle des protéines animales consommées dans le monde. Elle oppose une pêche artisanale, nombreuse et locale, à une pêche industrielle puissante. Avec l'aquaculture, la production augmente, mais la surpêche menace les ressources.","objectifs":["distinguer les types de pêche et l'aquaculture","localiser les grandes zones et puissances de pêche","analyser les problèmes et les solutions"],"parties":[{"t":"Types de pêche","html":"<div class='def'><b>Définitions</b>La <strong>pêche</strong> est la capture d'animaux aquatiques (poissons, crustacés, mollusques) en mer ou en eau douce. L'<strong>aquaculture</strong> est l'élevage d'animaux ou de plantes aquatiques.</div><ul><li><strong>Pêche artisanale</strong> : pirogues, filets, petites quantités, consommation locale ; elle emploie la majorité des pêcheurs du monde.</li><li><strong>Pêche industrielle</strong> : chalutiers, navires-usines qui congèlent et transforment à bord, sonars ; grandes quantités, exportation.</li><li><strong>Pêche continentale</strong> : fleuves et lacs (Nil, Niger, lac Tchad, lac de Lagdo).</li></ul>","retenir":"Artisanale / industrielle / continentale ; aquaculture."},{"t":"Zones et puissances","verrou":true},{"t":"Problèmes et solutions","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Géographie de Première A","famille":"Environnement, santé et bien-être","agir":"Défendre une pêche durable","situation":"À Kribi, les pêcheurs artisanaux se plaignent : « Les chalutiers viennent la nuit près des côtes, nos filets reviennent vides et le poisson devient cher. »","tache":"Expliquer causes et conséquences et proposer trois solutions."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-francais-formation-mots",{"c":"1re A","m":"francais","rang":17,"titre":"Les procédés de formation des mots","duree":20,"accroche":"Ndolè, taxi-moto, BEPC, courriel : comment naissent les mots ?","intro":"La langue française invente sans cesse des mots pour nommer les réalités nouvelles. Elle les fabrique à partir de mots existants (dérivation, composition, abréviation) ou les emprunte à d'autres langues. Au Cameroun, ce dynamisme est particulièrement visible, au contact de l'anglais et des langues nationales.","objectifs":["identifier les procédés de formation des mots","distinguer néologie de forme et néologie de sens","reconnaître les emprunts et leurs usages"],"parties":[{"t":"Néologie : définitions","html":"<div class='def'><b>Définitions</b>La <strong>néologie</strong> est la création de mots nouveaux (les <strong>néologismes</strong>). La <strong>néologie de forme</strong> crée un mot nouveau ; la <strong>néologie de sens</strong> donne un sens nouveau à un mot existant (« souris » d'ordinateur). L'<strong>emprunt</strong> consiste à intégrer un mot d'une autre langue.</div><ul><li>Un mot est formé d'un <strong>radical</strong> (base) et éventuellement d'<strong>affixes</strong> : <strong>préfixe</strong> (avant) et <strong>suffixe</strong> (après).</li></ul>","retenir":"Néologie de forme / de sens ; emprunt ; radical, préfixe, suffixe."},{"t":"Les procédés de formation","verrou":true},{"t":"L'emprunt","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Français de Première A","famille":"Vie sociale et culturelle","agir":"Analyser la formation des mots et maîtriser les registres","situation":"Le club de journalisme de ton lycée prépare un petit lexique des mots inventés ou empruntés que les jeunes de Douala utilisent, pour une exposition sur « La vie des mots ».","tache":"Présenter six mots en usage au Cameroun et leur procédé de formation."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-anglais-polite-requests",{"c":"1re A","m":"anglais","rang":15,"titre":"Grammar: polite requests and suggestions","duree":20,"accroche":"Could you…? Would you mind…? Let me… Why don't we…? Politeness is grammar too.","intro":"In English, the way we ask for something or make a suggestion is as important as the request itself. A command like « Give me the book! » sounds rude; « Could you give me the book, please? » is polite. Requests and suggestions are frequent in dialogues and in Section A of the exam.","objectifs":["make polite requests with can, could, would, would you mind","make suggestions with let's, shall we, why don't we, how about","offer help with let me and shall I"],"parties":[{"t":"Polite requests","html":"<div class='def'><b>Definition</b>A <strong>polite request</strong> is a way of asking someone to do something, or asking for permission, without giving an order. A <strong>suggestion</strong> is a proposal of an idea or action.</div><ul><li><strong>Can you</strong> + bare infinitive (informal): <em>Can you pass the salt?</em></li><li><strong>Could you</strong> + bare infinitive (more polite): <em>Could you open the window, please?</em></li><li><strong>Would you</strong> + bare infinitive: <em>Would you help me, please?</em></li><li><strong>Would you mind</strong> + verb-<strong>ing</strong>: <em>Would you mind closing the door?</em> Answer « No, not at all » means you agree!</li><li>Permission: <strong>May I / Could I</strong> + bare infinitive: <em>May I come in?</em> ; <strong>Would you mind if I</strong> + past: <em>Would you mind if I sat here?</em></li></ul>","retenir":"Can / could / would you + bare infinitive ; would you mind + -ing ; may I / could I ; would you mind if I + past."},{"t":"Offers and suggestions","verrou":true},{"t":"Answering","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"apc":{"module":"Anglais de 1re A","famille":"Vie sociale et culturelle","agir":"Make polite requests and suggestions in school life","situation":"Your class in Kumba wants to organise a revision weekend at school before the exams. You need the principal's permission and the help of some teachers and parents.","tache":"Write a formal letter requesting permission and making suggestions."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-info-r05",{"duree":20,"titre":"Principes de la sécurité informatique","accroche":"Protéger l'information.","intro":"La sécurité informatique vise à protéger les données et les équipements contre les pertes, les vols et les attaques.","objectifs":["définir la sécurité informatique","citer ses objectifs","identifier les principales menaces"],"parties":[{"t":"Définition et objectifs","html":"<div class='def'><b>Définition</b>La <strong>sécurité informatique</strong> est l'ensemble des mesures qui protègent les systèmes informatiques et les données contre les accès non autorisés, les modifications, les pertes et les destructions.</div><p>Objectifs : <strong>confidentialité</strong> (accès réservé), <strong>intégrité</strong> (données non altérées), <strong>disponibilité</strong> (accès quand on en a besoin), <strong>authentification</strong> (vérifier l'identité).</p>"},{"t":"Les menaces","verrou":true},{"t":"Les bons réflexes","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"info","rang":5,"apc":{"module":"Sécurité et optimisation de l'environnement de travail","famille":"Environnement numérique","agir":"Protéger et optimiser son poste de travail","situation":"Au secrétariat du lycée, l'ordinateur des inscriptions reste allumé et ouvert pendant les pauses, et les fichiers ne sont copiés nulle part.","tache":"Identifie deux risques et propose trois mesures de sécurité."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-info-r06",{"duree":20,"titre":"Protection des données","accroche":"Garder ses données à l'abri.","intro":"Les données personnelles et professionnelles ont de la valeur. Il faut les protéger contre la perte, le vol et la divulgation.","objectifs":["créer un mot de passe robuste","sauvegarder ses données","protéger sa vie privée en ligne"],"parties":[{"t":"Mots de passe","html":"<div class='def'><b>Définition</b><strong>Protéger ses données</strong>, c'est empêcher qu'elles soient perdues, volées, modifiées ou divulguées sans autorisation.</div><p>Un mot de passe robuste : au moins 12 caractères, majuscules, minuscules, chiffres et symboles, différent pour chaque compte. Une phrase de passe facile à retenir convient : « J'aime2Plantains!AuDîner ». La double authentification renforce la protection.</p>"},{"t":"Sauvegarder","verrou":true},{"t":"Vie privée","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"info","rang":6,"apc":{"module":"Sécurité et optimisation de l'environnement de travail","famille":"Environnement numérique","agir":"Protéger et optimiser son poste de travail","situation":"Josiane utilise le même mot de passe « josiane123 » pour sa messagerie, son réseau social et son compte bancaire ; son compte de réseau social vient d'être piraté.","tache":"Explique pourquoi tous ses comptes sont menacés et propose trois mesures."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-info-r07",{"duree":20,"titre":"Protection de l'espace de travail","accroche":"Un poste propre, sûr et protégé.","intro":"Protéger son espace de travail, c'est sécuriser à la fois l'ordinateur, sa session et l'environnement physique.","objectifs":["sécuriser une session","installer et utiliser un antivirus","protéger le matériel"],"parties":[{"t":"Sécuriser la session","html":"<div class='def'><b>Définition</b>L'<strong>espace de travail</strong> est l'ensemble formé par l'ordinateur, la session de l'utilisateur, ses fichiers et l'environnement physique dans lequel il travaille.</div><p>Compte protégé par un mot de passe, verrouillage automatique après quelques minutes d'inactivité, compte standard pour l'usage quotidien.</p>"},{"t":"Antivirus et pare-feu","verrou":true},{"t":"Le matériel","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"info","rang":7,"apc":{"module":"Sécurité et optimisation de l'environnement de travail","famille":"Environnement numérique","agir":"Protéger et optimiser son poste de travail","situation":"Dans un cybercafé de Bertoua, les clients branchent leurs clés USB sans contrôle ; trois ordinateurs ont été infectés en un mois et un client a renversé du jus sur un clavier.","tache":"Propose quatre mesures pour protéger l'espace de travail du cybercafé."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-info-r08",{"duree":20,"titre":"Utilisation de quelques périphériques","accroche":"Brancher, configurer, utiliser.","intro":"Imprimante, scanner, vidéoprojecteur, webcam : les périphériques étendent les possibilités de l'ordinateur. Il faut savoir les installer et les utiliser.","objectifs":["classer les périphériques","installer un périphérique","utiliser imprimante, scanner et vidéoprojecteur"],"parties":[{"t":"Les périphériques","html":"<div class='def'><b>Définition</b>Un <strong>périphérique</strong> est un appareil connecté à l'ordinateur pour lui fournir des données (entrée), en recevoir (sortie) ou les deux (entrée-sortie).</div><ul><li>entrée : clavier, souris, scanner, webcam, micro ;</li><li>sortie : écran, imprimante, vidéoprojecteur, haut-parleurs ;</li><li>entrée-sortie : écran tactile, imprimante multifonction, clé USB.</li></ul>"},{"t":"Installer","verrou":true},{"t":"Utiliser","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"info","rang":8,"apc":{"module":"Sécurité et optimisation de l'environnement de travail","famille":"Environnement numérique","agir":"Protéger et optimiser son poste de travail","situation":"Pour un exposé, ton groupe branche un vidéoprojecteur au portable de l'enseignant : l'image apparaît sur le portable mais pas sur l'écran de projection.","tache":"Décris la démarche de vérification et de réglage en quatre étapes."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-info-r09",{"duree":20,"titre":"Optimisation des organes de stockage","accroche":"Un disque rangé, un ordinateur plus rapide.","intro":"Les disques et clés se remplissent de fichiers inutiles et se fragmentent. Quelques opérations simples améliorent leurs performances.","objectifs":["identifier les organes de stockage","libérer de l'espace","défragmenter et vérifier un disque"],"parties":[{"t":"Les organes de stockage","html":"<div class='def'><b>Définition</b>Un <strong>organe de stockage</strong> (mémoire de masse) conserve durablement les données : disque dur (HDD), disque SSD, clé USB, carte mémoire, disque externe, stockage en ligne.</div><p>Le SSD, sans pièce mécanique, est beaucoup plus rapide que le disque dur. Le <strong>partitionnement</strong> divise un disque physique en plusieurs disques logiques (partitions), par exemple pour séparer le système et les données ; le <strong>formatage</strong> prépare un disque ou une partition à recevoir des données (il efface son contenu).</p>"},{"t":"Libérer de l'espace","verrou":true},{"t":"Défragmenter et vérifier","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"info","rang":9,"apc":{"module":"Sécurité et optimisation de l'environnement de travail","famille":"Environnement numérique","agir":"Protéger et optimiser son poste de travail","situation":"L'ordinateur à disque dur du foyer culturel affiche « Espace disque insuffisant » : 3 Go libres sur 500 Go, dont 180 Go de vidéos de fêtes et 40 Go de téléchargements anciens.","tache":"Propose quatre actions pour libérer de l'espace et améliorer ses performances."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-info-r10",{"duree":20,"titre":"Saisie et calculs simples dans un tableur","accroche":"Premiers pas dans un classeur.","intro":"Le tableur organise les données dans des cellules et calcule automatiquement. Il est utilisé dans tous les métiers.","objectifs":["se repérer dans un classeur","saisir des données","écrire des formules simples"],"parties":[{"t":"Le classeur","html":"<div class='def'><b>Définition</b>Un <strong>tableur</strong> est un logiciel de calcul qui présente les données dans un tableau de cellules. Un <strong>classeur</strong> contient des <strong>feuilles</strong> ; chaque cellule est repérée par sa colonne (lettre) et sa ligne (nombre) : B3.</div>"},{"t":"Saisir","verrou":true},{"t":"Formules simples","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"info","rang":10,"apc":{"module":"Tableur et présentation","famille":"Outils de productivité","agir":"Produire des documents de calcul et de présentation","situation":"Une couturière note dans un tableur : en colonne A le type de tenue, en B la quantité vendue, en C le prix unitaire, pour 6 types de tenues (lignes 2 à 7).","tache":"Indique la formule à écrire en D2 pour le montant, comment l'étendre aux autres lignes, et la formule du chiffre d'affaires total en D8."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-info-r11",{"duree":20,"titre":"Utilisation des fonctions dans un tableur","accroche":"Des calculs tout faits.","intro":"Les fonctions du tableur réalisent en une instruction des calculs courants : somme, moyenne, maximum, test logique.","objectifs":["utiliser les fonctions statistiques","utiliser la fonction SI","utiliser une référence absolue"],"parties":[{"t":"Fonctions usuelles","html":"<div class='def'><b>Définition</b>Une <strong>fonction</strong> est une formule prédéfinie du tableur, qui s'écrit NOM(arguments) : <code>=SOMME(B2:B20)</code>, <code>=MOYENNE(B2:B20)</code>, <code>=MAX(B2:B20)</code>, <code>=MIN(B2:B20)</code>, <code>=NB(B2:B20)</code>.</div>"},{"t":"La fonction SI","verrou":true},{"t":"Référence absolue","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"info","rang":11,"apc":{"module":"Tableur et présentation","famille":"Outils de productivité","agir":"Produire des documents de calcul et de présentation","situation":"Un commerçant affiche ses prix hors taxe en colonne B (lignes 2 à 30) et le taux de TVA de 19,25 % dans la cellule F1.","tache":"Écris en C2 la formule du prix toutes taxes comprises, recopiable vers le bas, puis la formule du prix TTC le plus élevé."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-info-r12",{"duree":20,"titre":"Insertion des graphiques et impression","accroche":"Montrer les chiffres en images.","intro":"Un graphique rend des données lisibles d'un coup d'œil. Il faut choisir le type adapté puis préparer l'impression.","objectifs":["choisir le type de graphique adapté","créer et personnaliser un graphique","imprimer un classeur"],"parties":[{"t":"Choisir le graphique","html":"<div class='def'><b>Définition</b>Un <strong>graphique</strong> est la représentation visuelle d'une série de données d'un tableur.</div><ul><li><strong>histogramme</strong> (barres) : comparer des quantités ;</li><li><strong>courbe</strong> : montrer une évolution dans le temps ;</li><li><strong>secteurs</strong> (camembert) : montrer la répartition d'un total ;</li><li><strong>nuage de points</strong> : relier deux variables.</li></ul>"},{"t":"Créer et personnaliser","verrou":true},{"t":"Imprimer","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"info","rang":12,"apc":{"module":"Tableur et présentation","famille":"Outils de productivité","agir":"Produire des documents de calcul et de présentation","situation":"La coopérative de ton village a vendu en 2026 : 40 % de cacao, 35 % de café, 15 % de banane et 10 % de manioc ; elle veut aussi montrer l'évolution de ses ventes mensuelles.","tache":"Choisis un graphique pour chaque besoin, justifie, et cite trois éléments à ajouter à chaque graphique."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-info-r13",{"duree":20,"titre":"Création d'une diapositive","accroche":"Préparer un diaporama.","intro":"Le logiciel de présentation (PowerPoint, Impress) permet d'appuyer un exposé oral par des diapositives claires.","objectifs":["créer une présentation","choisir une disposition et un thème","respecter les règles d'une bonne diapositive"],"parties":[{"t":"Présentation et diapositive","html":"<div class='def'><b>Définition</b>Une <strong>présentation assistée par ordinateur</strong> (PréAO) est un ensemble de <strong>diapositives</strong> projetées pour appuyer un exposé oral.</div><p>On crée une nouvelle présentation, on choisit un <strong>thème</strong> (couleurs, polices) et une <strong>disposition</strong> pour chaque diapositive (titre, titre et contenu, deux colonnes).</p>"},{"t":"Structure d'un diaporama","html":"<ol><li>Diapositive de titre (sujet, noms, classe).</li><li>Plan.</li><li>Une diapositive par idée principale.</li><li>Conclusion.</li><li>Sources.</li></ol>","retenir":"Titre, plan, idées, conclusion, sources.","labo":{"type":"etapes","items":[["Titre","sujet, auteurs, classe."],["Plan","les grandes parties."],["Idées","une par diapositive."],["Conclusion","le message à retenir."],["Sources","documents utilisés."]]}},{"t":"Une bonne diapositive","html":"<p>Une idée par diapositive, des mots-clés plutôt que des phrases (six lignes au plus), une police lisible (au moins 24 points), un bon contraste. L'orateur explique ; la diapositive résume.</p><div class='attention'><b>Attention</b>recopier tout son texte sur les diapositives et le lire au public rend l'exposé ennuyeux.</div>"},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Question de cours.</strong> La PréAO sert à :</p><ol type='a'><li>calculer les moyennes trimestrielles d'une classe entière</li><li>retoucher des photographies anciennes</li><li>créer des diapositives pour appuyer un exposé</li><li>gérer une base de données d'élèves</li></ol><details><summary>Voir la réponse</summary><p><strong>créer des diapositives pour appuyer un exposé</strong>. Présentation assistée par ordinateur.</p></details><p><strong>Exercice.</strong></p><p>Combien de lignes au plus conseille-t-on par diapositive ?</p><details><summary>Voir la réponse</summary><p>(Réponse : environ six lignes de mots-clés.)</p></details></div>","retenir":"Savoir-être mobilisé : Créativité."}],"revision":["PréAO : diapositives pour appuyer l'oral.","Thème et disposition.","Une idée, mots-clés, 24 points, contraste."],"exo":"<p>Combien de lignes au plus conseille-t-on par diapositive ? <em>(Réponse : environ six lignes de mots-clés.)</em></p>","quiz":[{"q":"La PréAO sert à :","r":["calculer les moyennes trimestrielles d'une classe entière","retoucher des photographies anciennes","créer des diapositives pour appuyer un exposé","gérer une base de données d'élèves"],"b":2,"e":"Présentation assistée par ordinateur."},{"q":"PowerPoint et Impress sont des logiciels de :","r":["tableur","dessin vectoriel","messagerie","présentation"],"b":3,"e":"Ils produisent des diaporamas."},{"q":"Sur une diapositive, il vaut mieux écrire :","r":["des mots-clés","tout le texte de l'exposé","des paragraphes très longs","des phrases en tout petit"],"b":0,"e":"L'orateur développe à l'oral."},{"q":"Une bonne règle est de mettre par diapositive :","r":["toutes les idées de l'exposé","une seule idée principale","au moins dix paragraphes","aucun titre ni image"],"b":1,"e":"La diapositive reste lisible."},{"q":"La taille minimale conseillée du texte est d'environ :","r":["8 points","10 points","24 points","6 points"],"b":2,"e":"Il doit se lire du fond de la salle."},{"q":"Le thème d'une présentation définit :","r":["le nombre de diapositives obligatoires","le temps de parole de l'orateur","le nom du fichier enregistré","les couleurs et les polices communes"],"b":3,"e":"Il assure l'unité visuelle."},{"q":"La disposition d'une diapositive est :","r":["l'organisation de ses zones (titre, contenu)","la vitesse de passage d'une diapositive à la suivante","la taille du fichier sur le disque","la langue de correction orthographique"],"b":0,"e":"Titre seul, titre et contenu, deux colonnes…"},{"q":"Un bon contraste, c'est :","r":["un texte jaune sur un fond blanc","un texte foncé sur un fond clair","un texte gris sur un fond gris","un texte rouge sur un fond rouge"],"b":1,"e":"Le texte doit se détacher du fond."},{"q":"Pour ajouter une diapositive, on utilise :","r":["Enregistrer sous","Imprimer","Nouvelle diapositive","Fermer"],"b":2,"e":"Dans l'onglet Accueil."},{"q":"La première diapositive d'un exposé présente en général :","r":["la conclusion détaillée","la bibliographie complète","les remerciements finaux","le titre et les auteurs"],"b":3,"e":"C'est la diapositive de titre."}],"c":"1re A","m":"info","rang":13,"apc":{"module":"Tableur et présentation","famille":"Outils de productivité","agir":"Produire des documents de calcul et de présentation","situation":"Pour un exposé de 10 minutes sur l'Unité nationale, ton camarade a préparé 4 diapositives contenant chacune un paragraphe de 15 lignes en police 12.","tache":"Explique les défauts de son diaporama et propose une structure améliorée."},"gratuit":true});
VRT_L("1re-a-info-r14",{"duree":20,"titre":"Enrichissement d'une diapositive","accroche":"Images, animations et transitions.","intro":"Une diapositive enrichie retient l'attention, à condition de rester sobre : images, graphiques, animations et transitions doivent servir le message.","objectifs":["insérer images, tableaux et graphiques","appliquer animations et transitions","préparer la projection"],"parties":[{"t":"Insérer des objets","html":"<div class='def'><b>Définition</b><strong>Enrichir une diapositive</strong>, c'est y ajouter des éléments non textuels qui rendent le message plus clair : images, formes, tableaux, graphiques, vidéos, sons, liens.</div>"},{"t":"Animations et transitions","verrou":true},{"t":"Projeter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"info","rang":14,"apc":{"module":"Tableur et présentation","famille":"Outils de productivité","agir":"Produire des documents de calcul et de présentation","situation":"Le diaporama d'un groupe utilise une transition différente à chaque diapositive, des textes qui tournoient et un son de klaxon à chaque apparition.","tache":"Explique pourquoi ces choix nuisent à l'exposé et propose trois règles d'enrichissement."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-info-r15",{"duree":20,"titre":"Éléments d'un algorithme","accroche":"La structure d'une solution.","intro":"Un algorithme décrit étape par étape la résolution d'un problème. Il comporte des éléments fixes : en-tête, déclarations et instructions.","objectifs":["définir un algorithme","identifier ses parties","utiliser variables, constantes et types"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Un <strong>algorithme</strong> est une suite finie et ordonnée d'instructions précises qui permet de résoudre un problème.</div><pre>Algorithme Surface\nVariables longueur, largeur, s : réels\nDébut\n   Lire(longueur, largeur)\n   s ← longueur * largeur\n   Écrire(\"Surface : \", s)\nFin</pre>"},{"t":"Les parties","verrou":true},{"t":"Les instructions de base","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"info","rang":15,"apc":{"module":"Algorithmique et programmation HTML","famille":"Algorithmique et programmation","agir":"Résoudre un problème simple et créer une page web","situation":"Un parent veut connaître le coût total de la scolarité de ses enfants : il connaît le nombre d'enfants et les frais par enfant.","tache":"Écris l'algorithme complet en identifiant ses trois parties."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-info-r16",{"duree":20,"titre":"Structures de contrôle","accroche":"Décider et répéter.","intro":"Les structures de contrôle modifient l'ordre d'exécution des instructions : elles permettent de choisir et de répéter.","objectifs":["écrire une structure alternative","écrire une boucle Pour et Tant que","choisir la structure adaptée"],"parties":[{"t":"L'alternative","html":"<div class='def'><b>Définition</b>Une <strong>structure de contrôle</strong> détermine l'ordre d'exécution des instructions : <strong>séquence</strong>, <strong>alternative</strong> (Si) ou <strong>répétition</strong> (boucle).</div><pre>Si age ≥ 20 Alors\n   Écrire(\"Tu peux voter\")\nSinon\n   Écrire(\"Tu ne peux pas encore voter\")\nFinSi</pre>"},{"t":"Les boucles","verrou":true},{"t":"Les conditions","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"info","rang":16,"apc":{"module":"Algorithmique et programmation HTML","famille":"Algorithmique et programmation","agir":"Résoudre un problème simple et créer une page web","situation":"Un cinéma de Yaoundé applique un tarif de 1 500 F pour les moins de 12 ans, 2 500 F pour les élèves (12 à 20 ans) et 3 500 F pour les adultes.","tache":"Écris l'algorithme qui lit l'âge et affiche le tarif."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-info-r17",{"duree":20,"titre":"Exécution d'un algorithme","accroche":"Vérifier à la main.","intro":"Avant de programmer, on vérifie un algorithme en l'exécutant à la main avec des valeurs d'essai : c'est la trace.","objectifs":["construire un tableau de trace","exécuter un algorithme avec boucle","détecter une erreur"],"parties":[{"t":"Le tableau de trace","html":"<div class='def'><b>Définition</b><strong>Exécuter un algorithme</strong> (faire sa trace), c'est suivre ses instructions une à une en notant la valeur de chaque variable dans un tableau.</div>"},{"t":"Exemple","verrou":true},{"t":"Détecter les erreurs","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"info","rang":17,"apc":{"module":"Algorithmique et programmation HTML","famille":"Algorithmique et programmation","agir":"Résoudre un problème simple et créer une page web","situation":"Un algorithme doit compter les nombres pairs parmi 5 valeurs lues : nb ← 0 ; Pour i ← 1 à 5 Faire Lire(x) ; Si x mod 2 = 1 Alors nb ← nb + 1 FinSi FinPour ; Écrire(nb). On teste avec 4, 7, 10, 3, 8.","tache":"Fais la trace, donne le résultat affiché et corrige l'erreur."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-info-r18",{"duree":20,"titre":"Organigrammes","accroche":"Dessiner un algorithme.","intro":"Un organigramme (algorigramme) représente graphiquement la logique d'un algorithme à l'aide de symboles normalisés.","objectifs":["connaître les symboles","traduire un algorithme en organigramme","lire un organigramme"],"parties":[{"t":"Les symboles","html":"<div class='def'><b>Définition</b>Un <strong>organigramme de programmation</strong> est un schéma qui représente un algorithme par des symboles normalisés reliés par des flèches indiquant l'ordre d'exécution.</div><ul><li>ovale : début, fin ;</li><li>parallélogramme : entrée, sortie ;</li><li>rectangle : traitement ;</li><li>losange : test, avec deux sorties Oui et Non.</li></ul>"},{"t":"Représenter une boucle","verrou":true},{"t":"Lire un organigramme","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"info","rang":18,"apc":{"module":"Algorithmique et programmation HTML","famille":"Algorithmique et programmation","agir":"Résoudre un problème simple et créer une page web","situation":"Le distributeur de boissons du foyer rend la monnaie : il lit le montant inséré ; si le montant est inférieur au prix de 300 F, il affiche « Montant insuffisant », sinon il délivre la boisson et rend la différence.","tache":"Décris l'organigramme symbole par symbole."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-info-r19",{"duree":20,"titre":"Généralités sur le HTML","accroche":"Le langage des pages web.","intro":"Toutes les pages web sont écrites en HTML, un langage à balises que le navigateur interprète pour afficher le contenu.","objectifs":["définir HTML, balise et navigateur","connaître la structure d'une page","créer et ouvrir une première page"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définition</b>Le <strong>HTML</strong> (HyperText Markup Language) est le langage de description du contenu des pages web. Il utilise des <strong>balises</strong> ouvrantes et fermantes (&lt;p&gt; ... &lt;/p&gt;), interprétées par un <strong>navigateur</strong> (Chrome, Firefox, Edge).</div>"},{"t":"Structure d'une page","verrou":true},{"t":"Créer une page","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"info","rang":19,"apc":{"module":"Algorithmique et programmation HTML","famille":"Algorithmique et programmation","agir":"Résoudre un problème simple et créer une page web","situation":"Ton camarade a écrit « <b><i>Club</b></i> » et enregistré sa page sous « page.txt » ; elle s'affiche comme du texte brut.","tache":"Relève ses deux erreurs et corrige-les."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-info-r20",{"duree":20,"titre":"Mise en forme d'un document HTML","accroche":"Titres, paragraphes et styles.","intro":"Le HTML structure le texte en titres, paragraphes et listes ; quelques balises et le CSS permettent de le mettre en forme.","objectifs":["utiliser les balises de structure du texte","mettre en valeur du texte","appliquer un style simple"],"parties":[{"t":"Structurer le texte","html":"<div class='def'><b>Définition</b><strong>Mettre en forme un document HTML</strong>, c'est organiser et présenter son texte : titres de niveaux 1 à 6 (&lt;h1&gt; à &lt;h6&gt;), paragraphes (&lt;p&gt;), sauts de ligne (&lt;br&gt;), lignes horizontales (&lt;hr&gt;).</div>"},{"t":"Mettre en valeur","verrou":true},{"t":"Un style simple","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"info","rang":20,"apc":{"module":"Algorithmique et programmation HTML","famille":"Algorithmique et programmation","agir":"Résoudre un problème simple et créer une page web","situation":"Pour la page « Histoire du lycée », tu dois afficher un titre principal, deux sous-parties avec leur titre, des paragraphes et mettre en évidence la date de création.","tache":"Décris le code HTML organisé de cette page."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-info-r21",{"duree":20,"titre":"Images, liens et listes dans une page web","accroche":"Relier et illustrer.","intro":"Le web repose sur les liens hypertextes qui relient les pages entre elles. On illustre aussi les pages par des images et on organise l'information en listes.","objectifs":["insérer une image","créer un lien hypertexte","créer des listes"],"parties":[{"t":"Les images","html":"<div class='def'><b>Définition</b>Un <strong>lien hypertexte</strong> est un élément cliquable qui mène vers une autre page, un autre site, une partie de la page ou un fichier ; il s'écrit avec la balise &lt;a href=\"...\"&gt;.</div><pre>&lt;img src=\"images/drapeau.png\" alt=\"Drapeau du Cameroun\" width=\"300\"&gt;</pre>"},{"t":"Les liens","verrou":true},{"t":"Les listes","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"info","rang":21,"apc":{"module":"Algorithmique et programmation HTML","famille":"Algorithmique et programmation","agir":"Résoudre un problème simple et créer une page web","situation":"La page d'accueil du club doit afficher le logo, une liste à puces des activités (programmation, infographie, robotique) et un lien vers la page « inscription.html ».","tache":"Écris le code HTML correspondant."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-info-r22",{"duree":20,"titre":"Insertion d'un formulaire dans une page web","accroche":"Recueillir des informations.","intro":"Un formulaire HTML permet aux visiteurs de saisir des informations : inscription, contact, sondage.","objectifs":["créer un formulaire","utiliser les principaux champs","rendre le formulaire clair"],"parties":[{"t":"Le formulaire","html":"<div class='def'><b>Définition</b>Un <strong>formulaire</strong> est une zone de page web délimitée par &lt;form&gt; ... &lt;/form&gt;, qui contient des champs de saisie et un bouton d'envoi.</div>"},{"t":"Les champs","verrou":true},{"t":"Bonnes pratiques","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"info","rang":22,"apc":{"module":"Algorithmique et programmation HTML","famille":"Algorithmique et programmation","agir":"Résoudre un problème simple et créer une page web","situation":"Le club théâtre veut un formulaire de sondage : nom, classe (liste), rôle souhaité (acteur, décor, costumes : un seul choix), et suggestions libres.","tache":"Indique les champs HTML à utiliser pour chaque information."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-info-r23",{"duree":20,"titre":"Généralités sur l'infographie","accroche":"L'image au service de la communication.","intro":"L'infographie produit les images de la publicité, de la presse, du web et des jeux. Elle offre de nombreux débouchés aux élèves de série littéraire et artistique.","objectifs":["définir l'infographie","distinguer image matricielle et vectorielle","citer des domaines d'application"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>L'<strong>infographie</strong> est la création et le traitement d'images à l'aide de l'ordinateur.</div><p>Elle comprend le dessin (illustration, logo), la retouche photographique, la mise en page (PAO), l'animation et la modélisation en 3D.</p>"},{"t":"Deux types d'images","html":"<ul><li><strong>Matricielle</strong> (bitmap) : grille de pixels ; idéale pour les photos ; se dégrade à l'agrandissement (JPEG, PNG).</li><li><strong>Vectorielle</strong> : formes mathématiques ; idéale pour les logos et les illustrations ; reste nette à toute taille (SVG, AI).</li></ul>","retenir":"Photo : matriciel ; logo : vectoriel.","labo":{"type":"trier","invite":"Choisis une notion.","items":[["Image matricielle","pixels ; photos ; se dégrade à l'agrandissement."],["Image vectorielle","formes mathématiques ; nette à toute taille."],["Retouche","corriger une photographie."],["PAO","mise en page de documents."]]}},{"t":"Domaines d'application","html":"<p>Publicité et affiches, presse et édition, emballages, sites web et réseaux sociaux, cinéma et jeux vidéo, cartographie. Métiers : infographiste, graphiste, maquettiste, motion designer.</p><div class='attention'><b>Attention</b>les images trouvées sur internet sont protégées par le droit d'auteur, sauf mention d'une licence libre.</div>"},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Question de cours.</strong> L'infographie est :</p><ol type='a'><li>la réparation des ordinateurs portables</li><li>la création d'images par ordinateur</li><li>la programmation des microcontrôleurs</li><li>la gestion d'une base de données</li></ol><details><summary>Voir la réponse</summary><p><strong>la création d'images par ordinateur</strong>. Dessins, retouches, animations.</p></details><p><strong>Exercice.</strong></p><p>Quel type d'image choisir pour un logo ?</p><details><summary>Voir la réponse</summary><p>(Réponse : une image vectorielle, qui reste nette à toutes les tailles.)</p></details></div>","retenir":"Savoir-être mobilisé : Créativité."}],"revision":["Infographie : images par ordinateur.","Matriciel (pixels) / vectoriel (formes).","Domaines : publicité, presse, web, cinéma ; métiers du graphisme."],"exo":"<p>Quel type d'image choisir pour un logo ? <em>(Réponse : une image vectorielle, qui reste nette à toutes les tailles.)</em></p>","quiz":[{"q":"L'infographie est :","r":["la réparation des ordinateurs portables","la création d'images par ordinateur","la programmation des microcontrôleurs","la gestion d'une base de données"],"b":1,"e":"Dessins, retouches, animations."},{"q":"Une image matricielle est formée de :","r":["vecteurs","notes","pixels","cellules"],"b":2,"e":"Grille de points colorés."},{"q":"Une image vectorielle est décrite par :","r":["des pixels colorés disposés en grille","des notes de musique","des cellules de tableur","des formes mathématiques"],"b":3,"e":"Elle reste nette à toutes les tailles."},{"q":"Agrandir fortement une image matricielle la rend :","r":["floue ou pixelisée","plus nette et plus lumineuse","vectorielle","plus légère"],"b":0,"e":"Les pixels deviennent visibles."},{"q":"Un logo destiné à de nombreux formats doit être :","r":["matriciel","vectoriel","animé","sonore"],"b":1,"e":"Il reste net sur toutes les tailles."},{"q":"Un domaine de l'infographie est :","r":["la comptabilité","la mécanique","la publicité","la plomberie"],"b":2,"e":"Affiches, spots, emballages."},{"q":"Le graphiste est un professionnel qui :","r":["répare des réseaux électriques","écrit des lois pour l'État","gère des comptes bancaires","conçoit des supports visuels"],"b":3,"e":"Logos, affiches, sites web."},{"q":"Une photo numérique est une image :","r":["matricielle","vectorielle","sonore","textuelle"],"b":0,"e":"Elle est faite de pixels."},{"q":"L'infographie sert au cinéma pour :","r":["vendre les billets d'entrée","créer des effets spéciaux","nettoyer la salle de projection","écrire le scénario"],"b":1,"e":"Images de synthèse."},{"q":"Le format SVG est :","r":["matriciel","sonore","vectoriel","vidéo"],"b":2,"e":"Scalable Vector Graphics."}],"c":"1re A","m":"info","rang":23,"apc":{"module":"Infographie et multimédia","famille":"Création numérique","agir":"Produire et traiter des contenus multimédias","situation":"Le comité des fêtes de ton quartier veut une affiche avec une photo de la place du marché et le logo du comité, imprimée en format A2.","tache":"Indique le type d'image adapté à chaque élément et un point de vigilance pour chacun."},"gratuit":true});
VRT_L("1re-a-info-r24",{"duree":20,"titre":"Besoins matériels et logiciels en infographie","accroche":"S'équiper pour créer.","intro":"L'infographie demande un ordinateur performant, des périphériques adaptés et des logiciels spécialisés, dont beaucoup sont gratuits.","objectifs":["identifier le matériel nécessaire","citer des logiciels adaptés","choisir un équipement selon un budget"],"parties":[{"t":"Le matériel","html":"<div class='def'><b>Définition</b>Les <strong>besoins en infographie</strong> sont les équipements matériels et logiciels nécessaires pour créer et traiter des images dans de bonnes conditions.</div><ul><li>processeur performant et mémoire vive suffisante (8 Go ou plus) ;</li><li>carte graphique et écran de bonne qualité aux couleurs fidèles ;</li><li>tablette graphique et stylet pour dessiner ;</li><li>scanner, appareil photo, imprimante couleur ;</li><li>espace de stockage important.</li></ul>"},{"t":"Les logiciels","verrou":true},{"t":"Choisir selon le budget","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"info","rang":24,"apc":{"module":"Infographie et multimédia","famille":"Création numérique","agir":"Produire et traiter des contenus multimédias","situation":"Une jeune graphiste de Bafoussam dispose de 400 000 F pour s'équiper afin de créer des affiches et des logos pour les commerçants.","tache":"Propose un équipement matériel et logiciel cohérent avec ce budget, en justifiant."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-info-r25",{"duree":20,"titre":"Introduction au traitement d'images","accroche":"Comprendre l'image numérique.","intro":"Avant de retoucher une image, il faut comprendre ses caractéristiques : définition, résolution, couleurs et formats.","objectifs":["définir pixel, définition et résolution","connaître le codage des couleurs","choisir un format d'image"],"parties":[{"t":"Caractéristiques","html":"<div class='def'><b>Définition</b>Le <strong>traitement d'images</strong> est l'ensemble des opérations réalisées sur une image numérique pour la modifier ou l'améliorer : recadrer, redimensionner, corriger les couleurs, retoucher.</div><p>Le <strong>pixel</strong> est le plus petit point de l'image ; la <strong>définition</strong> est le nombre de pixels (1920 × 1080) ; la <strong>résolution</strong> est le nombre de pixels par pouce (ppp).</p>"},{"t":"Les couleurs","verrou":true},{"t":"Les formats","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"info","rang":25,"apc":{"module":"Infographie et multimédia","famille":"Création numérique","agir":"Produire et traiter des contenus multimédias","situation":"Un élève veut imprimer en grand format (affiche) une photo téléchargée de 640 × 480 pixels.","tache":"Calcule la taille maximale d'impression de qualité à 300 ppp et conclus."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-info-r26",{"duree":20,"titre":"Manipulation des images","accroche":"Recadrer, redimensionner, retoucher.","intro":"Les logiciels de retouche permettent d'adapter une image à son usage : couper, redimensionner, corriger, assembler.","objectifs":["recadrer et redimensionner une image","corriger luminosité et contraste","utiliser les calques"],"parties":[{"t":"Recadrer et redimensionner","html":"<div class='def'><b>Définition</b><strong>Recadrer</strong> une image, c'est en garder seulement une partie ; la <strong>redimensionner</strong>, c'est changer son nombre de pixels.</div><p>On conserve les proportions en verrouillant le rapport largeur/hauteur. Agrandir une image ne crée pas de détails : elle devient floue.</p>"},{"t":"Corriger","verrou":true},{"t":"Les calques","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"info","rang":26,"apc":{"module":"Infographie et multimédia","famille":"Création numérique","agir":"Produire et traiter des contenus multimédias","situation":"Pour la page Facebook du club, il faut une image de couverture de 820 × 312 pixels à partir d'une photo de groupe de 4000 × 3000 pixels, un peu sombre, sur laquelle on ajoutera le nom du club.","tache":"Décris dans l'ordre les manipulations à effectuer dans un logiciel de retouche."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-info-r27",{"duree":20,"titre":"Introduction au traitement de sons et vidéos","accroche":"Le son et l'image animée numériques.","intro":"Le son et la vidéo numériques sont des suites de données. Leur qualité et leur poids dépendent de leurs caractéristiques et de leur format.","objectifs":["décrire les caractéristiques d'un son et d'une vidéo","citer les formats courants","choisir le matériel d'enregistrement"],"parties":[{"t":"Le son numérique","html":"<div class='def'><b>Définition</b>Le <strong>son numérique</strong> est la représentation d'un son par une suite de mesures (échantillons) prises à intervalles réguliers. Ses caractéristiques sont la <strong>fréquence d'échantillonnage</strong> (44 100 Hz pour un CD), la <strong>résolution</strong> (16 bits) et le nombre de <strong>canaux</strong> (mono, stéréo).</div>"},{"t":"La vidéo numérique","verrou":true},{"t":"Formats et matériel","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"info","rang":27,"apc":{"module":"Infographie et multimédia","famille":"Création numérique","agir":"Produire et traiter des contenus multimédias","situation":"Le club journalisme veut enregistrer une interview du proviseur pour la publier sur les réseaux sociaux ; il ne dispose que d'un smartphone dans un couloir bruyant.","tache":"Propose des conditions et un matériel d'enregistrement, et le format final."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-info-r28",{"duree":20,"titre":"Traitement des sons et vidéos","accroche":"Monter un petit film.","intro":"Le montage assemble, coupe et enrichit les séquences pour produire une vidéo claire. Des logiciels gratuits suffisent pour débuter.","objectifs":["couper et assembler des séquences","ajouter titres, musique et transitions","exporter une vidéo"],"parties":[{"t":"Le montage","html":"<div class='def'><b>Définition</b>Le <strong>montage</strong> est l'opération qui consiste à sélectionner, couper, ordonner et assembler des séquences vidéo et sonores pour réaliser un film cohérent.</div><p>Logiciels : Shotcut, OpenShot, DaVinci Resolve (gratuits), applications mobiles de montage ; Audacity pour le son.</p>"},{"t":"Les opérations","verrou":true},{"t":"Exporter","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"info","rang":28,"apc":{"module":"Infographie et multimédia","famille":"Création numérique","agir":"Produire et traiter des contenus multimédias","situation":"Le club a filmé 40 minutes de la journée culturelle du lycée et doit publier une vidéo de 3 minutes sur la page du lycée.","tache":"Décris les étapes du montage et deux règles de droit à respecter."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-info-r29",{"duree":20,"titre":"Exemples et services des réseaux sociaux","accroche":"Connaître les plateformes.","intro":"Les réseaux sociaux sont devenus des outils de communication, d'information et de commerce. Chacun offre des services différents.","objectifs":["définir un réseau social","citer des réseaux et leurs services","identifier leurs usages"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Un <strong>réseau social</strong> est un service en ligne qui permet de créer un profil, de se connecter à d'autres personnes et de partager des contenus (textes, photos, vidéos) et des messages.</div>"},{"t":"Exemples et services","verrou":true},{"t":"Usages","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"info","rang":29,"apc":{"module":"Réseaux sociaux, cloud et virtualisation","famille":"Citoyenneté numérique","agir":"Utiliser les services en ligne de façon responsable","situation":"Une vendeuse de jus naturels de Douala veut faire connaître son activité et recevoir des commandes en ligne avec peu de moyens.","tache":"Propose deux réseaux sociaux adaptés et explique comment les utiliser."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-info-r30",{"duree":20,"titre":"Exploitation des réseaux sociaux","accroche":"Utiliser les réseaux avec responsabilité.","intro":"Les réseaux sociaux offrent des opportunités mais comportent des risques. L'usage responsable protège sa réputation et celle des autres.","objectifs":["identifier les risques des réseaux sociaux","protéger son identité numérique","publier de façon responsable"],"parties":[{"t":"Les risques","html":"<div class='def'><b>Définition</b>L'<strong>identité numérique</strong> est l'ensemble des traces laissées sur internet par une personne : profils, publications, photos, commentaires, mentions par d'autres.</div><p>Risques : cyberharcèlement, arnaques, usurpation d'identité, fausses informations, atteinte à la vie privée, dépendance, publications regrettées qui nuisent plus tard (recherche d'emploi).</p>"},{"t":"Se protéger","verrou":true},{"t":"Publier de façon responsable","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"info","rang":30,"apc":{"module":"Réseaux sociaux, cloud et virtualisation","famille":"Citoyenneté numérique","agir":"Utiliser les services en ligne de façon responsable","situation":"Mireille, 17 ans, a un profil public avec sa photo, le nom de son lycée, son numéro de téléphone et ses horaires de sortie ; un inconnu lui envoie des messages insistants.","tache":"Identifie les risques auxquels elle s'expose et propose quatre réglages ou actions."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-info-r31",{"duree":20,"titre":"Initiation au cloud computing","accroche":"Travailler sur des ordinateurs distants.","intro":"Le cloud (« nuage ») permet de stocker des fichiers et d'utiliser des logiciels sur des serveurs accessibles par internet.","objectifs":["définir le cloud computing","citer des services en nuage","en évaluer avantages et limites"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>cloud computing</strong> (informatique en nuage) est l'utilisation, par internet, de ressources informatiques (stockage, logiciels, puissance de calcul) hébergées sur des serveurs distants appartenant à un fournisseur.</div>"},{"t":"Services","verrou":true},{"t":"Avantages et limites","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"info","rang":31,"apc":{"module":"Réseaux sociaux, cloud et virtualisation","famille":"Citoyenneté numérique","agir":"Utiliser les services en ligne de façon responsable","situation":"Quatre élèves habitant des quartiers différents doivent rédiger ensemble un dossier en deux semaines ; jusqu'ici, ils s'envoient des versions par clé USB et perdent leurs modifications.","tache":"Montre comment le cloud résout leur problème et indique deux précautions."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-info-r32",{"duree":20,"titre":"Notions de base sur la virtualisation","accroche":"Plusieurs ordinateurs dans un seul.","intro":"La virtualisation permet de faire fonctionner plusieurs systèmes d'exploitation sur une même machine physique. C'est la base des centres de données et du cloud.","objectifs":["définir la virtualisation","décrire le rôle de l'hyperviseur","citer des usages"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>virtualisation</strong> est une technique qui permet de créer, sur un ordinateur physique, une ou plusieurs <strong>machines virtuelles</strong> : des ordinateurs simulés, chacun avec son système d'exploitation et ses applications.</div>"},{"t":"L'hyperviseur","verrou":true},{"t":"Usages","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"info","rang":32,"apc":{"module":"Réseaux sociaux, cloud et virtualisation","famille":"Citoyenneté numérique","agir":"Utiliser les services en ligne de façon responsable","situation":"Le club informatique veut apprendre à installer Linux, mais le proviseur refuse qu'on touche au système Windows des ordinateurs de la salle, qui ont 8 Go de RAM.","tache":"Propose une solution par la virtualisation et décris sa mise en œuvre."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-info-r01",{"duree":20,"titre":"L'IA dans les métiers et les filières professionnelles","accroche":"L'IA transforme le travail.","intro":"L'intelligence artificielle s'invite dans presque tous les métiers. Connaître ses usages professionnels aide à choisir sa filière et à se préparer.","objectifs":["citer des usages professionnels de l'IA","identifier les compétences nouvelles","mesurer les effets de l'IA sur l'emploi"],"parties":[{"t":"L'IA au travail","html":"<div class='def'><b>Définition</b>Une <strong>application professionnelle de l'IA</strong> est l'usage d'un système d'intelligence artificielle pour accomplir ou faciliter une tâche de travail : analyser, rédiger, diagnostiquer, prévoir, automatiser.</div><ul><li><strong>santé</strong> : aide au diagnostic sur images ;</li><li><strong>droit et administration</strong> : recherche et résumé de textes ;</li><li><strong>agriculture</strong> : prévision des récoltes, détection des maladies ;</li><li><strong>banque</strong> : détection des fraudes, analyse du risque de crédit ;</li><li><strong>communication</strong> : rédaction, traduction, création d'images.</li></ul>"},{"t":"Effets sur l'emploi","html":"<p>L'IA automatise des tâches répétitives, transforme des métiers et en crée de nouveaux (analyste de données, ingénieur en IA, spécialiste de l'éthique des données). Les compétences clés deviennent : esprit critique, maîtrise des outils numériques, créativité, communication.</p>","retenir":"Automatiser, transformer, créer des métiers.","labo":{"type":"trier","invite":"Choisis un secteur.","items":[["Santé","aide au diagnostic sur images."],["Banque","détection des fraudes et du risque."],["Agriculture","prévision des récoltes."],["Communication","rédaction et traduction assistées."]]}},{"t":"Se préparer","html":"<p>Quelle que soit la filière, l'élève a intérêt à maîtriser les outils, à apprendre à vérifier les résultats d'une IA et à développer les compétences humaines que la machine remplace mal : relation, jugement, sens éthique.</p><div class='attention'><b>Attention</b>l'IA ne supprime pas la responsabilité du professionnel : c'est lui qui répond de la décision.</div>"},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Question de cours.</strong> Dans un cabinet médical, l'IA peut servir à :</p><ol type='a'><li>signer les ordonnances à la place du médecin</li><li>analyser des radiographies</li><li>remplacer définitivement tous les infirmiers</li><li>décider seule des traitements sans aucun contrôle</li></ol><details><summary>Voir la réponse</summary><p><strong>analyser des radiographies</strong>. Elle aide au diagnostic ; le médecin décide.</p></details><p><strong>Exercice.</strong></p><p>Cite un nouveau métier lié à l'IA.</p><details><summary>Voir la réponse</summary><p>(Réponse : analyste de données ou ingénieur en intelligence artificielle.)</p></details></div>","retenir":"Savoir-être mobilisé : Esprit critique."}],"revision":["Usages : santé, droit, agriculture, banque, communication.","Effets : automatisation, transformation, nouveaux métiers.","Compétences : esprit critique, outils, créativité, éthique."],"exo":"<p>Cite un nouveau métier lié à l'IA. <em>(Réponse : analyste de données ou ingénieur en intelligence artificielle.)</em></p>","quiz":[{"q":"Dans un cabinet médical, l'IA peut servir à :","r":["signer les ordonnances à la place du médecin","analyser des radiographies","remplacer définitivement tous les infirmiers","décider seule des traitements sans aucun contrôle"],"b":1,"e":"Elle aide au diagnostic ; le médecin décide."},{"q":"L'automatisation par l'IA touche surtout :","r":["les décisions éthiques les plus délicates","les métiers qui demandent de l'empathie","les tâches répétitives","les relations humaines entre collègues"],"b":2,"e":"Saisie, tri, classement, réponses standard."},{"q":"Un métier né avec l'IA est :","r":["porteur d'eau dans les quartiers anciens","conducteur de calèche dans les grandes villes","allumeur de réverbères à huile","ingénieur en données"],"b":3,"e":"Collecte, préparation et analyse des données."},{"q":"Dans le domaine juridique, l'IA peut :","r":["rechercher rapidement des textes et des décisions","rendre seule les jugements à la place du juge et des avocats","voter les lois à la place des parlementaires","arrêter les suspects dans la rue sans policier"],"b":0,"e":"Elle facilite la recherche documentaire."},{"q":"Une compétence essentielle face à l'IA est :","r":["la capacité à tout recopier sans lire","l'esprit critique","la mémorisation des mots de passe d'autrui","l'utilisation exclusive du papier et du crayon"],"b":1,"e":"Il faut juger la qualité des réponses."},{"q":"En agriculture, des drones avec IA permettent :","r":["de remplacer totalement la pluie et le soleil","de supprimer le besoin de semences de qualité","de surveiller l'état des cultures","de récolter sans aucune intervention humaine"],"b":2,"e":"Ils repèrent maladies et manque d'eau."},{"q":"Dans la banque, l'IA sert notamment à :","r":["imprimer elle-même la monnaie nationale","fixer seule le taux directeur de la BEAC","fermer les agences les jours de marché","évaluer les risques de crédit"],"b":3,"e":"Elle analyse l'historique des clients."},{"q":"En communication, l'IA générative aide à :","r":["produire des premières versions de textes et de visuels","garantir que toutes les publicités sont vraies et honnêtes","remplacer la loi sur la protection des données","interdire la publication de toute fausse information"],"b":0,"e":"Le professionnel relit et corrige."},{"q":"L'IA transforme un métier quand :","r":["elle supprime toutes les compétences humaines nécessaires","elle modifie la manière d'exécuter les tâches","elle interdit l'usage de l'ordinateur au bureau","elle rend le diplôme inutile pour tous les postes"],"b":1,"e":"Le métier évolue sans disparaître."},{"q":"Pour se préparer aux métiers de demain, il faut :","r":["éviter tout contact avec les outils numériques modernes","attendre que l'IA choisisse sa filière à sa place","apprendre à utiliser les outils d'IA avec éthique","abandonner les mathématiques et le français à l'école"],"b":2,"e":"Outils, créativité et éthique se complètent."}],"c":"1re A","m":"info","rang":1,"apc":{"module":"Intelligence artificielle appliquée et enjeux professionnels","famille":"Environnement numérique","agir":"Utiliser l'IA de façon responsable dans un projet","situation":"Ta cousine, comptable dans une PME de Douala, craint que « l'IA lui prenne son travail » depuis qu'un logiciel saisit automatiquement les factures.","tache":"Montre-lui comment son métier se transforme plutôt qu'il ne disparaît, et propose deux compétences à développer."},"gratuit":true});
VRT_L("1re-a-info-r02",{"duree":20,"titre":"Réalisation d'un projet scolaire assisté par l'IA","accroche":"Travailler avec l'IA, pas la laisser travailler.","intro":"L'IA peut aider à mener un projet scolaire, à condition de garder la maîtrise de chaque étape et de vérifier ce qu'elle produit.","objectifs":["planifier un projet scolaire","utiliser l'IA à chaque étape de façon pertinente","vérifier et déclarer l'usage de l'IA"],"parties":[{"t":"Le projet et l'IA","html":"<div class='def'><b>Définition</b>Un <strong>projet assisté par l'IA</strong> est un travail mené par l'élève dans lequel l'IA intervient comme outil d'aide (idées, plan, explications, relecture), sous son contrôle.</div>"},{"t":"Les étapes","verrou":true},{"t":"Bonnes pratiques","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"info","rang":2,"apc":{"module":"Intelligence artificielle appliquée et enjeux professionnels","famille":"Environnement numérique","agir":"Utiliser l'IA de façon responsable dans un projet","situation":"Ton groupe de quatre élèves doit réaliser en trois semaines un dossier sur le traitement des déchets plastiques à Yaoundé ; un membre propose de « tout demander à l'IA la veille ».","tache":"Propose un plan de travail en cinq étapes où l'IA intervient de façon pertinente, en précisant à chaque étape ce qui reste à la charge du groupe."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-info-r03",{"duree":20,"titre":"Cadre juridique et protection des données face à l'IA","accroche":"Nos données nourrissent l'IA.","intro":"Les systèmes d'IA utilisent d'énormes quantités de données, dont des données personnelles. La loi encadre leur collecte et leur usage.","objectifs":["définir une donnée personnelle","connaître le cadre juridique camerounais et international","protéger ses données face aux outils d'IA"],"parties":[{"t":"Données personnelles","html":"<div class='def'><b>Définition</b>Une <strong>donnée personnelle</strong> est toute information qui permet d'identifier une personne directement ou indirectement : nom, numéro de téléphone, photo, voix, adresse, localisation, numéro de compte.</div><p>Certaines sont dites <strong>sensibles</strong> : santé, religion, opinions politiques, données biométriques.</p>"},{"t":"Le cadre juridique","verrou":true},{"t":"Se protéger","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"info","rang":3,"apc":{"module":"Intelligence artificielle appliquée et enjeux professionnels","famille":"Environnement numérique","agir":"Utiliser l'IA de façon responsable dans un projet","situation":"Pour « faire rire la classe », un élève veut fournir à une application d'IA la photo et des enregistrements vocaux de son professeur afin de produire une fausse vidéo.","tache":"Identifie les données personnelles en jeu, les règles violées et les risques pour l'élève."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-info-r04",{"duree":20,"titre":"Biais algorithmiques et équité de l'IA","accroche":"Une IA peut être injuste.","intro":"Une IA apprend à partir de données produites par des humains. Si ces données sont déséquilibrées, ses décisions peuvent être injustes envers certains groupes.","objectifs":["définir un biais algorithmique","en identifier les causes","proposer des moyens de réduire les biais"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Un <strong>biais algorithmique</strong> est une erreur systématique d'une IA qui la conduit à traiter de façon injuste ou défavorable certaines personnes ou certains groupes.</div><p>Exemples : reconnaissance faciale moins précise sur les peaux foncées parce que les données d'entraînement contenaient surtout des visages clairs ; outil de recrutement qui défavorise les femmes parce qu'il a appris sur des recrutements passés.</p>"},{"t":"Les causes","verrou":true},{"t":"Vers une IA équitable","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"info","rang":4,"apc":{"module":"Intelligence artificielle appliquée et enjeux professionnels","famille":"Environnement numérique","agir":"Utiliser l'IA de façon responsable dans un projet","situation":"Une banque teste une IA d'octroi de crédit : sur 1 000 dossiers, elle accepte 62 % des demandes d'hommes et 31 % des demandes de femmes au profil financier comparable.","tache":"Montre qu'il s'agit d'un biais, explique sa cause probable et propose trois mesures."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-espagnol-r01",{"duree":20,"titre":"La familia : evolución y conflictos","accroche":"Padres e hijos : ¿dos mundos?","intro":"La famille change : exode rural, travail des deux parents, téléphones. Ces mutations créent des conflits entre générations. On apprend à les analyser et à proposer le dialogue, avec l'expression de l'obligation et le présent du subjonctif.","objectifs":["analyser les causes des conflits entre générations","exprimer l'obligation personnelle et impersonnelle","former le présent du subjonctif"],"parties":[{"t":"El conflicto generacional","html":"<div class='def'><b>Définition</b>Le <strong>conflit intergénérationnel</strong> (<em>el conflicto generacional</em>) est une opposition d'idées, de valeurs ou de comportements entre les jeunes et leurs aînés.</div><p><em>la brecha generacional, los valores, la autoridad, la desobediencia, el diálogo, comprenderse, discutir, reñir, reconciliarse</em>.</p><p><em>Los jóvenes pasan horas con el móvil y los padres piensan que no respetan las tradiciones.</em></p>"},{"t":"La obligación","html":"<p>Obligation <strong>personnelle</strong> : <em>tener que + infinitif</em> (<em>tengo que obedecer</em>), <em>deber + infinitif</em> (<em>debes escuchar</em>). Obligation <strong>impersonnelle</strong> : <em>hay que + infinitif</em> (<em>hay que dialogar</em>), <em>es necesario que + subjonctif</em>.</p>","retenir":"Hay que = il faut (impersonnel) ; tener que = devoir (personnel).","labo":{"type":"trier","invite":"Obligation personnelle ou impersonnelle ?","items":[["Hay que respetar a los padres","impersonnelle."],["Tengo que volver a las ocho","personnelle."],["Es necesario que hablemos","impersonnelle + subjonctif."],["Debes pedir perdón","personnelle."]]}},{"t":"Presente de subjuntivo","html":"<p>On part de la 1re personne du présent : <em>hablo → hable</em>, <em>tengo → tenga</em>, <em>hago → haga</em>. Verbes en -ar : <strong>-e, -es, -e, -emos, -éis, -en</strong> ; en -er/-ir : <strong>-a, -as, -a, -amos, -áis, -an</strong>. Irréguliers : <em>ser → sea, ir → vaya, estar → esté, saber → sepa</em>.</p><p><em>Es necesario que los padres escuchen a sus hijos.</em></p><div class='attention'><b>Attention</b>le subjonctif inverse la voyelle : -ar donne -e, -er/-ir donnent -a.</div>"},{"t":"Vers le Probatoire","html":"<div class='integ'><h3>Compruebo mis conocimientos</h3><p>« La brecha generacional » désigne :</p><ol type='a'><li>la réunion de toute la famille</li><li>l'héritage des grands-parents</li><li>le fossé entre les générations</li><li>la naissance d'un nouvel enfant</li></ol><details><summary>Voir la réponse</summary><p><strong>le fossé entre les générations</strong>. La brecha generacional est l'écart d'idées et de valeurs entre jeunes et aînés.</p></details><h3>Competencias lingüísticas (formato del Probatoire)</h3><p>Complète : « Es necesario que los hijos ___ (respetar) a los mayores. »</p><details><summary>Voir la réponse</summary><p>(Réponse : respeten.)</p></details><h3>Comentario dirigido y producción de textos (formato del Probatoire)</h3><p><strong>Texto.</strong> <em>« Desde que tiene móvil, Brenda no habla con sus padres. Su padre se enfada; su madre llora. Una noche, el abuelo reúne a la familia: «Hay que hablar. Es necesario que cada uno escuche al otro». »</em> (texte : Réalisation VÉRITAS).</p><p><strong>Consigna 1.</strong> Comentario dirigido : ¿Cuál es el conflicto? ¿Qué propone el abuelo? Justifica con el texto.</p><p><strong>Consigna 2.</strong> Competencias lingüísticas : pon en subjuntivo presente : «escuchar» (ellos), «ser» (yo), «tener» (nosotros).</p><p><strong>Consigna 3.</strong> Ensayo libre (10 líneas) : ¿Cómo mejorar el diálogo entre padres e hijos?</p><details><summary>Voir une réponse attendue</summary><p>Conflicto : Brenda no habla con sus padres desde que tiene móvil. El abuelo propone el diálogo : «Hay que hablar». Subjuntivo : escuchen, sea, tengamos. Ensayo : se espera una introducción, dos ideas (tiempo en familia sin pantallas ; respeto mutuo) con hay que / es necesario que, y una conclusión.</p></details></div>","retenir":"Savoir-être mobilisé : Ouverture et respect d'autrui."}],"revision":["Conflit : la brecha generacional, el diálogo, reñir, reconciliarse.","Hay que + infinitif ; tener que / deber + infinitif.","Subjonctif présent : hable, coma, viva ; sea, vaya, tenga, haga."],"exo":"<p>Complète : « Es necesario que los hijos ___ (respetar) a los mayores. » <em>(Réponse : respeten.)</em></p>","quiz":[{"q":"« La brecha generacional » désigne :","r":["la réunion de toute la famille","l'héritage des grands-parents","le fossé entre les générations","la naissance d'un nouvel enfant"],"b":2,"e":"La brecha generacional est l'écart d'idées et de valeurs entre jeunes et aînés."},{"q":"« Hay que dialogar » exprime :","r":["une obligation personnelle","un souhait très poli","une hypothèse irréelle","une obligation impersonnelle"],"b":3,"e":"Hay que + infinitif = il faut, sans sujet précis."},{"q":"« Tengo que obedecer » exprime :","r":["une obligation personnelle","une obligation impersonnelle","un fait passé et terminé","une interdiction formelle"],"b":0,"e":"Tener que + infinitif marque l'obligation d'une personne précise."},{"q":"Le subjonctif présent de hablar (ellos) est :","r":["hablan","hablen","hablaron","hablarán"],"b":1,"e":"Les verbes en -ar prennent -e au subjonctif : hablen."},{"q":"Le subjonctif présent de comer (tú) est :","r":["comes","comiste","comas","comerás"],"b":2,"e":"Les verbes en -er prennent -a au subjonctif : comas."},{"q":"Le subjonctif présent de ser (yo) est :","r":["soy","fuera","seré","sea"],"b":3,"e":"Ser est irrégulier : sea, seas, sea…"},{"q":"Complète : « Es necesario que los padres ___ (escuchar). »","r":["escuchen","escuchan","escucharán","escuchaban"],"b":0,"e":"Es necesario que impose le subjonctif : escuchen."},{"q":"« Reconciliarse » signifie :","r":["se disputer","se réconcilier","se séparer","se marier"],"b":1,"e":"Reconciliarse = faire la paix après un conflit."},{"q":"Le subjonctif présent de tener (yo) est :","r":["tengo","tenía","tenga","tendré"],"b":2,"e":"On part de tengo : tenga."},{"q":"« Reñir » signifie :","r":["se réconcilier","se rencontrer","se reposer","se disputer"],"b":3,"e":"Reñir = se quereller, se disputer."}],"c":"1re A","m":"espagnol","rang":1,"apc":{"module":"Vie familiale et intégration sociale","famille":"Vie familiale et intégration sociale","agir":"Analyser les mutations de la famille et adopter des comportements responsables","situation":"Ton cousin de 16 ans ne parle plus à son père depuis une dispute sur les sorties du samedi soir ; la famille est divisée.","tache":"Rédige en espagnol 5 conseils pour rétablir le dialogue, avec hay que, tener que et es necesario que."},"gratuit":true});
VRT_L("1re-a-espagnol-r02",{"duree":20,"titre":"La mujer y los derechos del niño","accroche":"Iguales en derechos.","intro":"La femme camerounaise travaille, étudie, dirige ; l'enfant a des droits protégés par la Convention de 1989. On apprend le vocabulaire de l'égalité et l'opposition entre ser et estar.","objectifs":["présenter le statut de la femme et les droits de l'enfant","employer correctement ser et estar","argumenter en faveur de l'égalité"],"parties":[{"t":"La mujer y el niño","html":"<div class='def'><b>Définition</b>Les <strong>droits de l'enfant</strong> (<em>los derechos del niño</em>) sont les droits reconnus à toute personne de moins de 18 ans : éducation, santé, protection, nom et nationalité.</div><p><em>la igualdad, la discriminación, el matrimonio precoz, la escolarización de las niñas, el trabajo infantil, proteger, denunciar</em>.</p>"},{"t":"Ser y estar","verrou":true},{"t":"Argumentar","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"espagnol","rang":2,"apc":{"module":"Vie familiale et intégration sociale","famille":"Vie familiale et intégration sociale","agir":"Analyser les mutations de la famille et adopter des comportements responsables","situation":"Dans ton village, une voisine de 14 ans doit quitter l'école pour se marier ; ses parents disent que c'est la tradition.","tache":"Écris en espagnol un message de 5 phrases pour défendre son droit à l'éducation."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-espagnol-r03",{"duree":20,"titre":"Los comportamientos de riesgo (1)","accroche":"¿Peligro a la vista?","intro":"Drogue, alcool, tabac, violence, fraude : certains comportements mettent en danger la santé et l'avenir des jeunes. On apprend à les identifier, à exprimer la défense (prohibition) et à conjuguer le subjonctif des verbes irréguliers.","objectifs":["identifier les comportements à risque en milieu scolaire et social","exprimer l'interdiction","conjuguer les subjonctifs irréguliers"],"parties":[{"t":"Identificar los riesgos","html":"<div class='def'><b>Définition</b>Un <strong>comportement à risque</strong> (<em>un comportamiento de riesgo</em>) est une conduite qui expose une personne à un danger pour sa santé, sa sécurité ou son avenir.</div><p><em>la droga, el alcohol, el tabaco, la violencia escolar, el acoso, el fraude en los exámenes, las malas compañías, caer en, engancharse a</em>.</p>"},{"t":"La prohibición","verrou":true},{"t":"Subjuntivos irregulares","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"espagnol","rang":3,"apc":{"module":"Vie familiale et intégration sociale","famille":"Vie familiale et intégration sociale","agir":"Analyser les mutations de la famille et adopter des comportements responsables","situation":"Au lycée, des élèves de ta classe vendent des comprimés « pour réviser toute la nuit » avant le Probatoire.","tache":"Rédige en espagnol 5 interdictions pour une affiche de prévention."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-espagnol-r04",{"duree":20,"titre":"Los comportamientos de riesgo (2)","accroche":"Elegir bien.","intro":"Après avoir identifié les risques, il faut sensibiliser : conseiller, proposer, convaincre. On emploie l'impératif affirmatif, la place des pronoms et les verbes de conseil suivis du subjonctif.","objectifs":["sensibiliser à des comportements responsables","employer l'impératif avec les pronoms (enclise)","conseiller avec aconsejar que + subjonctif"],"parties":[{"t":"Sensibilizar","html":"<div class='def'><b>Définition</b><strong>Sensibiliser</strong> (<em>sensibilizar, concienciar</em>), c'est rendre quelqu'un attentif à un problème pour qu'il change de comportement.</div><p><em>una campaña, un eslogan, la prevención, el compañerismo, alejarse de, decir que no, pedir ayuda</em>.</p>"},{"t":"Imperativo y enclisis","verrou":true},{"t":"Aconsejar y pedir","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"espagnol","rang":4,"apc":{"module":"Vie familiale et intégration sociale","famille":"Vie familiale et intégration sociale","agir":"Analyser les mutations de la famille et adopter des comportements responsables","situation":"Le club santé du lycée prépare une campagne contre le harcèlement sur les réseaux sociaux.","tache":"Écris en espagnol 5 conseils à l'impératif, dont deux avec un pronom soudé."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-espagnol-r05",{"duree":20,"titre":"Medio ambiente y cambio climático","accroche":"El planeta se calienta.","intro":"Inondations à Douala, sécheresse dans l'Extrême-Nord : le changement climatique touche le Cameroun. On apprend le vocabulaire du climat, l'expression de la cause et de la conséquence, et le futur.","objectifs":["décrire les effets du changement climatique","exprimer la cause et la conséquence","employer le futur de l'indicatif"],"parties":[{"t":"El cambio climático","html":"<div class='def'><b>Définition</b>Le <strong>changement climatique</strong> (<em>el cambio climático</em>) est la modification durable des températures et des pluies, accélérée par les gaz à effet de serre.</div><p><em>el calentamiento global, la sequía, las inundaciones, la deforestación, los gases de efecto invernadero, la desertificación, reforestar</em>.</p>"},{"t":"Causa y consecuencia","verrou":true},{"t":"Futuro de indicativo","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"espagnol","rang":5,"apc":{"module":"Environnement, santé et bien-être","famille":"Environnement, santé et bien-être","agir":"Protéger l'environnement et promouvoir la santé par la parole et l'écrit","situation":"En août, le quartier Makèpè de Douala a été inondé ; ton correspondant de Séville parle, lui, d'une canicule à 45 °C.","tache":"Écris en espagnol 5 phrases qui comparent les deux situations et annoncent deux conséquences au futur."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-espagnol-r06",{"duree":20,"titre":"La salud y la prevención","accroche":"Más vale prevenir.","intro":"Le paludisme, le choléra, le diabète : beaucoup de maladies se préviennent par l'hygiène et une bonne alimentation. On apprend à donner des conseils de prévention et à exprimer la condition réalisable.","objectifs":["analyser les habitudes favorables à la santé","rédiger un message de prévention","exprimer la condition avec si + présent"],"parties":[{"t":"La prevención","html":"<div class='def'><b>Définition</b>La <strong>prévention</strong> (<em>la prevención</em>) est l'ensemble des mesures prises pour éviter une maladie avant qu'elle n'apparaisse.</div><p><em>el paludismo, el cólera, la diabetes, la vacuna, el mosquitero, lavarse las manos, hervir el agua, contagiar, curarse</em>.</p>"},{"t":"La condición realizable","verrou":true},{"t":"El mensaje de prevención","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"espagnol","rang":6,"apc":{"module":"Environnement, santé et bien-être","famille":"Environnement, santé et bien-être","agir":"Protéger l'environnement et promouvoir la santé par la parole et l'écrit","situation":"Le centre de santé de ton quartier de Garoua constate une hausse des cas de choléra pendant la saison des pluies.","tache":"Rédige en espagnol un message de prévention de 5 phrases avec au moins deux conditions en si."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-espagnol-r07",{"duree":20,"titre":"El deporte y los ocios (1)","accroche":"Mente sana en cuerpo sano.","intro":"Le sport et les loisirs entretiennent la santé du corps et de l'esprit. On évalue leur importance, on apprend le lexique sportif et la comparaison.","objectifs":["évaluer l'importance du sport pour la santé","employer le lexique des sports et des loisirs","comparer avec más… que, menos… que, tan… como"],"parties":[{"t":"Deporte y bienestar","html":"<div class='def'><b>Définition</b>Le <strong>bien-être</strong> (<em>el bienestar</em>) est un état d'équilibre physique, mental et social.</div><p><em>el fútbol, el balonmano, el atletismo, correr, entrenarse, el estrés, el sedentarismo, relajarse, la lectura, la música</em>.</p><p><em>Mente sana en cuerpo sano.</em></p>"},{"t":"La comparación","verrou":true},{"t":"Expresar la frecuencia","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"espagnol","rang":7,"apc":{"module":"Environnement, santé et bien-être","famille":"Environnement, santé et bien-être","agir":"Protéger l'environnement et promouvoir la santé par la parole et l'écrit","situation":"Ta petite sœur passe ses après-midi devant les séries ; elle dit que le sport « fatigue pour rien ».","tache":"Écris-lui en espagnol 5 phrases pour comparer le sport et les écrans et la convaincre."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-espagnol-r08",{"duree":20,"titre":"El deporte y los ocios (2)","accroche":"¡A practicar!","intro":"On encourage la pratique du sport et des loisirs : organiser un tournoi, inviter, raconter un match. On révise le passé composé et le passé simple, et on apprend à les distinguer.","objectifs":["encourager la pratique du sport","distinguer pretérito perfecto et indefinido","raconter un événement sportif"],"parties":[{"t":"Organizar un torneo","html":"<div class='def'><b>Définition</b>Un <strong>tournoi</strong> (<em>un torneo</em>) est une compétition entre plusieurs équipes, par élimination ou en championnat.</div><p><em>el equipo, el árbitro, el gol, ganar, perder, empatar, el campeón, la copa, los aficionados, animar</em>.</p>"},{"t":"Pretérito perfecto e indefinido","verrou":true},{"t":"Invitar y animar","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"espagnol","rang":8,"apc":{"module":"Environnement, santé et bien-être","famille":"Environnement, santé et bien-être","agir":"Protéger l'environnement et promouvoir la santé par la parole et l'écrit","situation":"Ton lycée organise un tournoi de handball inter-classes ; ton équipe a gagné le match d'aujourd'hui, et l'an dernier vous aviez perdu en finale.","tache":"Raconte en espagnol en 5 phrases en employant le perfecto et l'indefinido à bon escient."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-espagnol-r09",{"duree":20,"titre":"Patriotismo y diversidad cultural","accroche":"Camerún, África en miniatura.","intro":"Le Cameroun compte plus de 250 ethnies ; l'Espagne et l'Amérique latine ont aussi leurs cultures régionales. On apprend à présenter un patrimoine, à exprimer la fierté et à employer les relatifs.","objectifs":["découvrir le patrimoine culturel du Cameroun et des pays hispanophones","promouvoir la diversité culturelle","employer les pronoms relatifs que, quien, donde, cuyo"],"parties":[{"t":"El patrimonio cultural","html":"<div class='def'><b>Définition</b>Le <strong>patrimoine culturel</strong> (<em>el patrimonio cultural</em>) est l'ensemble des biens, traditions, langues et arts hérités du passé et transmis aux générations futures.</div><p><em>la etnia, la lengua materna, la danza, el traje tradicional, el Ngondo, el Nguon, el flamenco, la cumbia, el orgullo, la identidad</em>.</p>"},{"t":"Los relativos","html":"<p><strong>que</strong> (personne ou chose) : <em>la fiesta que celebramos</em> ; <strong>quien</strong> (personne, après préposition) : <em>el jefe con quien hablé</em> ; <strong>donde</strong> (lieu) : <em>la ciudad donde nací</em> ; <strong>cuyo/a/os/as</strong> (dont, possession, accordé avec le possédé) : <em>el pueblo cuya fiesta es famosa</em>.</p><div class='attention'><b>Attention</b><em>cuyo</em> s'accorde avec ce qui est possédé, pas avec le possesseur.</div>","labo":{"type":"trier","invite":"Choisis le relatif.","items":[["la casa ___ vivo","donde."],["el amigo con ___ viajo","quien."],["el libro ___ leo","que."],["el autor ___ novelas leo","cuyas."]]}},{"t":"Expresar el orgullo","html":"<p><em>Estoy orgulloso/a de…, me siento camerunés/a, es un honor…, nuestra riqueza es…</em></p>","retenir":"Estar orgulloso de."},{"t":"Vers le Probatoire","html":"<div class='integ'><h3>Compruebo mis conocimientos</h3><p>« El patrimonio cultural » est :</p><ol type='a'><li>l'argent d'une famille riche</li><li>la maison des grands-parents</li><li>ce qu'une société hérite et transmet</li><li>le budget du ministère</li></ol><details><summary>Voir la réponse</summary><p><strong>ce qu'une société hérite et transmet</strong>. Traditions, langues, arts hérités et transmis.</p></details><h3>Competencias lingüísticas (formato del Probatoire)</h3><p>Complète : « Douala es la ciudad ___ se celebra el Ngondo. »</p><details><summary>Voir la réponse</summary><p>(Réponse : donde.)</p></details><h3>Comentario dirigido y producción de textos (formato del Probatoire)</h3><p><strong>Texto.</strong> <em>« El Ngondo es la fiesta del pueblo sawa, que vive en Douala. Los ancianos, cuya sabiduría todos respetan, entran en el río para hablar con los espíritus. Es una tradición de la que los sawa están orgullosos. »</em> (texte : Réalisation VÉRITAS).</p><p><strong>Consigna 1.</strong> Comentario dirigido : ¿Qué es el Ngondo? ¿Qué sentimiento expresan los sawa?</p><p><strong>Consigna 2.</strong> Competencias lingüísticas : completa con que, quien, donde o cuyo : «La ciudad ___ nací» ; «el jefe con ___ hablé» ; «el pueblo ___ fiesta es famosa».</p><p><strong>Consigna 3.</strong> Ensayo libre : presenta una fiesta tradicional de tu región (10 líneas).</p><details><summary>Voir une réponse attendue</summary><p>Es la fiesta del pueblo sawa ; expresan orgullo. Relativos : donde, quien, cuya. Ensayo : presentación con lugar, fecha, ritos, sentimiento de orgullo y al menos dos relativos.</p></details></div>","retenir":"Savoir-être mobilisé : Ouverture et respect d'autrui."}],"revision":["Patrimonio : etnia, lengua, danza, traje, Ngondo, flamenco.","Que, quien, donde ; cuyo s'accorde avec le possédé.","Estoy orgulloso de ; me siento camerunés."],"exo":"<p>Complète : « Douala es la ciudad ___ se celebra el Ngondo. » <em>(Réponse : donde.)</em></p>","quiz":[{"q":"« El patrimonio cultural » est :","r":["l'argent d'une famille riche","la maison des grands-parents","ce qu'une société hérite et transmet","le budget du ministère"],"b":2,"e":"Traditions, langues, arts hérités et transmis."},{"q":"Le Ngondo est une fête :","r":["du peuple bamoun de Foumban","des Peuls de Ngaoundéré","des Baka de l'Est","du peuple sawa de Douala"],"b":3,"e":"Le Ngondo est la fête traditionnelle des Sawa."},{"q":"Complète : « La ciudad ___ nací es Douala. »","r":["donde","quien","cuyo","cual"],"b":0,"e":"Donde = relatif de lieu."},{"q":"Complète : « El jefe con ___ hablé. »","r":["que","quien","donde","cuyo"],"b":1,"e":"Après préposition, pour une personne : quien."},{"q":"« Cuyo » s'accorde avec :","r":["le possesseur","le sujet du verbe","ce qui est possédé","rien, il est invariable"],"b":2,"e":"El pueblo cuya fiesta… : cuya s'accorde avec fiesta."},{"q":"Complète : « El autor ___ novelas leo. »","r":["cuyo","cuya","cuyos","cuyas"],"b":3,"e":"Novelas est féminin pluriel : cuyas."},{"q":"« Estoy orgulloso de » signifie :","r":["je suis fier de","je suis jaloux de","je suis fatigué de","je suis loin de"],"b":0,"e":"Orgulloso = fier."},{"q":"« La lengua materna » est :","r":["la langue étrangère","la langue maternelle","la langue officielle","la langue morte"],"b":1,"e":"Lengua materna = première langue apprise."},{"q":"Complète : « La fiesta ___ celebramos. »","r":["quien","donde","que","cuya"],"b":2,"e":"Que = relatif pour une chose, COD."},{"q":"Le flamenco vient :","r":["de Catalogne","de Galice","des Canaries","d'Andalousie"],"b":3,"e":"Le flamenco est né en Andalousie."}],"c":"1re A","m":"espagnol","rang":9,"apc":{"module":"Citoyenneté","famille":"Citoyenneté","agir":"Valoriser la diversité culturelle et le vivre-ensemble","situation":"Une classe de Bogota, en Colombie, échange avec la tienne et demande de lui faire découvrir une fête traditionnelle camerounaise.","tache":"Présente en espagnol en 5 phrases une fête de ta région avec au moins deux relatifs."},"gratuit":true});
VRT_L("1re-a-espagnol-r10",{"duree":20,"titre":"El mundo rural y el desarrollo local","accroche":"Volver al pueblo.","intro":"L'exode rural vide les villages et surcharge les villes. Développer le monde rural, c'est créer des routes, des écoles, des coopératives. On apprend l'expression du but et l'emploi de para que + subjonctif.","objectifs":["analyser l'exode rural et la mobilité","proposer des solutions de développement local","exprimer le but avec para et para que"],"parties":[{"t":"El éxodo rural","html":"<div class='def'><b>Définition</b>L'<strong>exode rural</strong> (<em>el éxodo rural</em>) est le départ massif des habitants des campagnes vers les villes.</div><p><em>el campo, el pueblo, la ciudad, emigrar, la cooperativa agrícola, la carretera, el cacao, el café, la cosecha, el desarrollo local</em>.</p>"},{"t":"Expresar la finalidad","verrou":true},{"t":"La mobilité","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"espagnol","rang":10,"apc":{"module":"Citoyenneté","famille":"Citoyenneté","agir":"Valoriser la diversité culturelle et le vivre-ensemble","situation":"Dans ton village près de Bafia, les jeunes partent tous à Yaoundé ; le chef veut créer une coopérative de cacao.","tache":"Rédige en espagnol 5 propositions pour retenir les jeunes, avec trois expressions du but."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-espagnol-r11",{"duree":20,"titre":"Identidad, tolerancia y convivencia (1)","accroche":"Diferentes, pero juntos.","intro":"Vivre ensemble suppose d'accepter les différences de langue, de religion, d'origine. On apprend le vocabulaire de la tolérance et l'expression de la concession.","objectifs":["définir la tolérance et le vivre-ensemble","exprimer la concession avec aunque","dénoncer les préjugés"],"parties":[{"t":"La convivencia","html":"<div class='def'><b>Définition</b>La <strong>tolérance</strong> (<em>la tolerancia</em>) est l'attitude qui consiste à respecter les idées, les croyances et les façons de vivre des autres, même quand on ne les partage pas.</div><p><em>el prejuicio, el tribalismo, el racismo, la xenofobia, el respeto, la paz, convivir, aceptar, rechazar, discriminar</em>.</p>"},{"t":"La concesión","verrou":true},{"t":"Denunciar los prejuicios","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"espagnol","rang":11,"apc":{"module":"Citoyenneté","famille":"Citoyenneté","agir":"Valoriser la diversité culturelle et le vivre-ensemble","situation":"Dans ta classe, deux élèves se moquent d'un nouveau venu à cause de son accent et de sa région d'origine.","tache":"Écris en espagnol 5 phrases pour les rappeler au respect, avec aunque et no es verdad que."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-espagnol-r12",{"duree":20,"titre":"Identidad, tolerancia y convivencia (2)","accroche":"Construir la paz.","intro":"Pour construire la paix, il faut dialoguer, négocier et proposer. On apprend le discours rapporté au présent et l'expression de l'accord et du désaccord.","objectifs":["proposer des actions pour le vivre-ensemble","rapporter les paroles d'autrui","exprimer l'accord et le désaccord"],"parties":[{"t":"La paz y el diálogo","html":"<div class='def'><b>Définition</b>Le <strong>vivre-ensemble</strong> (<em>la convivencia</em>) est la capacité de personnes différentes à partager un même espace dans le respect et la paix.</div><p><em>el diálogo, la reconciliación, el conflicto, la mediación, la solidaridad, el bilingüismo, la unidad nacional</em>.</p>"},{"t":"Estilo indirecto (presente)","verrou":true},{"t":"Acuerdo y desacuerdo","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"espagnol","rang":12,"apc":{"module":"Citoyenneté","famille":"Citoyenneté","agir":"Valoriser la diversité culturelle et le vivre-ensemble","situation":"Le délégué de classe rapporte au proviseur une dispute entre élèves anglophones et francophones pendant le match.","tache":"Rédige en espagnol le compte rendu en 5 phrases, au discours indirect, puis donne ton avis."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-espagnol-r13",{"duree":20,"titre":"El turismo y el desarrollo","accroche":"Viajar para descubrir.","intro":"Le Cameroun possède des atouts touristiques : plages de Kribi, mont Cameroun, parc de Waza, chefferies de l'Ouest. On apprend à promouvoir un tourisme durable et à employer le conditionnel de politesse et de suggestion.","objectifs":["analyser le potentiel touristique du Cameroun et des pays hispanophones","promouvoir le tourisme durable","employer le conditionnel"],"parties":[{"t":"El turismo sostenible","html":"<div class='def'><b>Définition</b>Le <strong>tourisme durable</strong> (<em>el turismo sostenible</em>) est un tourisme qui respecte l'environnement et les populations locales tout en créant des revenus.</div><p><em>el paisaje, la playa, el parque nacional, las cataratas de la Lobé, el monte Camerún, el alojamiento, el guía, las divisas, el ecoturismo</em>.</p>"},{"t":"El condicional","verrou":true},{"t":"Promover un destino","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"espagnol","rang":13,"apc":{"module":"Vie économique","famille":"Vie économique","agir":"Promouvoir le tourisme, l'entrepreneuriat et la consommation responsable","situation":"Une agence de voyages de Madrid prépare un circuit au Cameroun et te demande ton avis sur trois sites à visiter.","tache":"Rédige en espagnol en 5 phrases ta recomendación avec trois conditionnels."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-espagnol-r14",{"duree":20,"titre":"Emprendimiento e intercambios comerciales","accroche":"Mi proyecto, mi futuro.","intro":"Créer une petite entreprise est une solution au chômage des jeunes. On apprend à présenter un projet, à parler des échanges commerciaux et à exprimer l'hypothèse avec si + imparfait du subjonctif.","objectifs":["concevoir un projet entrepreneurial simple","analyser des échanges commerciaux","exprimer l'hypothèse irréalisable au présent"],"parties":[{"t":"El proyecto emprendedor","html":"<div class='def'><b>Définition</b>L'<strong>entrepreneuriat</strong> (<em>el emprendimiento</em>) est l'action de créer et de gérer une activité économique en prenant des risques pour en tirer un profit.</div><p><em>el emprendedor, el capital, el préstamo, el beneficio, el cliente, la exportación, la importación, el mercado, invertir, ahorrar</em>.</p>"},{"t":"Imperfecto de subjuntivo","verrou":true},{"t":"Si + imperfecto de subjuntivo","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"espagnol","rang":14,"apc":{"module":"Vie économique","famille":"Vie économique","agir":"Promouvoir le tourisme, l'entrepreneuriat et la consommation responsable","situation":"Ton cousin, titulaire d'un CAP de couture, n'a pas d'emploi ; une microfinance de Bamenda propose des prêts de 300 000 F aux jeunes.","tache":"Rédige en espagnol en 5 phrases son projet, avec deux hypothèses en si + imparfait du subjonctif."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-espagnol-r15",{"duree":20,"titre":"Consumo responsable y ética profesional","accroche":"Comprar con cabeza.","intro":"Acheter local, éviter le gaspillage, refuser la corruption au travail : la consommation responsable et l'éthique concernent chacun. On apprend la voix passive et la tournure se + verbe.","objectifs":["adopter une consommation responsable","parler de l'éthique professionnelle","transformer une phrase passive en active et inversement"],"parties":[{"t":"Consumir con responsabilidad","html":"<div class='def'><b>Définition</b>La <strong>consommation responsable</strong> (<em>el consumo responsable</em>) consiste à acheter selon ses besoins réels, en privilégiant les produits locaux, durables et respectueux de l'environnement.</div><p><em>el despilfarro, los productos locales, la etiqueta, la fecha de caducidad, la corrupción, la honestidad, el soborno, la puntualidad</em>.</p>"},{"t":"La voz pasiva","verrou":true},{"t":"La ética profesional","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"espagnol","rang":15,"apc":{"module":"Vie économique","famille":"Vie économique","agir":"Promouvoir le tourisme, l'entrepreneuriat et la consommation responsable","situation":"Au marché Mokolo, un vendeur propose des boîtes de lait périmées à moitié prix ; un inspecteur lui offre de « fermer les yeux » contre de l'argent.","tache":"Écris en espagnol 5 phrases qui dénoncent ces pratiques, dont deux au passif."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-espagnol-r16",{"duree":20,"titre":"Los medios y la información responsable","accroche":"¿Hecho u opinión?","intro":"Presse, radio, télévision, réseaux sociaux : l'information circule vite, les fausses nouvelles aussi. On apprend à distinguer les faits des opinions et à exprimer l'opinion et le doute.","objectifs":["analyser une information de presse ou des réseaux sociaux","distinguer faits et opinions","exprimer l'opinion et le doute"],"parties":[{"t":"Hechos y opiniones","html":"<div class='def'><b>Définition</b>Un <strong>fait</strong> (<em>un hecho</em>) est une information vérifiable ; une <strong>opinion</strong> (<em>una opinión</em>) est un jugement personnel, discutable.</div><p><em>la prensa, el periódico, el titular, la fuente, el bulo (la noticia falsa), verificar, difundir, las redes sociales, el periodista</em>.</p>"},{"t":"Opinión y duda","html":"<p><em>Creo que / pienso que / me parece que + indicatif</em> ; <em>no creo que / dudo que / no es seguro que + subjonctif</em>. <em>Pienso que es un bulo. No creo que la fuente sea seria.</em></p><div class='attention'><b>Attention</b>la négation du verbe d'opinion entraîne le subjonctif.</div>","labo":{"type":"trier","invite":"Fait ou opinion ?","items":[["Douala tiene un puerto","hecho."],["Douala es la ciudad más bonita","opinión."],["El periódico salió el lunes","hecho."],["Este periodista es malo","opinión."]]}},{"t":"Verificar una noticia","html":"<p>Avant de partager : <em>¿quién lo dice? ¿cuál es la fuente? ¿qué fecha tiene? ¿lo dicen otros medios?</em></p>","retenir":"¿Cuál es la fuente?"},{"t":"Vers le Probatoire","html":"<div class='integ'><h3>Compruebo mis conocimientos</h3><p>Un fait est une information :</p><ol type='a'><li>personnelle</li><li>discutable</li><li>vérifiable</li><li>imaginaire</li></ol><details><summary>Voir la réponse</summary><p><strong>vérifiable</strong>. Un hecho se vérifie ; une opinión se discute.</p></details><h3>Competencias lingüísticas (formato del Probatoire)</h3><p>Complète : « Dudo que esta noticia ___ (ser) verdad. »</p><details><summary>Voir la réponse</summary><p>(Réponse : sea.)</p></details><h3>Comentario dirigido y producción de textos (formato del Probatoire)</h3><p><strong>Texto.</strong> <em>« Un mensaje dice que el agua salada cura el paludismo. Miles de personas lo compartieron. Un médico de Yaundé respondió: «No creo que esta información sea seria. No hay ninguna fuente». »</em> (texte : Réalisation VÉRITAS).</p><p><strong>Consigna 1.</strong> Comentario dirigido : ¿Es un hecho o una opinión? Justifica con la respuesta del médico.</p><p><strong>Consigna 2.</strong> Competencias lingüísticas : completa : «Pienso que (ser) un bulo» ; «Dudo que la noticia (ser) verdad».</p><p><strong>Consigna 3.</strong> Ensayo semi-guiado : explica en cinco consejos cómo reconocer una noticia falsa.</p><details><summary>Voir une réponse attendue</summary><p>Es una información falsa (un bulo) : no hay fuente, dice el médico. Completa : es ; sea. Consejos : buscar la fuente, la fecha, comparar con otros medios, desconfiar de los títulos alarmistas, no compartir sin verificar.</p></details></div>","retenir":"Savoir-être mobilisé : Rigueur et méthode."}],"revision":["Medios : prensa, titular, fuente, bulo, verificar, difundir.","Creo que + indicatif ; no creo que / dudo que + subjonctif.","Vérifier : fuente, fecha, otros medios."],"exo":"<p>Complète : « Dudo que esta noticia ___ (ser) verdad. » <em>(Réponse : sea.)</em></p>","quiz":[{"q":"Un fait est une information :","r":["personnelle","discutable","vérifiable","imaginaire"],"b":2,"e":"Un hecho se vérifie ; une opinión se discute."},{"q":"« Douala es la ciudad más bonita » est :","r":["un fait","une source","un titre","une opinion"],"b":3,"e":"C'est un jugement personnel."},{"q":"« Un bulo » est :","r":["une fausse nouvelle","un vrai reportage","un journal papier","un journaliste"],"b":0,"e":"Bulo = fake news."},{"q":"Complète : « Dudo que la noticia ___ verdad. »","r":["es","sea","está","será"],"b":1,"e":"Dudar que + subjonctif."},{"q":"Complète : « Pienso que ___ un bulo. »","r":["sea","fuera","es","esté"],"b":2,"e":"Pensar que (affirmatif) + indicatif."},{"q":"« No creo que » est suivi :","r":["de l'indicatif","de l'infinitif","du conditionnel","du subjonctif"],"b":3,"e":"La négation du verbe d'opinion entraîne le subjonctif."},{"q":"« La fuente » d'une information est :","r":["son origine","son titre","sa date","sa longueur"],"b":0,"e":"Fuente = source."},{"q":"« Difundir » signifie :","r":["défendre","diffuser","différer","diminuer"],"b":1,"e":"Difundir = répandre."},{"q":"« El titular » est :","r":["le nom du journaliste","le prix du journal","le titre d'un article","la photo principale"],"b":2,"e":"Titular = gros titre."},{"q":"Avant de partager une information, il faut :","r":["l'envoyer vite à tous","ajouter une opinion","changer la date","vérifier la source"],"b":3,"e":"Verificar avant de difundir."}],"c":"1re A","m":"espagnol","rang":16,"apc":{"module":"Les mass médias et communication","famille":"Médias et communication","agir":"S'informer, communiquer et correspondre avec responsabilité","situation":"Un message WhatsApp affirme que « l'eau salée guérit le paludisme » et circule dans le groupe de ta classe.","tache":"Rédige en espagnol en 5 phrases ta réponse au groupe : fait ou opinion, doute, conseil."},"gratuit":true});
VRT_L("1re-a-espagnol-r17",{"duree":20,"titre":"Tecnologías digitales y comunicación","accroche":"Conectados, pero prudentes.","intro":"Le téléphone et internet facilitent les études et la communication, mais exposent aux arnaques, à la dépendance et au cyberharcèlement. On évalue ces risques et on emploie la tournure d'obligation et l'imparfait.","objectifs":["évaluer les risques des technologies numériques","proposer des comportements responsables","comparer hier et aujourd'hui avec l'imparfait"],"parties":[{"t":"Lo digital","html":"<div class='def'><b>Définition</b>Les <strong>technologies numériques</strong> (<em>las tecnologías digitales</em>) sont les outils qui traitent et transmettent l'information sous forme de données : ordinateur, téléphone, internet.</div><p><em>el móvil, la contraseña, la estafa, la adicción, el ciberacoso, descargar, navegar, conectarse, los datos personales</em>.</p>"},{"t":"Pretérito imperfecto","verrou":true},{"t":"Comportamientos responsables","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"espagnol","rang":17,"apc":{"module":"Les mass médias et communication","famille":"Médias et communication","agir":"S'informer, communiquer et correspondre avec responsabilité","situation":"Ton grand-père raconte que, de son temps, on attendait une lettre trois semaines ; ton petit frère, lui, a donné son mot de passe Mobile Money à un inconnu.","tache":"Écris en espagnol 5 phrases : comparaison avant / maintenant, puis deux conseils de sécurité."},"verrou":true,"nq":10,"labo":true});
VRT_L("1re-a-espagnol-r18",{"duree":20,"titre":"La correspondencia","accroche":"Querido amigo, estimado señor.","intro":"Lettre privée, lettre officielle, courriel : chaque correspondance a ses formules. On apprend à rédiger une lettre selon le destinataire, au Probatoire comme dans la vie.","objectifs":["rédiger différents types de correspondance","choisir les formules d'appel et de congé","employer le registre adapté"],"parties":[{"t":"Tipos de cartas","html":"<div class='def'><b>Définition</b>Une <strong>correspondance</strong> (<em>la correspondencia</em>) est un échange de lettres ou de messages écrits entre des personnes ou des institutions.</div><p>Lettre <strong>privée</strong> (ami, famille), lettre <strong>officielle</strong> (administration, entreprise), <strong>courriel</strong> (<em>el correo electrónico</em>) : <em>el remitente, el destinatario, el asunto, la firma, la posdata</em>.</p>"},{"t":"Fórmulas","verrou":true},{"t":"Estructura","verrou":true},{"t":"Vers le Probatoire","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"1re A","m":"espagnol","rang":18,"apc":{"module":"Les mass médias et communication","famille":"Médias et communication","agir":"S'informer, communiquer et correspondre avec responsabilité","situation":"Tu veux faire un stage de vacances à l'office du tourisme de Kribi et tu écris aussi à ton ami de Malabo pour lui raconter ton projet.","tache":"Rédige en espagnol la lettre officielle de demande de stage (8 lignes), avec les formules adaptées."},"verrou":true,"nq":10,"labo":true});
